#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure to represent a cell measurement report
typedef struct {
    int cellId;
    float rsrp;
    float rsrq;
} CellMeasurementReport;

// Data structure to store and manage reports
typedef struct {
    CellMeasurementReport* reports;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ReportManager;

// Create a new report manager with the given initial capacity
ReportManager* createReportManager(size_t initialCapacity) {
    ReportManager* manager = (ReportManager*)malloc(sizeof(ReportManager));
    manager->reports = (CellMeasurementReport*)calloc(initialCapacity, sizeof(CellMeasurementReport));
    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Add a new report to the manager
void addReport(ReportManager* manager, int cellId, float rsrp, float rsrq) {
    if (manager->count >= manager->capacity) {
        // If the manager is full, double its capacity and resize the reports array
        size_t newCapacity = manager->capacity * 2;
        CellMeasurementReport* newReports = (CellMeasurementReport*)realloc(manager->reports, newCapacity * sizeof(CellMeasurementReport));
        manager->reports = newReports;
        manager->capacity = newCapacity;
    }
    manager->reports[manager->count].cellId = cellId;
    manager->reports[manager->count].rsrp = rsrp;
    manager->reports[manager->count].rsrq = rsrq;
    manager->count++;
}

// Update an existing report in the manager
void updateReport(ReportManager* manager, int cellId, float newRsrp, float newRsrq) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i].cellId == cellId) {
            manager->reports[i].rsrp = newRsrp;
            manager->reports[i].rsrq = newRsrq;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Remove a report from the manager
void removeReport(ReportManager* manager, int cellId) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i].cellId == cellId) {
            // Shift remaining reports up and truncate the array
            memmove(&manager->reports[i], &manager->reports[i + 1], (manager->count - i - 1) * sizeof(CellMeasurementReport));
            manager->count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Calculate the average signal quality for a specific cell
void getAverageSignalQuality(ReportManager* manager, int cellId, float* rsrpAvg, float* rsrqAvg) {
    pthread_mutex_lock(&manager->lock);
    size_t count = 0;
    float sumRsrp = 0.0f;
    float sumRsrq = 0.0f;
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->reports[i].cellId == cellId) {
            sumRsrp += manager->reports[i].rsrp;
            sumRsrq += manager->reports[i].rsrq;
            count++;
        }
    }
    *rsrpAvg = count > 0 ? sumRsrp / count : 0.0f;
    *rsrqAvg = count > 0 ? sumRsrq / count : 0.0f;
    pthread_mutex_unlock(&manager->lock);
}

// Free the report manager and its resources
void freeReportManager(ReportManager* manager) {
    if (manager != NULL) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->reports);
        free(manager);
    }
}
