#define BUFFER_SIZE 1024

int main() {
    // Initialize configuration file parsing
    FILE *config_file = fopen("config.json", "r");
    json_object *config_json = json_load_file(config_file, 0);
    fclose(config_file);

    // Initialize message broker connection
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(9092);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr));

    // Initialize log processing threads
    pthread_t *threads = malloc(NUM_THREADS * sizeof(pthread_t));
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, process_log_entries, NULL);
    }

    // Process log entries in parallel
    while (1) {
        char buffer[BUFFER_SIZE];
        int bytes_read = read(sock, buffer, BUFFER_SIZE);
        if (bytes_read <= 0) break;
        process_log_entry(buffer, bytes_read);
    }

    // Close message broker connection and threads
    close(sock);
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);

    // Clean up configuration file parsing
    json_object_put(config_json);
    return 0;
}

