#include <arpa/inet.h>
#include <pthread.h>

#define MAX_FILE_SIZE (1*1024*1024*1024)
#define MAX_NETWORK_STREAM 1000

// Define a struct to hold the unique integer value
typedef struct {
    int value;
    int is_unique;
} UniqueValue;

// Function to read data from file
void* read_file_data(void* arg) {
    FILE* file = (FILE*)arg;
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    // Read the file chunk by chunk
    char buffer[1024];
    int bytesRead;
    UniqueValue unique_value;
    int max_unique_value = INT_MIN;

    while ((bytesRead = fread(buffer, 1, 1024, file)) > 0) {
        for (int i = 0; i < bytesRead; i++) {
            // Convert integer to binary and check for uniqueness
            unsigned char* c = (unsigned char*)&buffer[i];
            int value = *(int*)c;
            if (value > max_unique_value) {
                max_unique_value = value;
            }
        }
    }

    return &unique_value;
}

// Function to read data from network stream
void* read_network_stream_data(void* arg) {
    int socket = *((int*)arg);
    UniqueValue unique_value;

    // Read the network stream chunk by chunk
    char buffer[1024];
    int bytesRead;
    while ((bytesRead = recv(socket, buffer, 1024, 0)) > 0) {
        for (int i = 0; i < bytesRead; i++) {
            // Convert integer to binary and check for uniqueness
            unsigned char* c = (unsigned char*)&buffer[i];
            int value = *(int*)c;
            if (value > unique_value.value) {
                unique_value.value = value;
                unique_value.is_unique = 1;
            }
        }
    }

    return &unique_value;
}

// Function to process data from file and network stream
void* process_data(void* arg) {
    UniqueValue unique_values[2];

    // Create a thread pool for reading file and network stream concurrently
    pthread_t threads[2];
    void* result;

    // Read file and network stream simultaneously
    pthread_create(&threads[0], NULL, read_file_data, (void*)stdin);
    pthread_create(&threads[1], NULL, read_network_stream_data, (void*)&socket);

    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], &result);
    }

    return result;
}

// Function to print the highest unique value
void print_highest_unique_value(void* arg) {
    UniqueValue unique_values[2] = *((UniqueValue*)arg);

    // Check if we have at least one valid input
    int is_file_valid = (unique_values[0].value != INT_MIN);
    int is_network_stream_valid = (unique_values[1].value != INT_MIN);

    // Compare the highest values from both inputs
    int max_value = unique_values[0].value;
    if (is_network_stream_valid && (max_value < unique_values[1].value)) {
        max_value = unique_values[1].value;
    }

    printf("Highest unique value: %d\n", max_value);
}

int main() {
    FILE* file = fopen("data.txt", "rb");
    int socket = socket(AF_INET, SOCK_STREAM, 0);

    // Initialize thread pool and process data concurrently
    pthread_t threads[2];
    void* result;
    pthread_create(&threads[0], NULL, read_file_data, (void*)file);
    pthread_create(&threads[1], NULL, read_network_stream_data, (void*)&socket);

    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], &result);
    }

    // Print the highest unique value
    print_highest_unique_value(result);

    return 0;
}
