import logging
import time
import os
import json
from threading import Lock

class LoggingSubsystem:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

        # Set up log file handlers
        self.log_file_handler = None

        # Initialize the lock for thread safety
        self.lock = Lock()

        # Load configuration from environment variables and a config file
        self.config = {
            'log_format': os.environ.get('LOG_FORMAT', 'plain_text'),
            'log_file_path': os.environ.get('LOG_FILE_PATH', '/var/log/service.log'),
            'log_file_max_size': int(os.environ.get('LOG_FILE_MAX_SIZE', 10*1024*1024)),
            'log_file_rotation_interval': int(os.environ.get('LOG_FILE_ROTATION_INTERVAL', 60)),
            'flush_log_entries': bool(os.environ.get('FLUSH_LOG_ENTRIES', True)),
            'trace_log_entries': bool(os.environ.get('TRACE_LOG_ENTRIES', False))
        }

        # Set up the log file handler based on the configuration
        if self.config['log_file_path']:
            self.log_file_handler = logging.FileHandler(self.config['log_file_path'])
            self.log_file_handler.setLevel(logging.INFO)
            self.logger.addHandler(self.log_file_handler)

    def log_message(self, message):
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        log_entry = f"[{timestamp}] [{os.environ.get('SERVICE_ID', 'Unknown')}]: {message}"

        # Handle different log formats
        if self.config['log_format'] == 'json':
            try:
                with open(self.config['log_file_path'], 'a') as f:
                    json.dump(log_entry, f)
                    f.write('\n')
            except Exception as e:
                print(f"Error writing to log file: {e}")

        else:
            self.logger.info(log_entry)

    def flush_log_entries(self):
        if not self.config['flush_log_entries']:
            return

        try:
            # Flush log entries
            self.log_file_handler.flush()
        except Exception as e:
            print(f"Error flushing log entries: {e}")

    def rotate_log_files(self):
        if not os.path.exists(self.config['log_file_path']):
            return

        file_size = os.path.getsize(self.config['log_file_path'])

        if file_size > self.config['log_file_max_size']:
            try:
                # Rotate the log file
                with open(self.config['log_file_path'], 'r') as f:
                    content = f.read()
                with open(f"{self.config['log_file_path']}.bak", 'w') as f:
                    f.write(content)
            except Exception as e:
                print(f"Error rotating log file: {e}")

        if time.time() - os.path.getmtime(self.config['log_file_path']) > self.config['log_file_rotation_interval']:
            try:
                # Rotate the log file
                with open(self.config['log_file_path'], 'r') as f:
                    content = f.read()
                with open(f"{self.config['log_file_path']}.bak", 'w') as f:
                    f.write(content)
            except Exception as e:
                print(f"Error rotating log file: {e}")

    def trace_log_entry(self, message):
        if not self.config['trace_log_entries']:
            return

        try:
            with open('log_traces.txt', 'a') as f:
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_entry = f"[{timestamp}] [{os.environ.get('SERVICE_ID', 'Unknown')}]: {message}\n"
                f.write(log_entry)
        except Exception as e:
            print(f"Error tracing log entry: {e}")

    def handle_log_file_locking(self):
        try:
            if os.path.exists(self.config['log_file_path']):
                with open(self.config['log_file_path'], 'a') as f:
                    pass
        except Exception as e:
            print(f"Error handling log file locking: {e}")
