        } else if (json_object_get(cipher_config, "CFB")) {
            // Handle CFB encryption/decryption
        }

        // Log the encryption/decryption activity
        fprintf(log_file, "Encrypted/Decrypted %d bytes of data\n", bytes_read);

        // Send the encrypted/decrypted data back to the client
        write(conn_fd, buffer, bytes_read);
    }

    close(conn_fd);
    close(sock_fd);
    json_decref(cipher_config);
    fclose(log_file);

    return 0;
}
