#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <pthread.h>

// Function prototypes
void *load_cipher(const char* cipher_name);
int (*cipher_encrypt)(const void *in, size_t in_len, void *out);
int (*cipher_decrypt)(const void *in, size_t in_len, void *out);

// Configuration structure to hold cryptographic settings
typedef struct {
    int key_size;
    int block_size;
    size_t buffer_size;
} config_t;

// Thread-safe static variable to store the loaded cipher
static pthread_mutex_t cipher_lock = PTHREAD_MUTEX_INITIALIZER;
static void *cipher_handle = NULL;

void load_cipher(const char* cipher_name) {
    // Load the requested cipher using dlopen() and dlsym()
    void *handle = dlopen(cipher_name, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading cipher: %s\n", dlerror());
        return;
    }

    int (*cipher_init)(void *ctx);
    cipher_init = (int (*)(void *))dlsym(handle, "cipher_init");
    if (cipher_init == NULL || !cipher_init(cipher_handle)) {
        fprintf(stderr, "Error initializing cipher: %s\n", dlerror());
        return;
    }

    // Get the cipher's encrypt and decrypt functions
    cipher_encrypt = (int (*)(const void *in, size_t in_len, void *out))dlsym(handle, "cipher_encrypt");
    cipher_decrypt = (int (*)(const void *in, size_t in_len, void *out))dlsym(handle, "cipher_decrypt");

    if (!cipher_encrypt || !cipher_decrypt) {
        fprintf(stderr, "Error loading cipher functions: %s\n", dlerror());
        return;
    }

    // Lock and store the loaded cipher handle
    pthread_mutex_lock(&cipher_lock);
    cipher_handle = handle;
    pthread_mutex_unlock(&cipher_lock);

    printf("Loaded cipher '%s' successfully.\n", cipher_name);
}

// Asynchronous wrapper function for cryptographic operations
int async_cipher_op(int (*cipher_func)(const void *in, size_t in_len, void *out), const void *in, size_t in_len, void *out) {
    // Create a new thread to perform the asynchronous operation
    pthread_t thread;
    pthread_create(&thread, NULL, (void *)cipher_func, out);
    pthread_join(thread, NULL);

    return 0;
}

int main() {
    // Load and initialize the cipher
    load_cipher("libaes.so");

    // Perform a cryptographic operation in synchronous mode
    int result = cipher_encrypt(NULL, 0, NULL);
    printf("Synchronous encryption result: %d\n", result);

    // Perform a cryptographic operation in asynchronous mode
    async_cipher_op(cipher_encrypt, NULL, 0, NULL);

    return 0;
}
