#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

// Define the maximum number of concurrent requests
#define MAX_CONCURRENT_REQUESTS 500

// Define the structure for a request
typedef struct {
    int id;
    pthread_mutex_t* lock;
} Request;

// Function to handle a request
void* handleRequest(void* req) {
    // Get the request and lock from the void pointer
    Request* r = (Request*)req;
    pthread_mutex_lock(r->lock);

    // Process the request
    printf("Handling request %d\n", r->id);

    // Release the lock
    pthread_mutex_unlock(r->lock);

    return NULL;
}

// Function to create a new semaphore
pthread_mutex_t* createSemaphore() {
    pthread_mutex_t* sem = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    pthread_mutex_init(sem, NULL);
    return sem;
}

int main() {
    // Create the semaphore for concurrent requests
    pthread_mutex_t* requestSem = createSemaphore();

    // Create an array of request structures
    Request* requests[MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        requests[i] = malloc(sizeof(Request));
        requests[i]->id = i;
        requests[i]->lock = requestSem;
    }

    // Create threads to handle the requests
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_create(&threads[i], NULL, handleRequest, &requests[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

