#include <forward_list>
#include <functional>

void insertOrLog(std::forward_list<std::string>& actions,
                  const std::string& targetAction,
                  const std::string& newAction,
                  const std::function<void(const std::string&)>& errorLogger) {
    bool actionFound = false;
    for (auto it = actions.begin(); it != actions.end(); ++it) {
        if (*it == targetAction) {
            actions.insert_after(it, newAction);
            actionFound = true;
            break;
        }
    }
    if (!actionFound) {
        std::string logMessage = "Target action '" + targetAction +
                                 "' not found in the list. New action will be appended.";
        errorLogger(logMessage);
        actions.push_back(newAction);
    }
}
