using System.Xml.Linq;

namespace XmlConfigService
{
    public enum CacheEvictionPolicy { Lru, Fifo }

    public class XmlConfigService : IXmlConfigService
    {
        private readonly ILogger _logger;
        private readonly HttpClient _httpClient;
        private readonly Dictionary<string, XDocument> _xmlCache;
        private readonly CacheEvictionPolicy _evictionPolicy;

        public XmlConfigService(ILogger logger, HttpClient httpClient, int cacheSize = 1000, CacheEvictionPolicy evictionPolicy = CacheEvictionPolicy.Lru)
        {
            _logger = logger;
            _httpClient = httpClient;
            _xmlCache = new Dictionary<string, XDocument>(new DictionaryComparer<StringComparer>());
            _evictionPolicy = evictionPolicy;

            // Initialize cache with initial capacity and eviction policy
            _xmlCache = new Dictionary<string, XDocument>(_xmlCache.Count);
        }

        public async Task<XDocument> GetXmlConfigAsync(string xmlConfigId)
        {
            if (!_xmlCache.ContainsKey(xmlConfigId))
                await LoadXmlConfigAsync(xmlConfigId);

            return _xmlCache[xmlConfigId];
        }

        private async Task LoadXmlConfigAsync(string xmlConfigId)
        {
            try
            {
                // Fetch XML from external API or local storage
                byte[] xmlData = await DownloadXmlDataAsync(xmlConfigId);
                XDocument xmlDoc = XDocument.Parse(Encoding.UTF8.GetString(xmlData));

                // Validate XML against schema using external API
                string schemaUrl = GetSchemaUrl(xmlConfigId);
                HttpResponseMessage response = await _httpClient.GetAsync(schemaUrl);

                if (response.IsSuccessStatusCode)
                {
                    // Cache and validate XML
                    _xmlCache[xmlConfigId] = xmlDoc;
                }
                else
                {
                    // Log error and handle cache miss
                    _logger.LogError($"Failed to load schema for {xmlConfigId}: {response.StatusCode}");
                    await RefreshCachedXmlAsync(xmlConfigId);
                }
            }
            catch (Exception ex)
            {
                // Log error and retry if necessary
                _logger.LogError("Error loading XML config: " + ex.Message);

                // Retry up to 3 times with exponential backoff
                for (int i = 0; i < 3 && !(_xmlCache.ContainsKey(xmlConfigId)); i++)
                    await Task.Delay(Math.Pow(2, i), CancellationToken.None);
            }
        }

        private async Task RefreshCachedXmlAsync(string xmlConfigId)
        {
            // Refresh cache by re-downloading and parsing XML
            XDocument xmlDoc = await LoadXmlConfigAsync(xmlConfigId);
            _xmlCache[xmlConfigId] = xmlDoc;
        }

        public void SetCacheSettings(int maxSize, CacheEvictionPolicy policy)
        {
            // Update cache size and eviction policy
            _xmlCache = new Dictionary<string, XDocument>(maxSize, true, policy);
        }
    }

    internal class DictionaryComparer<T> : IEqualityComparer<string>
    {
        public bool Equals(string x, string y) => string.Equals(x, y);

        public int GetHashCode(string obj) => obj.GetHashCode();
    }
}
