public class PasswordUpdateService : IPasswordUpdateService
{
    private readonly UserManager<IdentityUser> _userManager;

    public PasswordUpdateService(UserManager<IdentityUser> userManager)
    {
        _userManager = userManager;
    }

    public async Task<IActionResult> UpdatePassword(string userId, string oldPassword, string newPassword)
    {
        var user = await _userManager.FindByIdAsync(userId);
        if (user == null)
            return NotFound();

        try
        {
            await _userManager.UpdatePasswordAsync(user, oldPassword, newPassword);
        }
        catch (OptimisticConcurrencyException ex)
        {
            // Handle concurrency conflict
            await _userManager.RollbackUpdatePasswordAsync(user);
            return Conflict(ex.Message);
        }

        return Ok("Password updated successfully");
    }
}

