const fs = require('fs');
const path = require('path');
const MetadataService = require('./metadata-service');

class FileFilter {
  async filterFiles(directoryPath, extensionPattern) {
    const metadataService = new MetadataService();
    const fileNames = [];

    try {
      await fs.readdir(directoryPath);
      for (const fileName of await fs.readdir(directoryPath)) {
        if (!path.extname(fileName).includes(extensionPattern)) continue;
        try {
          const fileMetadata = await metadataService.validateFileContents(
            path.join(directoryPath, fileName)
          );
          if (fileMetadata.valid) {
            fileNames.push(fileName);
          }
        } catch (error) {
          console.error(`Error validating file ${fileName}:`, error);
        }
      }
    } catch (error) {
      console.error(`Error reading directory ${directoryPath}:`, error);
    }

    return fileNames;
  }
}

class MetadataService {
  async validateFileContents(filePath) {
    // Implement your external metadata service logic here
    // For demonstration purposes, assume it's a simple validation process
    const content = await fs.readFile(filePath, 'utf8');
    if (content.includes('invalid data')) {
      return { valid: false };
    }
    return { valid: true };
  }
}

class FileFilterController {
  async getFiles(directoryPath, extensionPattern) {
    try {
      const fileFilter = new FileFilter();
      const fileNames = await fileFilter.filterFiles(directoryPath, extensionPattern);
      return fileNames;
    } catch (error) {
      console.error('Error retrieving files:', error);
      return [];
    }
  }
}

