    private static final String LOG_FORMAT = "timestamp:%s, request_uri:%s, status_code:%d";

    public static void processLogs(Iterator<LogEntry> logs) {
        Map<Integer, Integer> statusCodeCounts = new HashMap<>();
        Map<String, Integer> requestUriCounts = new HashMap<>();

        int failedRequests = 0;
        long lastThresholdUpdate = System.currentTimeMillis();

        while (logs.hasNext()) {
            LogEntry logEntry = logs.next();
            if (!isValidLogEntry(logEntry)) continue;

            String requestUri = logEntry.getRequestUri();
            int statusCode = logEntry.getStatusCode();

            if (statusCode >= 400 && statusCode < 600) {
                failedRequests++;

                // Update counts
                statusCodeCounts.computeIfPresent(statusCode, (k, v) -> v + 1);
                requestUriCounts.merge(requestUri, 1, Integer::sum);

                // Check for threshold updates
                long now = System.currentTimeMillis();
                if (now - lastThresholdUpdate > 60 * 1000) { // 1 minute
                    updateThresholds(statusCodeCounts, failedRequests);
                    lastThresholdUpdate = now;
                }
            }

            // Send logs to analytics service
            sendLogsToAnalytics(logEntry);

            // Handle request Uri with most frequent requests
            String mostFrequentRequestUri = getMostFrequentRequestUri(requestUriCounts);
            handleMostFrequentRequest(mostFrequentRequestUri, failedRequests);
        }
    }

    private static boolean isValidLogEntry(LogEntry logEntry) {
        return logEntry != null && logEntry.getRequestUri() != null;
    }

