function renderScripts(scripts) {
  const scriptElems = [];
  const logErrors = (err) => console.error(err.stack || err);

  scripts.forEach((script) => {
    try {
      if (!script.key || !script.code) throw new Error('Script object missing key or code');
      if (script.key.length > 10) throw new Error('Key exceeds maximum length');

      const minifiedCode = /* your minification library */.minify(script.code);
      if (!minifiedCode) throw new Error('Failed to minify script');

      const scriptElem = document.createElement('script');
      scriptElem.id = script.key;
      scriptElem.innerHTML = minifiedCode;
      scriptElems.push(scriptElem);
    } catch (err) {
      logErrors(err);
    }
  });

  const footer = document.querySelector('#footer');
  if (!footer) throw new Error('Footer element not found');

  footer.innerHTML = '';
  scriptElems.forEach((script) => footer.appendChild(script));

  return footer.innerHTML;
}
