int copy_data_into_new_buffer(void** data_chunks, size_t num_chunks, size_t bytes_to_copy, uint8_t** new_buffer) {
    size_t i;
    *new_buffer = malloc(bytes_to_copy);
    if (*new_buffer == NULL) {
        return -1; // Memory allocation failed
    }
    for (i = 0; i < num_chunks && i * BUFFER_SIZE <= bytes_to_copy; i++) {
        memcpy((*new_buffer) + (i * BUFFER_SIZE), data_chunks[i], BUFFER_SIZE);
    }
    if (i * BUFFER_SIZE < bytes_to_copy) {
        size_t remaining_bytes = bytes_to_copy - (i * BUFFER_SIZE);
        memcpy((*new_buffer) + (i * BUFFER_SIZE), data_chunks[i], remaining_bytes);
    }
    return 0;
}

int main() {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        return -1; // Socket creation failed
    }

    configuration_file_t* config_files = malloc(MAX_CONFIGURATION_FILES * sizeof(configuration_file_t));
    if (config_files == NULL) {
        close(sock); // Free resources before exiting
        return -1;
    }

    int num_config_files = load_configuration_files(sock, MAX_CONFIGURATION_FILES);
    if (num_config_files < 0) {
        free(config_files);
        close(sock);
        return -1; // Load configuration files failed
    }

    // Parse the loaded configuration files
    for (int i = 0; i < num_config_files; i++) {
        int ret = parse_configuration_file(config_files[i].filename, config_files[i].version);
        if (ret < 0) {
            break;
        }
    }

    free(config_files);

    // Example usage of the copy_data_into_new_buffer function
    void* data_chunks[] = {(void*) "Hello", (void*) " World!"};
    uint8_t* new_buffer;
    size_t bytes_to_copy = strlen((char*)data_chunks[0]) + strlen((char*)data_chunks[1]) + 2; // Include the null-terminating character
    int ret = copy_data_into_new_buffer(data_chunks, sizeof(data_chunks) / sizeof(void*), bytes_to_copy, &new_buffer);
    if (ret < 0) {
        free(new_buffer);
    } else {
        printf("%s\n", (char*)new_buffer);
        free(new_buffer);
    }

    close(sock);
    return 0;
}
