// modules.js
const express = require('express');
const app = express();
const fetch = require('node-fetch');

let modulesCache = {};

app.get('/modules', async (req, res) => {
  try {
    const response = await fetch('https://api.registry.com/modules');
    const data = await response.json();

    // Load and execute each module
    for (const module of data.modules) {
      if (!modulesCache[module.name]) {
        modulesCache[module.name] = {};
        try {
          const moduleCode = await loadModule(module);
          moduleCode();
        } catch (error) {
          console.error(`Error loading module ${module.name}:`, error);
          res.status(500).send({ message: `Failed to load module ${module.name}` });
        }
      }

      // Handle circular dependencies
      if (module.dependencies && Array.isArray(module.dependencies)) {
        for (const dep of module.dependencies) {
          await loadModule(dep);
        }
      }

      res.send({ modules: data.modules });
    }
  } catch (error) {
    console.error('Error fetching module metadata:', error);
    res.status(500).send({ message: 'Failed to fetch module metadata' });
  }
});

// loadModule.js
const fs = require('fs');
const path = require('path');

async function loadModule(moduleInfo) {
  try {
    const modulePath = `./modules/${moduleInfo.name}/index.js`;
    if (!fs.existsSync(modulePath)) {
      throw new Error(`Module ${moduleInfo.name} not found`);
    }

    const moduleCode = await fs.readFile(modulePath, 'utf8');
    return new Function('return ' + moduleCode)(); // execute the module
  } catch (error) {
    console.error(`Error loading module ${moduleInfo.name}:`, error);
    throw error;
  }
}

// main.js
const express = require('express');
const app = express();
const modules = require('./modules');

app.use(express.json());
app.use('/modules', modules);

app.listen(3000, () => {
  console.log('Module loader started on port 3000');
});
