import java.util.HashMap;
import java.util.Map;

public class DisjointPairCounter {
    public static void main(String[] args) throws Exception {
        Map<Integer, Integer> disjointPairs = new HashMap<>();
        long start = System.currentTimeMillis();
        try (ApiConnection api = new ApiConnection()) {
            int[] array = Arrays.stream(args).mapToInt(Integer::parseInt).toArray();
            for (int i : array) {
                union(i, disjointPairs);
            }
            long end = System.currentTimeMillis();
            logProcessingDuration(end - start, "DisjointPairCounter");
        } catch (Exception e) {
            logError(e.getMessage(), "DisjointPairCounter");
        }
    }

    private static void union(int x, Map<Integer, Integer> disjointPairs) {
        int rootX = find(x, disjointPairs);
        for (Map.Entry<Integer, Integer> entry : disjointPairs.entrySet()) {
            if (!entry.getKey().equals(rootX)) {
                if (find(entry.getKey(), disjointPairs).equals(rootX)) {
                    disjointPairs.put(entry.getKey(), rootX);
                } else {
                    union(rootX, entry.getKey(), disjointPairs);
                }
            }
        }
    }

    private static int find(int x, Map<Integer, Integer> disjointPairs) {
        if (!disjointPairs.containsKey(x)) {
            disjointPairs.put(x, x);
        }
        return disjointPairs.getOrDefault(x, x);
    }

    private static void union(int rootX, int y, Map<Integer, Integer> disjointPairs) {
        int rootY = find(y, disjointPairs);
        disjointPairs.put(rootY, rootX);
    }

    private interface ApiConnection {
        void log(String message);

        default void log(String message) throws Exception {
            // Implement API connection logic here
        }
    }
}

