import java.nio.channels.AsynchronousSocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class ModularMessagingService {
    private static final int DEFAULT_CONNECTION_POOL_SIZE = 10;
    private static final int MAX_RETRIES = 5;
    private static final long CONNECTION_TIMEOUT_MILLIS = 10000L; // 10 seconds

    private AsynchronousChannelGroup channelGroup;
    private List<AsynchronousServerSocketChannel> serverSockets;
    private BlockingQueue<AsynchronousSocketChannel> availableConnections;
    private MessagingBrokerClient messagingBrokerClient;

    public ModularMessagingService(int connectionPoolSize, int maxThreads) {
        this.channelGroup = new AsynchronousChannelGroup(maxThreads);
        this.serverSockets = new ArrayList<>();
        this.availableConnections = new LinkedBlockingQueue<>();
        for (int i = 0; i < connectionPoolSize; i++) {
            AsynchronousServerSocketChannel serverSocket = openServerSocket();
            serverSockets.add(serverSocket);
            AsynchronousSocketChannel channel = acceptConnection(serverSocket);
            availableConnections.add(channel);
        }
    }

    public void start() throws IOException {
        // Start accepting incoming connections
        for (AsynchronousServerSocketChannel serverSocket : serverSockets) {
            serverSocket.accept(null, (future -> {
                try {
                    AsynchronousSocketChannel channel = future.get();
                    // Handle incoming connection and process messages asynchronously
                    processMessages(channel);
                } catch (Exception e) {
                    logError("Failed to accept incoming connection: " + e.getMessage());
                }
            }));
        }

        // Start sending messages to the messaging broker
        messagingBrokerClient = new MessagingBrokerClient();
        messagingBrokerClient.start();

        // Start monitoring and logging metrics
        startMetricsLogger();
    }

    private AsynchronousServerSocketChannel openServerSocket() throws IOException {
        AsynchronousServerSocketChannel serverSocket = AsynchronousServerSocketChannel.open(channelGroup);
        serverSocket.bind(new URI("localhost:0")); // Bind to a random available port
        return serverSocket;
    }

    private AsynchronousSocketChannel acceptConnection(AsynchronousServerSocketChannel serverSocket) {
        try {
            return serverSocket.accept(null);
        } catch (IOException e) {
            logError("Failed to accept connection: " + e.getMessage());
            return null;
        }
    }

    private void processMessages(AsynchronousSocketChannel channel) {
