@SpringBootApplication
@EnableEurekaClient
public class AuthenticationService {
    private static final Logger logger = LoggerFactory.getLogger(AuthenticationService.class);

    @Autowired
    private UserDetailsService userDetailsService;

    @Autowired
    private AuthenticationManager authenticationManager;

    @PostMapping("/authenticate")
    public ResponseEntity<String> authenticate(@RequestBody String token) {
        UsernamePasswordAuthenticationToken authenticationToken = new UsernamePasswordAuthenticationToken(token, null);
        return new ResponseEntity<>(authenticationManager.authenticate(authenticationToken), HttpStatus.OK);
    }

    @GetMapping("/users/{username}")
    public ResponseEntity<UserDetails> getUserDetails(@PathVariable String username) {
        UserDetailsService userDetailsService = (UserDetailsService) this.userDetailsService;
        UserDetails userDetails = userDetailsService.loadUserByUsername(username);
        return new ResponseEntity<>(userDetails, HttpStatus.OK);
    }

    public static void main(String[] args) {
        SpringApplication.run(AuthenticationService.class, args);
    }
}

