use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};
use std::fs::File;
use std::io::{Read, Write};

fn compile_and_manage_resources(input_path: &str, flags: Option<String>) -> (i32, i32) {
    let mut command = Command::new("cargo");
    if let Some(flags) = flags {
        command.arg("build").arg("--manifest-path").arg(input_path).arg(&flags);
    } else {
        command.arg("build").arg("--manifest-path").arg(input_path);
    }

    let output = command.output().expect("Failed to execute process");
    let exit_code: ExitCode = output.status;
    let result = String::from_utf8_lossy(&output.stdout).to_string();

    let mut bundle_path = PathBuf::new();
    bundle_path.push("resources");

    // Load and process the resource bundle
    let mut bundle_contents = Vec::new();
    if let Ok(file) = File::open(&bundle_path) {
        let mut reader = std::io::BufReader::new(file);
        reader.read_to_end(&mut bundle_contents).unwrap();
    }

    (exit_code.code() as i32, bundle_contents.len() as i32)
}
