<?php
// Define constants for database connection parameters
define('DB_HOST', 'localhost');
define('DB_USER', 'your_username');
define('DB_PASSWORD', 'your_password');
define('DB_NAME', 'your_database');

// Initialize MySQLi connection with error handling
$mysqli = new mysqli(DB_HOST, DB_USER, DB_PASSWORD, DB_NAME);
if ($mysqli->connect_error) {
    die('Connect Error: ' . $mysqli->connect_error);
}

// Define constants for HTTP request and C-based processing engine settings
define('HTTP_PORT', 8000);
define('C_ENGINE_PATH', '/path/to/c/engine');

// Start HTTP server
$server = new swoole_http_server(HTTP_PORT);

// Register callback function to handle HTTP requests
$server->on('request', function ($request) use ($mysqli, $C_ENGINE_PATH) {
    // Extract request data (clinic ID, status, timestamp)
    $clinicId = $request->get['id'];
    $status = $request->get['status'];
    $timestamp = $request->get['timestamp'];

    try {
        // Update MySQL database
        $query = "UPDATE clinics SET status = '$status', updated_at = '$timestamp' WHERE id = '$clinicId'";
        $mysqli->query($query);

        // Invoke C-based processing engine for background processing
        $command = "cd $C_ENGINE_PATH && ./update_clinic_status.sh $clinicId $status $timestamp";
        exec($command);
    } catch (Exception $e) {
        // Handle database connection failure or other errors
        echo 'Error: ' . $e->getMessage();
    }
});

// Start HTTP server and listen for incoming requests
$server->start();
