<?php
namespace OAuthService;

use GuzzleHttp\Client;
use League\OAuth2\Client\Provider\Facebook as FacebookProvider;
use League\OAuth2\Client\Provider\Google as GoogleProvider;
use League\OAuth2\Client\Provider\LinkedIn as LinkedInProvider;
use League\OAuth2\Client\Token\AccessToken;
use League\OAuth2\Client\Token\Storage\PhpStorage;
use Monolog\Logger;

class OAuthService {
    private $config = [];
    private $storage;
    private $logger;

    public function __construct(array $config, Logger $logger) {
        $this->config = $config;
        $this->storage = new PhpStorage();
        $this->logger = $logger;
    }

    public function authenticate(string $provider): ?array {
        switch ($provider) {
            case 'google':
                return $this->authenticateGoogle();
            case 'github':
                return $this->authenticateGitHub();
            case 'linkedin':
                return $this->authenticateLinkedIn();
            default:
                return null;
        }
    }

    private function authenticateGoogle(): ?array {
        $client = new GoogleProvider([
            'clientId'     => $this->config['google']['client_id'],
            'clientSecret' => $this->config['google']['client_secret'],
            'redirectUri'  => $this->config['google']['redirect_uri']
        ]);

        if (!$accessToken = $this->getAccessToken($client)) {
            return null;
        }

        $guzzleClient = new Client();
        $userResponse = $guzzleClient->get('https://www.googleapis.com/oauth2/v1/userinfo', [
            'headers' => ['Authorization' => 'Bearer ' . $accessToken->getToken()]
        ]);

        if ($userResponse->getStatusCode() !== 200) {
            return null;
        }

        $userData = json_decode($userResponse->getBody(), true);
        return array_merge(['provider' => 'google'], $userData);
    }

    // ... (GitHub and LinkedIn authentication methods)

    private function getAccessToken(League\OAuth2\Client\Provider\AbstractProvider $provider): ?AccessToken {
        if (!$this->storage->hasAccessToken($provider)) {
            $accessToken = $provider->getAccessToken();
            if ($accessToken) {
                $this->storage->saveAccessToken($provider, $accessToken);
            } else {
                return null;
            }
        }

        return $this->storage->loadAccessToken($provider);
    }

    public function handleRequest(array $request): array {
        // Process request data
        // ...

        if (isset($request['oauth_provider'])) {
            $userData = $this->authenticate($request['oauth_provider']);
            if ($userData) {
                return ['user_data' => $userData];
            }
        }

        return [];
    }
}

class OAuthServiceFactory {
    public static function create(array $config, Logger $logger): OAuthService {
        return new OAuthService($config, $logger);
    }
}
