// Insert a point into the octree
void OctreeManager::insert(const SpatialPoint& point, const Data& data) {
    // Determine the correct region to insert the point
    int regionId = determineRegion(point);

    // Lock the region for modification
    lockRegion(regionId);

    // Create or find the corresponding node in the octree
    Node* node = getNode(regionId, point);

    // Insert the data into the node
    node->insert(data);

    // Unlock the region
    unlockRegion(regionId);
}

// Update a point in the octree
void OctreeManager::update(const SpatialPoint& oldPoint, const SpatialPoint& newPoint, Data& data) {
    // Determine the correct regions to update (old and new points)
    int oldRegionId = determineRegion(oldPoint);
    int newRegionId = determineRegion(newPoint);

    // Lock both regions for modification
    lockRegion(oldRegionId);
    lockRegion(newRegionId);

    // Update the nodes in both regions
    Node* oldNode = getNode(oldRegionId, oldPoint);
    Node* newNode = getNode(newRegionId, newPoint);

    // Update data in both nodes and propagate changes to children
    oldNode->update(data);
    newNode->update(data);

    // Unlock both regions
    unlockRegion(oldRegionId);
    unlockRegion(newRegionId);
}

// Perform a nearest neighbor query on the octree
void OctreeManager::query(const SpatialQuery& query, std::vector<Data>& results) {
    // Determine the correct region to start the query from
    int regionId = determineRegion(query.point);

    // Lock the region for modification
    lockRegion(regionId);

    // Start a breadth-first search from the root node in the region
    Node* node = getNode(regionId, query.point);
    node->query(query, results);

    // Unlock the region
    unlockRegion(regionId);
}

