    public void processTransactions(byte[] transactions) throws IOException {
        List<Transaction> recentTransactions = new ArrayList<>();
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(transactions))) {
            Transaction transaction;
            while ((transaction = (Transaction) ois.readObject()) != null) {
                handleTransaction(transaction, recentTransactions);
            }
        } catch (IOException e) {
            // Handle deserialization errors gracefully
            System.out.println("Error deserializing transactions: " + e.getMessage());
        }
    }

    private void handleTransaction(Transaction transaction, List<Transaction> recentTransactions) {
        if (isEligibleForProcessing(transaction)) {
            processTransaction(transaction);
            updateRecentTransactions(recentTransactions);
        }
    }

