#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <map>
#include <random>
#include <chrono>

class AttackManager {
public:
    AttackManager(int characterId) : characterId_(characterId), attacks_({{"A", 10}, {"B", 15}, {"C", 20}}),
                                       attackCooldowns_({}), lastAttackTime_(0), logService_(nullptr) {}

    void setLogService(std::function<void(std::string)> logService) {
        logService_ = logService;
    }

    void updateCooldownPeriods(const std::map<std::string, int>& updatedCooldowns) {
        attackCooldowns_ = updatedCooldowns;
    }

    void executeAttack() {
        // Select a random attack respecting cooldown periods
        auto it = std::uniform_int_distribution<>(0, 2)();
        if (it == 0 && lastAttackTime_ > 10) {
            it = std::uniform_int_distribution<>(1, 2);
        }
        else if (it == 1 && lastAttackTime_ > 15) {
            it = std::uniform_int_distribution<>(2);
        }

        auto attackType = "A";
        switch (it) {
            case 0: attackType = "A"; break;
            case 1: attackType = "B"; break;
            case 2: attackType = "C"; break;
        }

        // Check if the selected attack is within its cooldown period
        if (attackCooldowns_.at(attackType) < lastAttackTime_) {
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
            return; // Attack not yet ready, wait and try again
        }

        // Record the attack log
        auto timestamp = std::chrono::system_clock::now().time_since_epoch().count();
        if (logService_) {
            logService_(std::to_string(characterId_) + " used " + attackType + " at time " + std::to_string(timestamp));
        }

        lastAttackTime_ = timestamp;
    }

private:
    int characterId_;
    std::map<std::string, int> attacks_;
    std::map<std::string, int> attackCooldowns_;
    int lastAttackTime_;
    std::function<void(std::string)> logService_;
};

int main() {
    // Example usage
    AttackManager manager(1);
    manager.setLogService([](std::string message) { std::cout << message << std::endl; });

    for (int i = 0; i < 5; ++i) {
        manager.executeAttack();
        std::this_thread::sleep_for(std::chrono::seconds(2));
    }

    return 0;
}
