using System;
using System.Net.Http;
using System.Threading.Tasks;

public class DynamicValueGenerator
{
    private readonly HttpClient _httpClient;
    private readonly Random _random;
    private double _minValue;
    private double _maxValue;

    public DynamicValueGenerator(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _random = new Random();
    }

    public void InitializeRange()
    {
        try
        {
            var response = _httpClient.GetAsync("https://config-service.com/range").Result;
            if (response.IsSuccessStatusCode)
            {
                var jsonString = response.Content.ReadAsStringAsync().Result;
                var config = JsonConvert.DeserializeObject<Config>(jsonString);
                _minValue = config.MinValue;
                _maxValue = config.MaxValue;
            }
            else
            {
                // Handle transient failures
                Console.WriteLine("Failed to retrieve range: " + response.StatusCode);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine("Initialization failed: " + ex.Message);
        }
    }

    public double GetRandomFloat()
    {
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GetRandomInt()
    {
        return (int)Math.Round(GetRandomFloat());
    }

    public double GetExclusiveRandomFloat()
    {
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue + 0.0001;
    }

    public int GetExclusiveRandomInt()
    {
        return (int)Math.Ceiling(GetExclusiveRandomFloat());
    }
}

public class Config
{
    public double MinValue { get; set; }
    public double MaxValue { get; set; }
}
