#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <gio/gio.h>

typedef struct {
    char* filePath;
    int retryCount;
} LoadResourceBundleConfig;

void loadResourceBundle(LoadResourceBundleConfig* config) {
    GError* error = NULL;
    GHashTable* bundleItems = g_hash_table_new(g_str_equal, (GCompareFunc)g_strcmp0);
    GFile* file = g_file_new_for_path(config->filePath);

    if (!g_file_resolve_symbolic(file, "bundle", &file)) {
        g_error("Failed to resolve symbolic link for file '%s'", config->filePath);
    }

    GInputStream* input = g_input_stream_new();
    g_input_stream_set_close(input, FALSE);
    g_input_stream_set_buffered_input(input, TRUE);

    if (!g_file_read(file, input, NULL, &error)) {
        g_error("Failed to read file '%s': %s", config->filePath, error->message);
    }

    GDataInputStream* dataInput = g_data_input_stream_new();
    g_data_input_stream_set_input_stream(dataInput, input);

    while (g_input_stream_read_until_eof(dataInput, &error) == FALSE) {
        gchar* line = g_strdup(g_data_input_stream_read_line(dataInput));
        if (!line) {
            g_error("Failed to read line from file '%s': %s", config->filePath, error->message);
        }

        // Parse the bundle item and add it to the hash table
        GHashTable* itemHash = g_hash_table_new(g_str_equal, (GCompareFunc)g_strcmp0);
        gchar** itemKeys = g_strsplit(line, "=", 2);
        for (int i = 0; i < 2; i++) {
            if (!itemKeys[i]) continue;
            gchar** keyVals = g_strsplit(itemKeys[i], ".", 3);
            if (!keyVals[1] || !keyVals[2]) continue;

            gchar* key = g_strdup(keyVals[1]);
            gchar* val = g_strdup(keyVals[2]);
            g_hash_table_insert(itemHash, key, val);

            g_free(key);
            g_free(val);
        }

        for (int i = 0; i < 3; i++) {
            g_free(itemKeys[i]);
        }
        g_strfreev(itemKeys);

        g_hash_table_insert(bundleItems, "bundle", itemHash);

        g_free(line);
    }

    // Handle potential network failures and authentication issues
    if (g_input_stream_get_eos(input)) {
        g_error("Failed to read file '%s'", config->filePath);
    }

    g_hash_table_unref(bundleItems);
    g_input_stream_close(input, NULL, &error);

    if (!g_file_delete(file, &error)) {
        g_error("Failed to delete temporary file '%s': %s", config->filePath, error->message);
    }
}

int main() {
    LoadResourceBundleConfig* config = (LoadResourceBundleConfig*)malloc(sizeof(LoadResourceBundleConfig));
    config->filePath = "path/to/resource/bundle";
    config->retryCount = 3;

    loadResourceBundle(config);

    return 0;
}
