char* sanitize_and_extend_path(char* path, int max_length, const char* custom_sep) {
    if (!path || strlen(path) >= max_length) {
        char* error_message = (char*) malloc(strlen("Invalid path: ") + strlen(path) + 1);
        strcpy(error_message, "Invalid path: ");
        strcat(error_message, path);
        log_error(error_message);
        free(error_message);
        return NULL;
    }

    for (int i = 0; i < strlen(path); i++) {
        if (strchr(valid_chars, path[i]) == NULL) {
            char* error_message = (char*) malloc(strlen("Invalid character: ") + strlen(&path[i]) + 1);
            strcpy(error_message, "Invalid character: ");
            strcat(error_message, &path[i]);
            log_error(error_message);
            free(error_message);
            return NULL;
        }
    }

    if (custom_sep && strlen(custom_sep) > 0) {
        if (strchr(valid_chars, custom_sep[0]) == NULL) {
            char* error_message = (char*) malloc(strlen("Invalid separator: ") + strlen(custom_sep) + 1);
            strcpy(error_message, "Invalid separator: ");
            strcat(error_message, custom_sep);
            log_error(error_message);
            free(error_message);
            return NULL;
        }
    }

    char* extended_path = (char*) malloc(MAX_PATH_LENGTH + 2); // 1 for null-termination and 1 for the added separator
    strcpy(extended_path, path);

    if (strchr(custom_sep ? custom_sep : "/", '\0') == NULL) {
        strcat(extended_path, custom_sep ? custom_sep : "/");
    }

    return extended_path;
}
