// Function to calculate the average of last two numeric values on each line
double calculateAverage(char* line) {
    // Tokenize the line by spaces
    char* token = strtok(line, " ");
    double sum = 0.0;
    int count = 0;

    while (token != NULL) {
        if (atoi(token) > 0) {
            sum += atof(token);
            count++;
        }
        token = strtok(NULL, " ");
    }

    // Calculate the average
    if (count > 1)
        return sum / count;
    else
        return 0.0;
}

int main() {
    // Load JSON configuration file
    json_object* config = json_load_file("config.json", NULL);
    char* dirPath = json_object_get_string(config, "directory");

    // Initialize directory and output files
    DIR* dir = opendir(dirPath);
    FILE* outputFile = fopen("output.csv", "w");

    if (dir == NULL || outputFile == NULL) {
        fprintf(stderr, "Error opening directory or file\n");
        return -1;
    }

    // Process each file concurrently using threads
    pthread_t threads[10];
    int numThreads = 0;

    while ((dirent*) readdir(dir)) {
        if (strcmp(".", dreame->d_name) == 0 || strcmp("..", dreame->d_name) == 0)
            continue;

        // Open the file for processing
        FILE* file = fopen(dreame->d_name, "r");

        if (file == NULL) {
            fprintf(stderr, "Error opening file %s\n", dreame->d_name);
            continue;
        }

        // Process each line in the file concurrently using threads
        while ((line = getline(file))) {
            // Calculate the average of last two numeric values on each line
            double average = calculateAverage(line);

            // Append this average as the final field in the output
            fprintf(outputFile, "%s,%.2f\n", line, average);
        }

        fclose(file);
    }

    // Close directory and output file
    closedir(dir);
    fclose(outputFile);

    return 0;
}

