        // Validate input parameters
        if (!config->ip || !config->mac || !settings->subnet_mask || !settings->gateway) {
            errorCallback("Invalid configuration data");
            return;
        }

        // Check if device is already configured
        if (config->already_configured) {
            printf("Device is already configured\n");
            return;
        }

        // Configure the device
        pthread_mutex_lock(&mutex);
        int status = configure_device_internal(config, settings);
        pthread_mutex_unlock(&mutex);

        // Handle errors and retries
        if (status == 0) {
            config->already_configured = 1;
            printf("Device configured successfully\n");
            return;
        } else if (retries < 2) {
            // Retry failed configuration attempts with exponential backoff
            int delay = (int)pow(2, retries);
            printf("Configuration failed. Retrying in %d seconds...\n", delay);
            sleep(delay);
            retries++;
        } else {
            // Maximum retries reached. Report error.
            errorCallback("Failed to configure device");
            return;
        }
    }

    // Log detailed information about each configuration attempt and outcome
    pthread_mutex_lock(&mutex);
    log_configuration_attempts();
    pthread_mutex_unlock(&mutex);

    return;
}

// Function to implement the actual device configuration
int configure_device_internal(DeviceConfig* config, NetworkSettings* settings) {
    // Simulate DNS lookup with potential delay and error
    int dns_status = perform_dns_lookup(config->ip);
    if (dns_status == 0) {
        // Configure the device using DHCP
        int dhcp_status = perform_dhcp_config(config->mac, settings->subnet_mask, settings->gateway);
        if (dhcp_status == 0) {
            // Configure the device using configuration management API
            int api_status = perform_api_config(config->ip, config->mac);
            return api_status;
        } else {
            return -1; // DHCP failed
        }
    } else {
        return -2; // DNS lookup failed
    }
}

