    public class TokenGenerator : ITokenGenerator
    {
        private readonly ILogger<TokenGenerator> _logger;
        private readonly string _secretKey;
        private readonly string _authServiceUrl;

        public TokenGenerator(ILogger<TokenGenerator> logger, string secretKey, string authServiceUrl)
        {
            _logger = logger;
            _secretKey = secretKey;
            _authServiceUrl = authServiceUrl;
        }

        public async Task<string> GenerateToken(string userId, string username, DateTime expirationDate)
        {
            using var md5 = MD5.Create();
            var tokenData = Encoding.UTF8.GetBytes($"{userId}{username}{expirationDate.Ticks}");
            var hashBytes = md5.ComputeHash(tokenData);

            var token = Convert.ToBase64String(hashBytes);
            await StoreTokenInDatabase(userId, token);
            return token;
        }

        public async Task<bool> ValidateToken(string token, string userId)
        {
            try
            {
                using var md5 = MD5.Create();
                var storedHash = GetStoredHashFromDatabase(userId);
                if (string.IsNullOrEmpty(storedHash))
                    throw new Exception("Invalid or expired token");

                var hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(token));
                return storedHash == Convert.ToBase64String(hashBytes);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Token validation failed");
                return false;
            }
        }

        private async Task StoreTokenInDatabase(string userId, string token)
        {
            // Implement database operations using your preferred ORM or ADO.NET
            await DbOperations.InsertAsync(new TokenEntry { UserId = userId, Token = token });
        }

        private string GetStoredHashFromDatabase(string userId)
        {
            // Implement database operations using your preferred ORM or ADO.NET
            return DbOperations.QueryAsync<TokenEntry>(x => x.UserId == userId).Select(x => x.Token).FirstOrDefault();
        }
    }
}
