namespace EncryptedDataService
{
    public class EncryptionService : IDisposable
    {
        private readonly AesCbcEncryption _encryption;
        private readonly SecureStore _secureStore;
        private readonly ILogger _logger;

        public EncryptionService(SecureStore secureStore, ILogger logger)
        {
            _secureStore = secureStore;
            _logger = logger;
            _encryption = new AesCbcEncryption(_secureStore.GetKey(), _secureStore.GetInitializationVector());
        }

        public void DecryptFile(string filePath)
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                var buffer = new byte[1024 * 1024]; // adjust buffer size as needed
                while (fileStream.Read(buffer, 0, buffer.Length) > 0)
                {
                    _encryption.DecryptData(buffer);
                    fileStream.Write(buffer, 0, buffer.Length);
                }
            }
        }

        public void Dispose()
        {
            _encryption.Dispose();
            _secureStore.Dispose();
        }
    }

    public class SecureStore : IDisposable
    {
        private readonly string _keyFile;
        private readonly string _ivFile;

        public SecureStore(string keyFile, string ivFile)
        {
            _keyFile = keyFile;
            _ivFile = ivFile;
        }

        public byte[] GetKey()
        {
            return File.ReadAllBytes(_keyFile);
        }

        public byte[] GetInitializationVector()
        {
            return File.ReadAllBytes(_ivFile);
        }

        public void Dispose()
        {
            File.Dispose();
        }
    }

    public class AesCbcEncryption : IDisposable
    {
        private readonly Aes _aes;
        private readonly ICryptoTransform _encryptor;

        public AesCbcEncryption(byte[] key, byte[] initializationVector)
        {
            _aes = Aes.Create();
            _aes.Key = key;
            _aes.IV = initializationVector;
            _encryptor = _aes.CreateEncryptor();
        }

        public void DecryptData(byte[] buffer)
        {
            using (var memoryStream = new MemoryStream(buffer))
            {
                var decryptor = _aes.CreateDecryptor();
                using (var cs = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
                {
                    cs.Write(buffer, 0, buffer.Length);
                }
            }
        }

        public void Dispose()
        {
            _aes.Dispose();
        }
    }

    public interface ILogger
    {
        void Log(string message);
    }
}
