namespace CloudDataLoader
{
    public class DataProcessor : IDisposable
    {
        private readonly IFileAccessor _fileAccessor;
        private readonly IApiConnector _apiConnector;
        private readonly ILogger _logger;

        public DataProcessor(IFileAccessor fileAccessor, IApiConnector apiConnector, ILogger logger)
        {
            _fileAccessor = fileAccessor;
            _apiConnector = apiConnector;
            _logger = logger;
        }

        public async Task LoadAndIntegrateData(string filePath, int attempts = 5)
        {
            using (var fileStream = _fileAccessor.OpenRead(filePath))
            {
                try
                {
                    var data = DeserializeFile(fileStream);
                    await IntegrateWithApi(data);
                }
                catch (Exception ex) when (!HandleError(ex, filePath, attempts))
                {
                    // Log and retry if max attempts not reached
                    _logger.LogError(ex, "Failed to load and integrate data from file {filePath}");
                    await Task.Delay((int)Math.Pow(2, attempts - 1));
                    LoadAndIntegrateData(filePath, --attempts);
                }
            }
        }

        private DataModel DeserializeFile(Stream fileStream)
        {
            // Stream-based deserialization
            using (var memoryStream = new MemoryStream())
            {
                fileStream.CopyTo(memoryStream);
                memoryStream.Position = 0;
                return JsonConvert.DeserializeObject<DataModel>(memoryStream);
            }
        }

        private async Task IntegrateWithApi(DataModel data)
        {
            // Concurrency-safe API interaction
            var apiRequest = _apiConnector.BuildRequest(data);
            await apiRequest.ExecuteAsync();
        }

        public void Dispose()
        {
            // Properly dispose resources
            _fileAccessor.Dispose();
            _apiConnector.Dispose();
        }
    }

    public interface IFileAccessor : IDisposable
    {
        Stream OpenRead(string filePath);
    }

