public class CustomService {
    private final ThreadFactory threadFactory;
    private final ExecutorService executorService;
    private final ExternalAPIService externalApiService;
    private final DeserializationPolicy deserializationPolicy;

    public CustomService(DeserializationPolicy deserializationPolicy, 
                          ThreadFactory threadFactory, 
                          ExecutorService executorService, 
                          ExternalAPIService externalApiService) {
        this.deserializationPolicy = deserializationPolicy;
        this.threadFactory = threadFactory;
        this.executorService = executorService;
        this.externalApiService = externalApiService;
    }

    public Response consumeSerializedList(byte[] serializedList) throws IOException {
        try (ObjectInputStream objectInputStream = new ObjectInputStream(new ByteArrayInputStream(serializedList))) {
            List<Object> deserializedObjects = new ArrayList<>();
            Object obj;
            while ((obj = objectInputStream.readObject()) != null) {
                deserializedObjects.add(obj);
            }

            Response response = new Response();
            for (Object obj : deserializedObjects) {
                try {
                    Metadata metadata = externalApiService.getMetadataFor(obj);
                    response.addDeserializedObject(obj, metadata);
                } catch (Exception e) {
                    // handle exceptions
                }
            }

            return response;
        } catch (ClassNotFoundException e) {
            throw new DeserializationError("Invalid class type", e);
        }
    }

    public static class Response {
        private List<DeserializedObject> deserializedObjects;

        public void addDeserializedObject(Object obj, Metadata metadata) {
            // handle objects and metadata
        }

        public List<DeserializedObject> getDeserializedObjects() {
            return deserializedObjects;
        }
    }

    public static class DeserializedObject {
        private Object object;
        private Metadata metadata;

        public DeserializedObject(Object object, Metadata metadata) {
            this.object = object;
            this.metadata = metadata;
        }

