struct Environment {
    name: String,
    path: String,
}

impl Environment {
    fn new(name: &str, path: &str) -> Self {
        Environment { name: name.to_string(), path: path.to_string() }
    }

    fn create(&self) -> io::Result<()> {
        fs::create_dir_all(Path::new(&self.path))?;
        Ok(())
    }

    fn update(&self) -> io::Result<()> {
        if !Path::new(&self.path).exists() {
            self.create()?;
        }
        Ok(())
    }

    fn delete(&self) -> io::Result<()> {
        fs::remove_dir_all(Path::new(&self.path))?;
        Ok(())
    }
}

