using System;
using System.Threading;
using System.Threading.Tasks;

namespace DynamicSecureValueGenerator
{
    public class DynamicSecureValueGenerator
    {
        private readonly IConfigService _configService;
        private readonly ILogger _logger;

        public DynamicSecureValueGenerator(IConfigService configService, ILogger logger)
        {
            _configService = configService;
            _logger = logger;
        }

        public async Task<(int, int)> GetRangeAsync()
        {
            while (true)
            {
                try
                {
                    var range = await _configService.GetRangeAsync();
                    return range;
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error fetching range from config service");
                    await Task.Delay(500); // exponential backoff
                }
            }
        }

        public float GetRandomFloat(int minValue, int maxValue)
        {
            if (minValue > maxValue)
            {
                throw new ArgumentException("minValue must be less than maxValue");
            }
            return new Random().NextDouble() * (maxValue - minValue) + minValue;
        }

        public int GetRandomInt(int minValue, int maxValue)
        {
            return (int)(GetRandomFloat(minValue, maxValue));
        }

        public float GetExclusiveRandomFloat(int minValue, int maxValue)
        {
            return (float)(new Random().NextDouble() * (maxValue - minValue) + (minValue + 1));
        }

        public int GetExclusiveRandomInt(int minValue, int maxValue)
        {
            return (int)(GetExclusiveRandomFloat(minValue, maxValue));
        }
    }
}
