// Function to sanitize and extend the given file path
char *sanitize_and_extend_path(char *path, int max_length) {
    char *normalized_path = NULL;
    size_t len = 0;

    // Normalize the path
    if (path != NULL && strlen(path) > 0) {
        normalized_path = malloc((strlen(allowed_chars) + 1) * sizeof(char));
        strcpy(normalized_path, allowed_chars);

        for (int i = 0; i < strlen(path); i++) {
            char c = path[i];

            // Check for invalid characters and log errors
            if (!strchr(allowed_chars, c)) {
                printf("Invalid character: %c\n", c);
                free(normalized_path);
                return NULL;
            }

            // Append the valid character to the normalized path
            strcat(normalized_path, &c);
        }
    }

    // Extend the path with the appropriate directory separator
    if (normalized_path != NULL) {
        size_t new_len = strlen(normalized_path);

        for (int i = 0; i < max_length - new_len; i++) {
            char *sep = normalized_path + new_len - 1;

            // Check for redundant separators and resolve relative paths
            if (*sep == '/') {
                free(normalized_path);
                return NULL;
            }

            strcat(normalized_path, sep == '/' ? "\\" : "/");
        }
    }

    return normalized_path;
}

int main() {
    char *path = "C:\\Windows\\System32";
    int max_length = 256;

    char *result = sanitize_and_extend_path(path, max_length);
    printf("%s\n", result);

    free(result);

    return 0;
}
