        public RandomValueProvider()
            : this(new DefaultConfig())
        { }

        public RandomValueProvider(IConfiguration config)
        {
            Configuration = config;
        }

        public IConfiguration Configuration { get; }

        public int GenerateRandomInteger(int min, bool isExclusiveMin = false, int max = int.MaxValue, bool isExclusiveMax = true)
        {
            if (isExclusiveMin) min++;
            if (isExclusiveMax) max--;

            return _random.Next(min, max + 1);
        }

        public double GenerateRandomDouble(double min, bool isExclusiveMin = false, double max = double.MaxValue, bool isExclusiveMax = true)
        {
            if (isExclusiveMin) min += 1e-6;
            if (isExclusiveMax) max -= 1e-6;

            return _random.NextDouble() * (max - min) + min;
        }

        public Color GenerateRandomColor()
        {
            var r = GenerateRandomInteger(0, isExclusiveMax: true) / 255.0;
            var g = GenerateRandomInteger(0, isExclusiveMax: true) / 255.0;
            var b = GenerateRandomInteger(0, isExclusiveMax: true) / 255.0;

            return Color.FromArgb((int)(r * 256), (int)(g * 256), (int)(b * 256));
        }

        public double[] GenerateRandomNormals(int count, double mean, double standardDeviation)
        {
            var result = new double[count];

            for (var i = 0; i < count; i++)
                result[i] = _random.NextGaussian() * standardDeviation + mean;

            return result;
        }
