        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &json_data);

        // Perform the request
        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            printf("cURL error: %s\n", curl_easy_strerror(res));
            free(json_data);
            json_object_put(json_data);
            return NULL;
        }

        // Parse JSON response and store integers
        json_object* array = json_object_object_get(json_data, "integers");
        if(array != NULL) {
            for(int i = 0; i < json_object_array_length(array); i++) {
                int integer = (int)json_object_array_get_int(array, i);
                integers = realloc(integers, (count + 1) * sizeof(int));
