        }

        // Free cURL and JSON resources
        curl_easy_cleanup(curl);
        json_object_put(json_data);

        if(count > 0) {
            *size = count;
            return integers;
        } else {
            free(integers);
            return NULL;
        }
    }

    return NULL;
}

