    Record** records = malloc(sizeof(Record*) * n);
    for(int i = 0; i < n; i++) {
        records[i] = createRecord(rand() % 100);
    }

    // Perform garbage collection periodically
    gc(mem, 1024);

    // Serialize data structure to binary format
    FILE* file = fopen("data.bin", "wb");
    serializeData(records, n, file);
    fclose(file);

    return 0;
}
