// Document Editor Panel class for handling user interactions
class DocumentEditorPanel extends JPanel {

    // Initializing the document editor components
    public DocumentEditorPanel() {
        // Adding a JTextArea for editing the document
        textarea = new JTextArea(20, 30);
        textarea.setEditable(true);

        // Adding a JScrollPane to manage the text area's size
        scrollPane = new JScrollPane(textarea);

        // Adding a JButton for saving the document
        saveButton = new JButton("Save");
        saveButton.addActionListener(new ActionListener() {
            public void actionPerformed(ActionEvent e) {
                // Saving the document contents to a file
                try (FileWriter writer = new FileWriter("document.txt")) {
                    writer.write(textarea.getText());
                } catch (IOException ex) {
                    System.err.println("Error saving the document: " + ex.getMessage());
                }
            }
        });

        // Adding a JButton for loading the document
        loadButton = new JButton("Load");
        loadButton.addActionListener(new ActionListener() {
            public void actionPerformed(ActionEvent e) {
                // Loading the document contents from a file
                try (FileReader reader = new FileReader("document.txt")) {
                    textarea.setText(reader.readLine());
                } catch (IOException ex) {
                    System.err.println("Error loading the document: " + ex.getMessage());
                }
            }
        });

        // Adding the components to the panel
        add(scrollPane, BorderLayout.CENTER);
        add(saveButton, BorderLayout.NORTH);
        add(loadButton, BorderLayout.SOUTH);
    }

    // JTextArea for editing the document
    private JTextArea textarea;

    // JScrollPane for managing the text area's size
    private JScrollPane scrollPane;

    // JButton for saving the document
    private JButton saveButton;

    // JButton for loading the document
    private JButton loadButton;
}

// Real-Time Collaboration class for handling collaboration features
class RealTimeCollaboration extends Thread {

    // Initializing the real-time collaboration components
    public RealTimeCollaboration(JFrame frame) {
        this.frame = frame;

        // Creating a Socket for real-time communication
        socket = new Socket("localhost", 8080);

        // Reading and writing data to/from the socket
        in = socket.getInputStream();
        out = socket.getOutputStream();

        // Starting the thread for real-time collaboration
        start();
    }

    // Running the thread for real-time collaboration
    public void run() {
        while (true) {
            try {
                // Receiving data from other clients and updating the document
                String message = in.readUTF();
                textarea.setText(message);

                // Sending updates to other clients
                out.write(textarea.getText().getBytes());
                out.flush();

                // Handling user input for collaboration
                if (!textarea.isEditable()) {
                    out.write("User Input: " + textarea.getText().substring(0, 100) + "\n");
                    out.flush();
                }
            } catch (IOException ex) {
                System.err.println("Error during real-time collaboration: " + ex.getMessage());
                break;
            }
        }

        // Closing the socket and stopping the thread
        try {
            socket.close();
            this.interrupt();
        } catch (IOException ex) {
            System.err.println("Error closing the socket: " + ex.getMessage());
        }
    }

    // JFrame for displaying the document editor
    private JFrame frame;

    // Socket for real-time communication
    private Socket socket;

    // Input stream for receiving data from other clients
    private InputStream in;

    // Output stream for sending updates to other clients
    private OutputStream out;
}
