#ifndef RANDOM_VALUE_PROVIDER_HPP
#define RANDOM_VALUE_PROVIDER_HPP

#include <thread>
#include <mutex>
#include <random>
#include <iostream>

namespace RandomGenerator {
    class MTGenerator {
        private:
            std::mt19937_64 engine;
            std::mutex mtx;

        public:
            MTGenerator() : engine(std::random_device{}()) {}

            void reseed(const uint32_t& seed) {
                engine.seed(seed);
            }

            int generateRandomInt(int min, int max) {
                std::lock_guard<std::mutex> lock(mtx);
                return std::uniform_int_distribution<int>(min, max)(engine);
            }
    };

    class RandomValueProvider {
        private:
            MTGenerator generator;

        public:
            RandomValueProvider() : generator() {}

            void reseed(const uint32_t& seed) {
                generator.reseed(seed);
            }

            int generateRandomInt(int min, int max) {
                return generator.generateRandomInt(min, max);
            }
    };
}

#endif // RANDOM_VALUE_PROVIDER_HPP
