    public class XmlConfigService
    {
        private readonly HttpClient _httpClient;
        private readonly SemaphoreSlim _semaphore;
        private readonly IXmlValidator _xmlValidator;
        private readonly ICacheManager _cacheManager;
        private readonly ILogger _logger;

        public XmlConfigService(HttpClient httpClient, 
                                 SemaphoreSlim semaphore, 
                                 IXmlValidator xmlValidator, 
                                 ICacheManager cacheManager, 
                                 ILogger logger)
        {
            _httpClient = httpClient;
            _semaphore = semaphore;
            _xmlValidator = xmlValidator;
            _cacheManager = cacheManager;
            _logger = logger;
        }

        public async Task ProcessXmlAsync(XElement xmlDoc)
        {
            await _semaphore.WaitAsync();
            try
            {
                // Validate XML document against cached schema
                if (_cacheManager.IsValidSchema(xmlDoc))
                {
                    // Schema is valid, no need to validate again
                    _logger.LogInformation("Validating XML document against cached schema.");
                    await _xmlValidator.ValidateXmlAsync(xmlDoc);
                }
                else
                {
                    // Fetch and validate schema from external API
                    await _httpClient.GetAsync("https://api.schema.com/schemas");
                    var schema = await _httpClient.GetXmlSchemaAsync();
                    if (!schema.IsValid)
                    {
                        _logger.LogError("Invalid schema: {0}", schema.Error);
                        return;
                    }
                    _cacheManager.SetSchema(schema);
                }
            }
            finally
            {
                _semaphore.Release();
            }
        }

        public async Task ManageCacheSettingsAsync(CacheSettings settings)
        {
            await _semaphore.WaitAsync();
            try
            {
                // Update cache settings
                _cacheManager.UpdateSettings(settings);
            }
            finally
            {
                _semaphore.Release();
            }
        }
    }

    public class CacheSettings
    {
        public int MaxCacheSize { get; set; }
        public CacheEvictionPolicy EvictionPolicy { get; set; }
    }

    public enum CacheEvictionPolicy
    {
        LRU,
        FIFO,
        Random
    }
}
