        List<ResourceConfig> existingResourceConfigs = database.getExistingResourceConfigs();
        for (ResourceConfig rc : existingResourceConfigs) {
            resourceConfigs.add(rc);
        }

        List<ResourceConfig> newResourceConfigs = apiClient.getNewResourceConfigs();
        for (ResourceConfig rc : newResourceConfigs) {
            resourceConfigs.add(rc);
            database.saveResourceConfig(rc);
        }
    }

    public void updateResourceConfig(ResourceConfig updatedRC) {
        // Update the local cache and database
        resourceConfigs.set(resourceConfigs.indexOf(updatedRC), updatedRC);
