    {
        private readonly IUserRepository _userRepository;
        private readonly IIdentityService _identityService;
        private readonly ILogger<UserController> _logger;

        public UserController(IUserRepository userRepository, IIdentityService identityService, ILogger<UserController> logger)
        {
            _userRepository = userRepository;
            _identityService = identityService;
            _logger = logger;
        }

        [HttpPost("register")]
        public async Task<IActionResult> Register([FromBody] UserRegistrationModel model)
        {
            try
            {
                var user = await _userRepository.GetUserByUserName(model.UserName);
                if (user != null) return Conflict($"User {model.UserName} already exists.");

                // Validate username and password according to configured rules
                if (!ValidateUsernameAndPassword(model.UserName, model.Password))
                    return BadRequest("Invalid username or password");

                // Create new user account
                await _userRepository.CreateUser(model.UserName, model.Email, model.Password);

                return Ok($"User {model.UserName} created successfully");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error creating user");
                return StatusCode(500, "Internal Server Error");
            }
        }

        [HttpPost("login")]
        public async Task<IActionResult> Login([FromBody] UserLoginModel model)
        {
            try
            {
                var user = await _userRepository.GetUserByUserName(model.UserName);
                if (user == null) return Unauthorized($"User {model.UserName} not found");

                // Validate username and password using external identity service
                if (!await _identityService.ValidateCredentials(user.Id, model.Password))
                    return Unauthorized("Invalid password or account locked");

                // Generate JWT token for authenticated user
                var token = await GenerateJwtToken(user);

                return Ok(new { Token = token });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error logging in user");
                return StatusCode(500, "Internal Server Error");
            }
        }

        [HttpPost("recover")]
        public async Task<IActionResult> Recover([FromBody] UserRecoveryModel model)
        {
            try
            {
                var user = await _userRepository.GetUserByUserName(model.UserName);
                if (user == null) return Unauthorized($"User {model.UserName} not found");

                // Validate recovery credentials and send password reset instructions to user
                await _identityService.SendPasswordResetInstructions(user.Id, model.RecoveryCode);

                return Ok("Password reset instructions sent successfully");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error recovering user's password");
                return StatusCode(500, "Internal Server Error");
            }
        }

