// Patient Health Record class
class PatientHealthRecord {
public:
    std::string patientID;
    std::vector<std::pair<std::string, std::string>> healthData;

    // Constructor to initialize patient data
    PatientHealthRecord(std::string patientID) : patientID(patientID) {}

    void addHealthData(std::string key, std::string value) {
        healthData.push_back({key, value});
    }

    // Example method to demonstrate query capabilities
    bool searchHealthData(std::string key, std::string value) {
        for (auto& data : healthData) {
            if (data.first == key && data.second == value) {
                return true;
            }
        }
        return false;
    }
};

// Library implementation
namespace PatientHealthRecordLibrary {
class PatientHealthRecordStore {
public:
    std::map<std::string, PatientHealthRecord> patientRecords;

    // Bulk import operation
    void importPatientData(const std::vector<PatientHealthRecord>& records) {
        for (const auto& record : records) {
            patientRecords[record.patientID] = record;
        }
    }

    // Query engine implementation
    bool searchPatientData(std::string patientID, std::string key, std::string value) {
        if (patientRecords.find(patientID) != patientRecords.end()) {
            return patientRecords[patientID].searchHealthData(key, value);
        }
        return false;
    }

    // Concurrency and data consistency implementation
    class PatientHealthRecordTransaction {
    public:
        std::shared_ptr<PatientHealthRecord> record;
        bool committed;

        // Constructor to initialize transaction
        PatientHealthRecordTransaction(std::shared_ptr<PatientHealthRecord> record) : record(record), committed(false) {}

        void commit() {
            committed = true;
        }

        void rollback() {
            if (record) {
                patientRecords.erase(record->patientID);
            }
            record.reset();
            committed = false;
        }
    };

    // Example method to demonstrate concurrency and data consistency
