async function loadAndExecuteModules() {
  try {
    const modules = await registerModules();
    for (const module of modules) {
      try {
        await executeModule(module);
      } catch (error) {
        console.error(`Error executing module ${module}: ${error}`);
      }
    }
  } catch (error) {
    console.error('Error loading and executing modules:', error);
  }
}

async function executeModule(module) {
  try {
    const metadata = await fetchModuleMetadata(module);
    if (!metadata) throw new Error(`No metadata found for module ${module}`);
    if (metadata.dependencies.length > 0) {
      await loadAndExecuteModules(metadata.dependencies);
    }
    await require(module); // Load and execute the module
  } catch (error) {
    console.error(`Error executing module ${module}: ${error}`);
  }
}

// registry.js
const { getRegistry } = require('./registry-api');
async function registerModules() {
  const registry = await getRegistry();
  try {
    return Object.keys(registry.modules).map((module) => ({
      name: module,
      version: registry.modules[module].version,
    }));
  } catch (error) {
    console.error('Error accessing registry:', error);
  }
}

// api.js
const { fetchMetadata } = require('./metadata-api');
async function fetchModuleMetadata(module) {
  try {
    const response = await fetchMetadata({ module });
    return response.data;
  } catch (error) {
    console.error(`Error fetching metadata for module ${module}: ${error}`);
  }
}

// metadata-api.js
const { getMetadata } = require('./metadata');
async function fetchMetadata(options) {
  try {
    const response = await getMetadata({ ...options });
    return response;
  } catch (error) {
    console.error(`Error fetching metadata: ${error}`);
  }
}
