const anomalyDetector = require('./anomaly-detector');

async function logAuthenticationAttempt(req) {
    try {
        const validationResult = await authenticateRequest(req);
        if (validationResult.valid) {
            // Log successful authentication attempt
            logger.logSuccess('Authentication', req.ip, validationResult.userId);
        } else {
            // Log failed authentication attempt
            logger.logError('Authentication', req.ip, validationResult.error);
        }
    } catch (error) {
        console.error(error);
        // Implement anomaly detection and logging for suspicious activity
        await anomalyDetector.detect(req.ip, error.message);
    }
}

