        predicted_load = self.scaling_algorithm.predict(current_load)
        desired_connections = int((predicted_load - 10) * (self.config["MAX_CONNECTIONS"] - self.config["MIN_CONNECTIONS"]) / 90 + self.config["MIN_CONNECTIONS"])
        if desired_connections != len(self.connections):
