// Function to generate a cryptographically random session ID
char* generate_session_id(int length) {
    // Initialize the session ID string with a null character
    char* session_id = (char*)malloc(length + 1);
    session_id[0] = '\0';

    // Generate random characters from the defined character set
    for (int i = 0; i < length; i++) {
        int rand_idx = rand() % strlen(SESSION_ID_CHARSET);
        session_id[i] = SESSION_ID_CHARSET[rand_idx];
