use Firebase\JWT\Signer;
use PDO;

class SessionManager {
    private $pdo;
    private $config;
    private $jwk;

    public function __construct(PDO $pdo, array $config) {
        $this->pdo = $pdo;
        $this->config = $config;
        $this->jwk = new JWKTrait($config['jwt_private_key'], $config['jwt_public_key']);
    }

    public function authenticate(array $credentials): ?array {
        // Verify credentials against your database or authentication service
        // ...

        if (isset($user)) {
            $token = $this->generateToken($user);
            return ['token' => $token, 'user' => $user];
        } else {
            throw new Exception('Invalid credentials');
        }
    }

    public function validateToken(string $token): ?array {
        try {
            $decoded = (new JWT)->decode($token, $this->jwk->getPublicKey(), ['HS256']);
            return $decoded->getData();
        } catch (ExpiredException $e) {
            // Handle expired token
        }
    }

    public function generateToken(array $user): string {
        // Set the expiration time to 1 hour from now
        $exp = (new DateTime())->add(new \DateInterval('PT1H'))->getTimestamp();

        // Generate the JWT
        return (new JWT)->encode(['sub' => $user['id'], 'exp' => $exp], $this->jwk->getPrivateKey(), 'HS256');
    }

    public function renewToken(string $token): ?string {
        // Get the user from the token
        $user = $this->validateToken($token);

        if ($user) {
            // Generate a new token with the same expiration time as the original token
            return $this->generateToken($user);
        } else {
            throw new Exception('Invalid token');
        }
    }

    public function revokeToken(string $token): void {
        // Remove the token from your database or authentication service
        // ...
    }
}

