import json
import os
import multiprocessing
from functools import partial
from collections import OrderedDict

class DynamicFileProcessor:
    def __init__(self):
        self.file_processors = {}
        self.cache = {}

    def read_json_file(self, file_path):
        with open(file_path, 'r') as f:
            return json.load(f)

    def write_json_file(self, file_path, data):
        with open(file_path, 'w') as f:
            json.dump(data, f)

    def process_json_file(self, file_path, processor=None):
        if not processor:
            processor = self.get_default_processor()
        try:
            file_data = self.read_json_file(file_path)
            processed_data = processor.process(file_data)
            self.write_json_file(file_path, processed_data)
        except Exception as e:
            print(f"Error processing {file_path}: {str(e)}")

    def get_default_processor(self):
        return JSONFileProcessor()

    def register_file_processor(self, file_type, processor):
        self.file_processors[file_type] = processor

class JSONFileProcessor:
    def process(self, data):
        # implement custom processing logic for JSON files
        pass

class DynamicJSONProcessor(JSONFileProcessor):
    def process(self, data):
        processed_data = []
        for item in data:
            if 'sequence_number' in item and 'data' in item:
                processed_data.append({**item, 'processed': True})
            else:
                processed_data.append(item)
        return processed_data

class Cache:
    def __init__(self, cache_size=1000):
        self.cache = {}
        self.cache_size = cache_size
        self.eviction_count = 0

    def get(self, key):
        if key in self.cache:
            value = self.cache[key]
            del self.cache[key]  # remove from cache to ensure eviction
            self.cache_size -= 1
            return value
        else:
            return None

    def set(self, key, value):
        if len(self.cache) >= self.cache_size:
            self.evict()
        self.cache[key] = value

    def evict(self):
        for k in list(self.cache.keys()):
            del self.cache[k]
            self.cache_size -= 1
            self.eviction_count += 1
