#include <iostream>
#include <thread>
#include <mutex>
#include <shared_mutex>
#include <map>
#include <vector>
#include <memory>

class OctreeNode {
public:
    std::mutex lock;
    std::unique_ptr<OctreeNode> children[8];
    int pointCount = 0;

    bool isEmpty() { return pointCount == 0; }
};

class Octree {
public:
    Octree() : root(std::make_unique<OctreeNode>()) {}

    void insertPoint(int x, int y, int z) {
        OctreeNode* current = &root;
        for (int i = 0; i < 3; ++i) {
            if (x > current->children[0]->isEmpty()) {
                current = &current->children[1];
            } else if (y > current->children[4]->isEmpty()) {
                current = &current->children[5];
            } else if (z > current->children[6]->isEmpty()) {
                current = &current->children[7];
            } else {
                break;
            }
        }
        ++current->pointCount;
    }

    void removePoint(int x, int y, int z) {
        OctreeNode* current = &root;
        for (int i = 0; i < 3; ++i) {
            if (x > current->children[0]->isEmpty()) {
                current = &current->children[1];
            } else if (y > current->children[4]->isEmpty()) {
                current = &current->children[5];
            } else if (z > current->children[6]->isEmpty()) {
                current = &current->children[7];
            } else {
                break;
            }
        }
        --current->pointCount;
    }

    std::vector<int> queryPoints(int minX, int minY, int minZ, int maxX, int maxY, int maxZ) {
        std::vector<int> result;
        OctreeNode* current = &root;
        for (int i = 0; i < 3; ++i) {
            if (minX > current->children[0]->isEmpty()) {
                current = &current->children[1];
            } else if (minY > current->children[4]->isEmpty()) {
                current = &current->children[5];
            } else if (minZ > current->children[6]->isEmpty()) {
                current = &current->children[7];
            } else {
                break;
            }
        }
        for (int i = 0; i < 3; ++i) {
            if (maxX < current->children[0]->isEmpty()) {
                current = &current->children[1];
            } else if (maxY < current->children[4]->isEmpty()) {
                current = &current->children[5];
            } else if (maxZ < current->children[6]->isEmpty()) {
                current = &current->children[7];
            } else {
                break;
            }
        }
        for (int i = 0; i < current->pointCount; ++i) {
            result.push_back(current->pointCount);
        }
        return result;
    }

private:
    std::unique_ptr<OctreeNode> root;
};

int main() {
    Octree octree;
    // Test the octree
    octree.insertPoint(0, 0, 0);
    octree.insertPoint(1, 1, 1);
    octree.queryPoints(-1, -1, -1, 2, 2, 2);
    return 0;
}

