package com.transactionprocessing;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.logging.Level;
import java.util.logging.Logger;
import org.apache.commons.lang3.StringUtils;
import com.google.protobuf.Any;
import com.google.protobuf.ByteString;
import io.grpc.stub.StreamObserver;

public class TransactionProcessor {
    private static final Logger LOGGER = Logger.getLogger(TransactionProcessor.class.getName());
    private static final int MAX_CONCURRENT_REQUESTS = 10;
    private static ExecutorService executorService;
    private static grpc.TransactionServiceGrpc.TransactionServiceBlockingStub transactionService;

    public static void processTransactions(List<Transaction> transactions) {
        List<Callable<Void>> callables = new ArrayList<>();
        for (Transaction transaction : transactions) {
            callables.add(() -> processTransaction(transaction));
        }
        executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
        try {
            List<Future<Void>> futures = executorService.invokeAll(callables);
            for (Future<Void> future : futures) {
                future.get();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            if (executorService != null) {
                executorService.shutdown();
            }
        }
    }

    private static void processTransaction(Transaction transaction) {
        // Deserialize and validate the transaction
        Any any = Any.pack(transaction);
        ByteString data = any.getData();

        try {
            // Process the transaction using gRPC
            transactionService.withDeadlineAfter(Duration.ofMinutes(1)).process(any);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error processing transaction", e);
        }
    }

    public static void main(String[] args) {
        // Initialize the gRPC service
        grpc.TransactionServiceGrpc.TransactionServiceBlockingStub transactionService = TransactionServiceGrpc.newBlockingStub();
        processTransactions(new ArrayList<>());
    }
}
