#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>
#include <functional>

class ItemEquiper {
public:
    using ItemID = std::string;
    using Callback = std::function<void(const ItemID&)>;

    ItemEquiper(int cooldownSeconds) : cooldownSeconds_(cooldownSeconds), lastEquipped_(std::chrono::steady_clock::now()) {}

    void equipItem(ItemID itemID, const Callback& callback) {
        auto now = std::chrono::steady_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastEquipped_) < std::chrono::seconds(cooldownSeconds_)) {
            // Duplicate selection within cooldown period
            callback(itemID);
            return;
        }

        equipped_.emplace(itemID, now);

        // Start a new timer for the next cooldown
        timer_.reset(new std::thread([this] { this->timer(); }));

        callback(itemID);
    }

    void timer() {
        auto duration = std::chrono::seconds(cooldownSeconds_);
        while (true) {
            std::this_thread::sleep_for(duration - std::chrono::milliseconds(1));
            if (!equipped_.empty()) {
                auto now = std::chrono::steady_clock::now();
                for (auto it = equipped_.begin(); it != equipped_.end();) {
                    auto&& [id, timestamp] = *it;
                    if (std::chrono::duration_cast<std::chrono::seconds>(now - timestamp) >= duration) {
                        it = equipped_.erase(it);
                    } else {
                        ++it;
                    }
                }
            } else {
                break;
            }
        }
    }

private:
    int cooldownSeconds_;
    std::chrono::steady_clock::time_point lastEquipped_;
    std::unordered_map<ItemID, std::chrono::steady_clock::time_point> equipped_;
    std::unique_ptr<std::thread> timer_;
};

