}

void AsyncRESTClient::delete_request(const std::string& endpoint) {
    execute_request(curl_, CURL_OP_DELETE, base_url_ + endpoint);
}

void AsyncRESTClient::execute_request(CURL* curl, const std::string& method,
                                         const std::string& endpoint, const std::string& query_params,
                                         const std::string& request_body) {
    if (!curl_) {
        curl_ = CURL::easy_init();
    }

    CURL::set_option(curl_, CURLOPT_URL, (base_url_ + endpoint).c_str());
    CURL::set_option(curl_, CURLOPT_RETURNTRANSFER, 1L);
    CURL::set_option(curl_, CURLOPT_MAXREDIRS, 5L);

    if (!query_params.empty()) {
        CURL::set_option(curl_, CURLOPT_URL, (CURL::append_query_string(endpoint, query_params)).c_str());
    }

    switch (method[0]) {
        case 'G':
            CURL::set_option(curl_, CURLOPT_CUSTOMREQUEST, "GET");
            break;
        case 'P':
            CURL::set_option(curl_, CURLOPT_CUSTOMREQUEST, "POST");
            if (!request_body.empty()) {
                CURL::set_option(curl_, CURLOPT_POSTFIELDS, request_body.c_str());
            }
            break;
        case 'U':
            CURL::set_option(curl_, CURLOPT_CUSTOMREQUEST, "PUT");
            if (!request_body.empty()) {
                CURL::set_option(curl_, CURLOPT_POSTFIELDS, request_body.c_str());
            }
            break;
        case 'D':
            CURL::set_option(curl_, CURLOPT_CUSTOMREQUEST, "DELETE");
            break;
    }

    CURL::perform(curl_);
}

int AsyncRESTClient::curl_write_callback(char* ptr, size_t size, size_t nmemb, void* userp) {
    // Handle callback logic
    return 0;
}
```

