class FSAWrapper {
public:
    FSAWrapper(fsa_t* fsa) : fsa_(fsa) {}

    // Process a stream of inputs in the FSA concurrently
    void processInputStream(int *input_stream, int num_inputs) {
        std::vector<std::thread> threads;
        for (int i = 0; i < num_inputs; i++) {
            threads.emplace_back([this, input_stream, i]() {
                fsa_->process(input_stream[i]);
            });
        }
        for (auto& thread : threads) {
            thread.join();
        }
    }

private:
    fsa_t* fsa_;
};

