class VideoProcessor {
private:
    std::unordered_map<std::string, VideoStream*> streams;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void addStream(VideoStream* stream) {
        std::unique_lock<std::mutex> lock(mtx);
        streams[stream->toString()] = stream;
        cv.notify_all();
    }

    void removeStream(VideoStream* stream) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = streams.find(stream->toString());
        if (it != streams.end()) {
            delete it->second;
            streams.erase(it);
        }
    }

    void process() {
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !streams.empty(); });
            for (auto& stream : streams) {
                stream.second->process();
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }
};

int main() {
    VideoProcessor processor;

    CameraVideoStream cameraStream(0);
    FileVideoStream fileStream("path/to/file.mp4");
    WebSocketVideoStream socketStream("ws://localhost:8080", 8080);

    processor.addStream(&cameraStream);
    processor.addStream(&fileStream);
    processor.addStream(&socketStream);

    std::thread processThread([&processor]() { processor.process(); });

    // ... handle video processing and error handling logic ...

