        private readonly IDatabaseRepository _databaseRepository;
        private readonly IExternalAuthenticationService _externalAuthenticationService;
        private readonly ILogger _logger;

        public AuthenticationTokenGenerator(IDatabaseRepository databaseRepository, 
            IExternalAuthenticationService externalAuthenticationService, 
            ILogger logger)
        {
            _databaseRepository = databaseRepository;
            _externalAuthenticationService = externalAuthenticationService;
            _logger = logger;
        }

        public string GenerateToken(string username, string password, bool isMFAEnabled)
        {
            // Hash the input using MD5
            var md5Hash = GetMd5Hash(password);

            // Validate the user and generate a token
            if (_databaseRepository.ValidateUser(username, md5Hash))
            {
                // Check for MFA requirements
                if (isMFAEnabled)
                {
                    // Perform MFA authentication using an external service
                    var mfaToken = _externalAuthenticationService.PerformMFAAuthentication();
                    return GenerateToken(username, md5Hash, mfaToken);
                }
                else
                {
                    return GenerateToken(username, md5Hash);
                }
            }
            else
            {
                throw new AuthenticationException("Invalid username or password");
            }
        }

        private string GetMd5Hash(string input)
        {
            using (var md5 = MD5.Create())
            {
                var result = md5.ComputeHash(Encoding.UTF8.GetBytes(input));
                return BitConverter.ToString(result).Replace("-", "").ToLower();
            }
        }

        private string GenerateToken(string username, string passwordHash, string mfaToken = "")
        {
            // Implement token generation logic using the hashed password and MFA token (if present)
            // For demonstration purposes, a simple concatenated string is used
            return $"{username}:{passwordHash}{mfaToken ?? ""}";
        }
    }

