{
    public async Task<T> Execute<T>(Func<T> func)
    {
        if (_isBroken)
        {
            return default(T); // Return default value or fallback
        }

        try
        {
            return await func();
        }
        catch (Exception e)
        {
            _isBroken = true; // Set circuit breaker to open state
            throw;
        }
    }

    public void Reset() => _isBroken = false;
}

