import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.util.HashMap;
import java.util.Map;

public class SerializationComponent {
    private static final Map<String, Class<?>> CLASS_CACHE = new HashMap<>();
    private static final Map<String, Object> OBJECT_FACTORY_MAP = new HashMap<>();

    public void deserialize(byte[] data) throws IOException, SerializationException {
        try (DataInputStream dis = new DataInputStream(new ByteArrayInputStream(data))) {
            int checksum = dis.readInt();
            String className = readUTF(dis);
            Class<?> clazz = getTargetClass(className);
            if (!clazz.isInstance(dis.readObject())) {
                throw new SerializationException("Invalid object instance");
            }
            if (checksum != calculateChecksum(data)) {
                throw new SerializationException("Checksum mismatch");
            }
        } catch (ClassNotFoundException e) {
            logError(e.getMessage());
        } catch (InstantiationException | IllegalAccessException | InvocationTargetException e) {
            logError("Failed to instantiate target class: " + e.getMessage());
        }
    }

    private Class<?> getTargetClass(String className) throws ClassNotFoundException {
        return CLASS_CACHE.computeIfAbsent(className, k -> {
            try {
                return Class.forName(k);
            } catch (ClassNotFoundException e) {
                throw new ClassNotFoundException(k, e);
            }
        });
    }

    private String readUTF(DataInputStream dis) throws IOException {
        int length = dis.readInt();
        byte[] bytes = new byte[length];
        dis.readFully(bytes);
        return new String(bytes, "UTF-8");
    }

    private int calculateChecksum(byte[] data) {
