namespace RandomValueEngine
{
    public class RandomValueGenerator
    {
        private readonly RandomNumberGenerator _randomNumberGenerator;

        public RandomValueGenerator()
        {
            _randomNumberGenerator = RandomNumberGenerator.Create();
        }

        public int GenerateRandomInt(int min, int max)
        {
            byte[] randomNumber = new byte[4];
            _randomNumberGenerator.GetBytes(randomNumber);
            int randomValue = BitConverter.ToInt32(randomNumber, 0);
            return Math.Max(min, Math.Min(max, randomValue % (max - min + 1)));
        }

        public float GenerateRandomFloat(float min, float max)
        {
            byte[] randomNumber = new byte[4];
            _randomNumberGenerator.GetBytes(randomNumber);
            int randomValue = BitConverter.ToInt32(randomNumber, 0);
            return (float)(min + (randomValue % ((int)((max - min) * 256)) / 255.0));
        }

        public Vector3 GenerateRandomVector3()
        {
            byte[] randomNumberX = new byte[4];
            byte[] randomNumberY = new byte[4];
            byte[] randomNumberZ = new byte[4];

            _randomNumberGenerator.GetBytes(randomNumberX);
            _randomNumberGenerator.GetBytes(randomNumberY);
            _randomNumberGenerator.GetBytes(randomNumberZ);

            int randomValueX = BitConverter.ToInt32(randomNumberX, 0);
            int randomValueY = BitConverter.ToInt32(randomNumberY, 0);
            int randomValueZ = BitConverter.ToInt32(randomNumberZ, 0);

            return new Vector3((float)randomValueX / 255.0f,
                                (float)randomValueY / 255.0f,
                                (float)randomValueZ / 255.0f);
        }
    }

    public class Vector3
    {
        public float X { get; set; }
        public float Y { get; set; }
        public float Z { get; set; }

