class FSA {
public:
    void addTransition(int from, int to) {
        transitions[from].push_back(to);
    }

    void process(int state) {
        while (transitions[state].size() > 0) {
            state = transitions[state][0];
            transitions[state].pop_front();
        }
    }

private:
    std::vector<std::vector<int>> transitions;
};

class FSAWrapper {
public:
    FSAWrapper(FSA& fsa) : fsa(fsa) {}

    void startProcessing() {
        std::thread thread(&FSAWrapper::process, this);
        thread.detach();
    }

    void process(int state) {
        fsa.process(state);
    }

private:
    FSA& fsa;
};

int main() {
    FSA fsa;
    fsa.addTransition(0, 1);
    fsa.addTransition(1, 2);

    FSAWrapper wrapper(fsa);
    wrapper.startProcessing();

    std::ifstream file("log.txt");
    if (file.is_open()) {
        std::string line;
        while (std::getline(file, line)) {
            int state = 0;
            // Process the line
            wrapper.process(state);
        }
    }

    return 0;
}
