using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Amazon.S3;
using Microsoft.Azure.Storage;
using Google.Cloud.Storage.V1;

namespace CloudStorageManager
{
    public class CloudStorageManager : IDisposable
    {
        private readonly Dictionary<string, CloudStorageService> _storageServices = new Dictionary<string, CloudStorageService>();

        public async Task UploadDataAsync(string storageProvider, string bucketName, byte[] data)
        {
            if (!_storageServices.ContainsKey(storageProvider))
                throw new ArgumentException($"Unsupported storage provider: {storageProvider}");

            await _storageServices[storageProvider].UploadDataAsync(bucketName, data);
        }

        public async Task DownloadDataAsync(string storageProvider, string bucketName, string key)
        {
            if (!_storageServices.ContainsKey(storageProvider))
                throw new ArgumentException($"Unsupported storage provider: {storageProvider}");

            await _storageServices[storageProvider].DownloadDataAsync(bucketName, key);
        }

        public void ConfigureService(string storageProvider, CloudStorageConfig config)
        {
            if (!_storageServices.ContainsKey(storageProvider))
                _storageServices.Add(storageProvider, CreateCloudStorageService(storageProvider, config));
        }

        private CloudStorageService CreateCloudStorageService(string storageProvider, CloudStorageConfig config)
        {
            switch (storageProvider)
            {
                case "AWS":
                    return new AWSS3Service(config.AWSS3Config);
                case "Azure":
                    return new AzureBlobService(config.AzureBlobConfig);
                case "Google":
                    return new GoogleCloudStorageService(config.GoogleCloudStorageConfig);
                default:
                    throw new ArgumentException($"Unsupported storage provider: {storageProvider}");
            }
        }

        public void Dispose()
        {
            foreach (var service in _storageServices.Values)
                service.Dispose();
        }
    }

    abstract class CloudStorageService : IDisposable
    {
        protected readonly ICloudStorageClient _cloudStorageClient;

        public CloudStorageService(ICloudStorageConfig config)
        {
            _cloudStorageClient = CreateCloudStorageClient(config);
        }

        public async Task UploadDataAsync(string bucketName, byte[] data)
        {
            await _cloudStorageClient.UploadDataAsync(bucketName, data);
        }

        public async Task DownloadDataAsync(string bucketName, string key)
        {
            await _cloudStorageClient.DownloadDataAsync(bucketName, key);
        }

        protected abstract ICloudStorageClient CreateCloudStorageClient(ICloudStorageConfig config);

        public void Dispose()
        {
            _cloudStorageClient.Dispose();
        }
    }

    class AWSS3Service : CloudStorageService
    {
        public AWSS3Service(AWSS3Config config) : base(config)
        {
        }

        protected override ICloudStorageClient CreateCloudStorageClient(AWSS3Config config)
        {
            return new AmazonS3Client(config.AWSCredentials, config.Regions);
        }
    }

    class AzureBlobService : CloudStorageService
    {
        public AzureBlobService(AzureBlobConfig config) : base(config)
        {
        }

        protected override ICloudStorageClient CreateCloudStorageClient(AzureBlobConfig config)
        {
            return new CloudBlobClient(new Uri(config.StorageAccount), config.Credentials);
        }
    }

    class GoogleCloudStorageService : CloudStorageService
    {
        public GoogleCloudStorageService(GoogleCloudStorageConfig config) : base(config)
        {
        }

        protected override ICloudStorageClient CreateCloudStorageClient(GoogleCloudStorageConfig config)
        {
            return StorageClient.Create(config.ProjectId, config.Credentials);
        }
    }

    interface ICloudStorageClient
    {
        Task UploadDataAsync(string bucketName, byte[] data);
        Task DownloadDataAsync(string bucketName, string key);
    }

    class CloudStorageConfig
    {
        public string StorageProvider { get; set; }
        public AWSS3Config AWSS3Config { get; set; }
        public AzureBlobConfig AzureBlobConfig { get; set; }
        public GoogleCloudStorageConfig GoogleCloudStorageConfig { get; set; }
    }

    class AWSS3Config
    {
        public string AccessKey { get; set; }
        public string SecretKey { get; set; }
        public List<string> Regions { get; set; }
    }

    class AzureBlobConfig
    {
        public string StorageAccount { get; set; }
        public CloudStorageAccount<Credentials> Credentials { get; set; }
    }

    class GoogleCloudStorageConfig
    {
        public string ProjectId { get; set; }
        public ServiceAccountCredential Credentials { get; set; }
    }
}
