void add_nodes_and_edges(int num_vertices, int num_edges) {
    // Create the first vertex
    Node *first_vertex = (Node *)malloc(sizeof(Node));
    first_vertex->id = 1;
    first_vertex->name = "Vertex 1";
    first_vertex->next = NULL;

    // Add additional vertices and edges
    for (int i = 2; i <= num_vertices; i++) {
        Node *new_vertex = (Node *)malloc(sizeof(Node));
        new_vertex->id = i;
        new_vertex->name = (char *)malloc((strlen("Vertex ") + 10) * sizeof(char));
        sprintf(new_vertex->name, "Vertex %d", i);
        new_vertex->next = first_vertex;

        // Add edges
        for (int j = 1; j <= num_edges; j++) {
            Node *new_edge = (Node *)malloc(sizeof(Node));
            new_edge->id = j;
            new_edge->name = (char *)malloc((strlen("Edge ") + 10) * sizeof(char));
            sprintf(new_edge->name, "Edge %d", j);
            new_edge->next = first_vertex;

            // Add vertices to edges
            for (int k = 1; k <= i; k++) {
                if (k != i) {
                    new_edge->next->id = k;
                    new_edge->next->name = (char *)malloc((strlen("Vertex ") + 10) * sizeof(char));
                    sprintf(new_edge->next->name, "Vertex %d", k);
                    new_edge->next->next = first_vertex;
                }
            }

            // Set random properties
            srand(time(NULL));
            int rand_prop1 = rand() % 100;
            int rand_prop2 = rand() % 100;

