// Define a callback mechanism for logging API calls
typedef void (*LoggerCallback)(const char* message);

void processString(const char* inputStr, size_t sizeLimit, char** outputStr, LoggerCallback logger) {
    // Validate the input string does not exceed the specified size limit
    if (strlen(inputStr) > sizeLimit) {
        // Dynamically allocate memory for a new string prefixed with "ERROR:"
        const size_t newSize = sizeLimit - strlen("ERROR:") + 1;
        char* newString = (char*)malloc(newSize);
        if (!newString) {
            logger("Memory allocation failure");
            return NULL;
        }
        sprintf(newString, "ERROR:%.*s", (int)sizeLimit, inputStr);
    } else {
        // Append a slash (/) to the end of the string
        size_t newSize = strlen(inputStr) + 2; // for the added slash and null termination
        *outputStr = (char*)realloc(*outputStr, newSize);
        if (!*outputStr) {
            logger("Memory allocation failure");
            return NULL;
        }
        sprintf(*outputStr, "%s/", inputStr);
    }

    // Ensure the output string is null-terminated
    *(*outputStr + newSize - 1) = '\0';

    // Log the operation using the provided API
    time_t timestamp = time(NULL);
    logger(printf("ProcessString: %s (Thread ID: %lu, Timestamp: %lu)", inputStr, (long unsigned)pthread_self(), timestamp));
}

int main() {
    LoggerCallback logger;
    char* outputStr;

    processString("Hello World", 10, &outputStr, logger);

    // Handle the returned string
    free(outputStr);

    return 0;
}
