// RealtimeEventProcessor.h
#ifndef REALTIMEEVENTPROCESSOR_H
#define REALTIMEEVENTPROCESSOR_H

#include <memory>
#include <queue>
#include <thread>
#include <mutex>

class RealtimeEventProcessor {
public:
    RealtimeEventProcessor();
    ~RealtimeEventProcessor();

    void start();
    void stop();

    void processEvent(const std::string& event);

private:
    class Worker {
    public:
        Worker(RealtimeEventProcessor* processor);
        ~Worker();

        void run();

    private:
        RealtimeEventProcessor* m_processor;
    };

    std::vector<std::thread> m_workers;
    std::queue<std::string> m_eventQueue;
    std::mutex m_mutex;

    // Internal processing functions
    void processEvents();
    void handleEvent(const std::string& event);
};

#endif  // REALTIMEEVENTPROCESSOR_H

// RealtimeEventProcessor.cpp
#include "RealtimeEventProcessor.h"
#include <algorithm>
#include <random>

RealtimeEventProcessor::RealtimeEventProcessor() {
    m_workers.reserve(8); // Initial worker pool size
}

RealtimeEventProcessor::~RealtimeEventProcessor() {
    stop();
}

void RealtimeEventProcessor::start() {
    for (int i = 0; i < m_workers.size(); ++i) {
        m_workers[i] = std::thread([this, i]() { runWorker(i); });
    }
}

void RealtimeEventProcessor::stop() {
    for (auto& worker : m_workers) {
        worker.join();
    }
    m_workers.clear();
}

RealtimeEventProcessor::Worker::Worker(RealtimeEventProcessor* processor)
    : m_processor(processor) {}

RealtimeEventProcessor::Worker::~Worker() {}

void RealtimeEventProcessor::Worker::run() {
    while (true) {
        std::string event;
        {
            std::lock_guard<std::mutex> lock(m_processor->m_mutex);
            if (!m_processor->m_eventQueue.empty()) {
                event = m_processor->m_eventQueue.front();
                m_processor->m_eventQueue.pop();
            }
        }
        if (event.empty()) break; // Exit when queue is empty
        m_processor->handleEvent(event);
    }
}

void RealtimeEventProcessor::processEvents() {
    while (true) {
        std::string event;
        {
            std::lock_guard<std::mutex> lock(m_mutex);
            if (!m_eventQueue.empty()) {
                event = m_eventQueue.front();
                m_eventQueue.pop();
            }
        }
        if (event.empty()) break; // Exit when queue is empty
        handleEvent(event);
    }
}

void RealtimeEventProcessor::handleEvent(const std::string& event) {
    // Process the event here...
}

void RealtimeEventProcessor::processEvent(const std::string& event) {
    {
        std::lock_guard<std::mutex> lock(m_mutex);
        m_eventQueue.push(event);
    }
}
