import logging
from abc import ABC, abstractmethod
from collections import deque
from threading import Lock, Thread
from typing import List, Tuple

class Logger(ABC):
    @abstractmethod
    def log(self, message: str) -> None:
        pass

class LogHandler(ABC):
    @abstractmethod
    def handle(self, message: str) -> None:
        pass

class FileLogHandler(LogHandler):
    def __init__(self, filename: str) -> None:
        self.filename = filename

    def handle(self, message: str) -> None:
        with open(self.filename, 'a') as f:
            f.write(message + '\n')

class DatabaseLogHandler(LogHandler):
    def __init__(self, db_url: str) -> None:
        self.db_url = db_url

    def handle(self, message: str) -> None:
        # implement database logging
        pass

class CloudStorageLogHandler(LogHandler):
    def __init__(self, bucket_name: str) -> None:
        self.bucket_name = bucket_name

    def handle(self, message: str) -> None:
        # implement cloud storage logging
        pass

class LoggerThread(Thread):
    def __init__(self, logger: Logger) -> None:
        super().__init__()
        self.logger = logger
        self.lock = Lock()

    def run(self) -> None:
        while True:
            message = self.queue.get()
            if message is None:
                break
            with self.lock:
                self.logger.log(message)
            self.queue.task_done()

class LoggingFramework:
    def __init__(self, log_level: int) -> None:
        self.log_level = log_level
        self.loggers: List[Logger] = []
        self.queue = deque()
        self.threads = []

    def add_logger(self, logger: Logger) -> None:
        self.loggers.append(logger)
        thread = LoggerThread(logger)
        thread.queue = self.queue
        self.threads.append(thread)
        thread.start()

    def log(self, message: str) -> None:
        if self.log_level <= logging.getlevelname(message):
            for logger in self.loggers:
                logger.log(message)

    def flush(self) -> None:
        while not self.queue.empty():
            self.queue.get()  # discard all pending messages
