#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

struct Node {
    std::string data;
    Node* prev;
    Node* next;
};

class DoublyLinkedList {
public:
    void insertOrLog(Node*& head, const std::string& targetAction, const std::string& newAction) {
        if (head == nullptr || head->data == targetAction) {
            insertAfter(head, newAction);
        } else {
            Node* current = head;
            while (current && current->data != targetAction) {
                current = current->next;
            }
            if (current) {
                insertAfter(current, newAction);
            } else {
                append(newAction);
            }
        }
    }

private:
    void insertAfter(Node*& node, const std::string& data) {
        Node* newNode = new Node();
        newNode->data = data;
        newNode->prev = node;
        newNode->next = node->next;
        if (node->next) {
            node->next->prev = &newNode;
        }
        node->next = &newNode;
    }

    void append(const std::string& data) {
        Node* newNode = new Node();
        newNode->data = data;
        if (!head) {
            head = &newNode;
        } else {
            Node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = &newNode;
            newNode->prev = current;
        }
    }
};

std::string apiCall(int id) {
    // implementation of API call
}

int main() {
