    public class MersenneTwister
    {
        private int _mtState;
        private const int MT_SIZE = 624;

        public MersenneTwister(int seed)
        {
            _mtState = seed;
            for (int i = 1; i < MT_SIZE; i++)
            {
                _mtState = (_mtState ^ ((_mtState & 0x80000000) >>> 21)) * 1664525 + (_mtState & 0x3ffffff);
            }
        }

        public double NextDouble()
        {
            int y = _mtState;
            y ^= (y >> 11);
            y ^= (y << 7) & 0x9d2c5680;
            y ^= (y << 15) & 0xefbac439;
            y ^= (y >> 18);
            return ((double)y) / 4636868975.0;
        }

        public int NextInt()
        {
            int y = _mtState;
            y ^= (y >> 11);
            y ^= (y << 7) & 0x9d2c5680;
            y ^= (y << 15) & 0xefbac439;
            y ^= (y >> 18);
            return y;
        }
    }

