        _connectionPool = new ConnectionPool(_maxConnections);
    }

    public async Task ExecuteParameterizedQueryAsync(string connectionString, string commandText, List<(string, object)> parameters, int timeoutInSeconds)
    {
        // Validate and sanitize command text
        commandText = SanitizeCommandText(commandText);

        // Get a connection from the pool or create a new one if needed
        using (var connection = await _connectionPool.GetConnectionAsync())
        {
            try
            {
                // Create a command with the given parameters
                var command = new SqlCommand(commandText, connection);
                foreach ((string, object) parameter in parameters)
                {
                    command.Parameters.AddWithValue(parameter.Item1, parameter.Item2);
                }

                // Set the timeout for the command execution
                command.CommandTimeout = timeoutInSeconds;

                // Execute the query asynchronously and handle exceptions
                await Task.Run(() =>
                {
                    try
                    {
                        using (var reader = command.ExecuteReader())
                        {
                            // Process the query results
                            // ...
                        }
                    }
                    catch (SqlException ex) when (ex.Number == 4999 || ex.Number == 3956)
                    {
                        // Retry logic for transient errors
                        await Task.Delay(_retryAttempts * _timeout);
                        await ExecuteParameterizedQueryAsync(connectionString, commandText, parameters, timeoutInSeconds);
                    }
                    catch (Exception ex)
                    {
                        // Log the error and rethrow it
                        _logger.LogError(ex, "Error executing query");
                        throw;
                    }
                });
