    public class ConfigurationService
    {
        private readonly HttpClient _httpClient;
        private readonly string _apiUrl;
        private readonly string _apiKey;
        private readonly Dictionary<string, dynamic> _configCache = new Dictionary<string, dynamic>();

        public ConfigurationService(string apiUrl, string apiKey)
        {
            _httpClient = new HttpClient();
            _apiUrl = apiUrl;
            _apiKey = apiKey;

            // Initialize TLS 1.2 or higher
            ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
        }

        public async Task<dynamic> GetConfigAsync(string gameId)
        {
            if (_configCache.TryGetValue(gameId, out dynamic config))
                return config;

            using (var request = new HttpRequestMessage(HttpMethod.Get, $"{_apiUrl}/games/{gameId}/config"))
            {
                request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", _apiKey);

                try
                {
                    var response = await _httpClient.SendAsync(request);
                    response.EnsureSuccessStatusCode();

                    config = await response.Content.ReadAsJsonAsync<dynamic>();

                    _configCache.Add(gameId, config);
                }
                catch (HttpRequestException ex)
                {
                    // Handle API error
                    throw;
                }
            }

            return config;
        }

        public async Task UpdateConfigAsync(string gameId, dynamic updatedConfig)
        {
            using (var request = new HttpRequestMessage(HttpMethod.Put, $"{_apiUrl}/games/{gameId}/config"))
