using Microsoft.Extensions.Logging;

namespace ConfigService
{
    public class ConfigManager
    {
        private readonly ILogger<ConfigManager> _logger;
        private readonly Dictionary<string, string> _localConfig = new();
        private readonly Dictionary<string, string> _remoteConfig = new();
        private readonly object _configLock = new();

        public ConfigManager(ILogger<ConfigManager> logger)
        {
            _logger = logger;
            LoadLocalConfig();
        }

        public void UpdateRemoteConfig()
        {
            try
            {
                // Call the remote JSON API to fetch updated configuration values
                var response = FetchRemoteConfig();

                if (response.IsSuccessStatusCode)
                {
                    _remoteConfig.Clear();
                    foreach (var setting in response.Value)
                    {
                        _remoteConfig.Add(setting.Key, setting.Value);
                    }
                    UpdateLocalConfig();
                }
                else
                {
                    _logger.LogError("Failed to update remote config: {0}", response.ReasonPhrase);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError("Error updating remote config: {0}", ex.Message);
            }
        }

        public string GetConfigValue(string key, bool useDefault = false)
        {
            if (_localConfig.ContainsKey(key))
            {
                return _localConfig[key];
            }

            if (_remoteConfig.ContainsKey(key) && useDefault)
            {
                return _remoteConfig[key];
            }

            // Fallback to default value
            return "default_value";
        }

        public void SetConfigValue(string key, string value)
        {
            lock (_configLock)
            {
                if (_localConfig.ContainsKey(key))
                {
                    _localConfig[key] = value;
                }
                else if (_remoteConfig.ContainsKey(key))
                {
                    _remoteConfig[key] = value;
                }
                else
                {
                    throw new ArgumentException("Invalid config key");
                }
            }

            UpdateLocalConfig();
        }

        private void LoadLocalConfig()
        {
            // Load environment variables and command-line arguments into local config
            foreach (var envVar in Environment.GetEnvironmentVariables())
            {
                _localConfig.Add(envVar.Key, envVar.Value);
            }
            foreach (var arg in System.Diagnostics.Process.GetCurrentProcess().MainModule.ModuleName.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries))
            {
                var parts = arg.Split('=');
                if (parts.Length == 2)
                {
                    _localConfig.Add(parts[0], parts[1]);
                }
            }
        }

        private void UpdateLocalConfig()
        {
            // Write local config to disk or database for persistence
        }

        private async Task<HttpResponseMessage> FetchRemoteConfig()
        {
            using (var client = new HttpClient())
            {
                var response = await client.GetAsync("https://example.com/config");
                return response;
            }
        }
    }
}
