#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <thread>

class DynamicNFAPIPacketGenerator {
public:
    enum class PacketDistribution { Uniform, Weighted, Custom };

    DynamicNFAPIPacketGenerator(PacketDistribution distribution = PacketDistribution::Uniform)
        : distribution_(distribution), packet_rate_(1.0), packet_size_(1024) {}

    void set_packet_distribution(PacketDistribution distribution) {
        if (distribution != PacketDistribution::Uniform && 
            distribution != PacketDistribution::Weighted && 
            distribution != PacketDistribution::Custom) {
            throw std::invalid_argument("Invalid packet distribution");
        }
        distribution_ = distribution;
    }

    void set_packet_rate(double rate) {
        if (rate <= 0.0) {
            throw std::invalid_argument("Packet rate must be greater than zero");
        }
        packet_rate_ = rate;
    }

    void set_packet_size(size_t size) {
        if (size == 0) {
            throw std::invalid_argument("Packet size must be greater than zero");
        }
        packet_size_ = size;
    }

    NFAPI_CRC_INDICATION_PDU_T generate_packet() {
        // Generate a random RNTI
        uint16_t rnti = static_cast<uint16_t>(std::rand() % 65536);

        // Generate a random CRC flag
        bool crc_flag = std::rand() % 2 == 0;

        // Create an NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T packet;
        packet.rx_ue_information_tag = RX_UE_INFORMATION_TAG();
        packet.rnti = rnti;
        packet.crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG(crc_flag);

        return packet;
    }

    void generate_packets(int num_packets) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<double> distribution(0.0, 1.0);

        for (int i = 0; i < num_packets; i++) {
            if (distribution_(== PacketDistribution::Uniform) {
                // Generate a random packet
                NFAPI_CRC_INDICATION_PDU_T packet = generate_packet();
            } else if (distribution_(== PacketDistribution::Weighted) {
                // Generate a weighted packet with varying probabilities
                double probability = distribution(gen);
                if (probability < 0.5) {
                    // Generate a packet with 50% chance of success
                    NFAPI_CRC_INDICATION_PDU_T packet = generate_packet();
                } else {
                    // Generate an empty packet
                    packet.rnti = 0;
                    packet.crc_indication_rel8_tag.set_crc_flag(false);
                }
            } else if (distribution_(== PacketDistribution::Custom) {
                // Generate a custom packet with user-defined probabilities
                double probability = distribution(gen);
                if (probability < 0.2) {
                    // Generate a packet with 20% chance of success
                    NFAPI_CRC_INDICATION_PDU_T packet = generate_packet();
                } else {
                    // Generate an empty packet
                    packet.rnti = 0;
                    packet.crc_indication_rel8_tag.set_crc_flag(false);
                }
            }

            // Transmit the packet over the network
            transmit_packet(packet);
        }
    }

private:
    PacketDistribution distribution_;
    double packet_rate_;
    size_t packet_size_;

    std::mutex mutex_;
};
