void cache_cell_measurement_report(CellMeasurementReport* report) {
    // In-memory caching layer (e.g., Redis or Memcached)
    CURL *curl;
    CURLcode res;
    char *data = "{\"cell_id\": %d, \"signal_strength\": %f, \"data_speed\": %f}";
    int len = strlen(data);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://localhost:8080/cache");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data, len);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            printf("curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
    }
    curl_global_cleanup();

    // Disk-based caching layer (e.g., SQLite or MongoDB)
    FILE *fp;
    fp = fopen("cell_measurement_reports.db", "a");
    if(fp) {
        fprintf(fp, "{\"cell_id\": %d, \"signal_strength\": %f, \"data_speed\": %f}\n", report->cell_id, report->signal_strength, report->data_speed);
        fclose(fp);
