        report->data_speed = (float)i * 2.0f;

        pthread_create(&threads[i], NULL, process_cell_measurement_report, report);
    }

    // Wait for all threads to complete
    for(int i = 0; i < num_reports; i++) {
        pthread_join(threads[i], NULL);
