void fetch_data(CellMeasurementReport* report, const char* api_url) {
    // Send HTTP request to the API and receive response
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    inet_pton(AF_INET, "8.8.8.8", &server_addr.sin_addr);
    connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr));
    // Read data from the API and store it in the report
    char buffer[1024];
    read(sockfd, buffer, 1024);
    // Parse the received data and update the report fields
    report->signal_strength = atof(strtok(buffer, ","));
    report->noise_level = atof(strtok(NULL, ","));
    close(sockfd);
}

