using System;
using Microsoft.Web.Administration;

namespace DistributedMonitoringSystem
{
    public static class WebHostingManager
    {
        public static void AddAndStartWebSite(string directoryPath, string siteName)
        {
            try
            {
                using (var webAdministration = new ServerManager())
                {
                    if (!webAdministration.Sites.Any(s => s.Name == siteName))
                    {
                        var webSite = webAdministration.CreateWebSite(siteName);
                        webSite.VirtualDirectories.Add("/", directoryPath);
                        webAdministration.ApplyChanges();
                        webSite.Start();
                    }
                    else
                    {
                        Console.WriteLine("The website already exists.");
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
