typedef enum {
    SOURCE_TYPE_LEGACY_API,
    SOURCE_TYPE_REAL_TIME_FEED
} source_type_t;

typedef struct {
    int id;
    char* name;
    source_type_t type;
    void (*callback)(void*);
    void* data;
} event_t;

// Event queue structure
typedef struct {
    int size;
    event_t** events;
} event_queue_t;

// Initialize the event queue
event_queue_t* init_event_queue(int capacity) {
    event_queue_t* queue = (event_queue_t*)malloc(sizeof(event_queue_t));
    queue->size = 0;
    queue->events = (event_t**)malloc(capacity * sizeof(event_t*));
    return queue;
}

// Enqueue an event
void enqueue_event(event_queue_t* queue, event_t* event) {
    if(queue->size >= queue->capacity) {
        printf("Event queue is full! Cannot enqueue event.\n");
        return;
    }
    queue->events[queue->size] = event;
    queue->size++;
}

// Dequeue an event
event_t* dequeue_event(event_queue_t* queue) {
    if(queue->size <= 0) {
        printf("Event queue is empty! Cannot dequeue event.\n");
        return NULL;
    }
    event_t* event = queue->events[0];
    for(int i = 1; i < queue->size; i++) {
        queue->events[i - 1] = queue->events[i];
    }
    queue->size--;
    return event;
}

// Process events in the queue
void process_events(event_queue_t* queue) {
    while(queue->size > 0) {
        event_t* event = dequeue_event(queue);
        if(event != NULL) {
            // Call the callback function with the event data
            event->callback(event->data);
        }
    }
}

// Main function to start processing events
int main() {
    // Initialize an event queue with capacity 10
    event_queue_t* queue = init_event_queue(10);

    // Enqueue some events
    for(int i = 0; i < 5; i++) {
        event_t* event = (event_t*)malloc(sizeof(event_t));
        event->id = i;
        event->name = "Event";
        event->type = SOURCE_TYPE_LEGACY_API;
        event->callback = callback_function;
        event->data = &i;
        enqueue_event(queue, event);
    }

    // Process events in the queue
    process_events(queue);

    return 0;
}

// Callback function for processing events
void callback_function(void* data) {
    int* i = (int*)data;
    printf("Received event: %d\n", *i);
}
