    // Destructor
    ~UserSession() {}
};

// SessionManager class definition
class SessionManager {
private:
    std::map<std::string, UserSession> sessions;
    std::mutex sessionMutex;

public:
    // Add a new user session
    void addSession(std::string token, int expirationTime) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        sessions[token] = UserSession(token, expirationTime);
    }

    // Get the user session by token
    UserSession* getSession(std::string token) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        auto it = sessions.find(token);
        if (it != sessions.end()) {
            return &it->second;
        }
        return nullptr;
    }

    // Remove a user session by token
    void removeSession(std::string token) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        sessions.erase(token);
    }

    // Check if the user session is valid
    bool isValidSession(std::string token, int expirationTime) {
        UserSession* session = getSession(token);
        if (session != nullptr && session->expirationTime > expirationTime) {
            return true;
        }
        return false;
    }
