// Function to process string
void* processString(void* arg) {
    // Get argument values
    char* str = (char*)arg;
    int sizeLimit = 100; // Set default size limit
    char* buffer = NULL;

    // Validate input size
    if (strlen(str) > sizeLimit) {
        // Dynamically allocate memory for new string
        buffer = (char*)malloc(strlen(str) + 15); // Add space for "ERROR:" and null-terminator
        sprintf(buffer, "ERROR:%s", str);
    } else {
        // Append slash to the string within limits
        strcat(str, "/");
    }

    // Log memory allocation failure if buffer is NULL
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed: %s\n", str);
        free(str); // Free original string to avoid memory leak
        return NULL;
    }

    // Output the processed string
    printf("%s\n", buffer);

    // Deallocate memory for buffer and original string
    free(buffer);
    free(str);

    return NULL;
}

int main() {
    pthread_t thread;

    // Create a new thread to process the string
    if (pthread_create(&thread, NULL, processString, "Hello World") != 0) {
        fprintf(stderr, "Thread creation failed.\n");
        return -1;
    }

    // Join the thread
    pthread_join(thread, NULL);

    return 0;
}
