    // Set encryption algorithm based on configuration parameters
    if (set_algorithm(ctx, "AES-256-CBC")) {
        // Process data securely using asynchronous streams
        FILE* file = fopen(filePath, "rb+");

        // Validate configuration parameters and handle errors
        if (!file) {
            error("Failed to open file: %s", filePath);
        } else {
            fseek(file, 0, SEEK_END);
            long fileSize = ftell(file);

            // Allocate memory for encrypted data
            uint8_t* data = (uint8_t*)malloc(fileSize);

            // Read and encrypt file contents in chunks
            int chunkSize = 1024;
            for (long offset = 0; offset < fileSize; offset += chunkSize) {
                fseek(file, offset, SEEK_SET);
                size_t bytesRead = fread(data + offset, 1, chunkSize, file);

                // Encrypt data using the cipher object
                uint8_t* encryptedData = malloc(bytesRead);
                int encryptedBytes = encrypt_data(ctx, data + offset, bytesRead, encryptedData);

                // Handle errors and exceptions
                if (encryptedBytes < 0) {
                    error("Encryption failed: %s", filePath);
                } else {
