        for (int i = 0; i < 1000000; i++) {
            this.parent[i] = i;
        }
    }

    public void unionAll(int num) {
        // Find the root of the set containing 'num'
        int root = find(num);
        // Union all elements in the range [root, num]
        for (int i = root; i <= num; i++) {
            this.parent[i] = root;
        }
    }

