CREATE PROCEDURE GetSupervisorEmployees @supervisorID int
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        SELECT E.EmployeeID, E.FirstName, E.LastName, E.Email, 
               E.JobTitle, E.DepartmentName, E.City, E.Address, 
               D.DepartmentName AS Department, C.[City] AS City,
               A.[DepartmentName] AS DepartmentFromAPI
        FROM Employees E
        JOIN Departments D ON E.DepartmentID = D.DepartmentID
        LEFT JOIN (
            SELECT * 
            FROM [ExternalAPICityTable]
            WHERE [EmployeeID] = E.EmployeeID AND [SupervisorID] = @supervisorID
        ) C ON E.EmployeeID = C.[EmployeeID]
        LEFT JOIN (
            SELECT * 
            FROM [ExternalAPIAddressTable]
            WHERE [EmployeeID] = E.EmployeeID AND [DepartmentName] = D.DepartmentName AND [City] = C.[City]
        ) A ON E.EmployeeID = A.[EmployeeID]
        WHERE E.SupervisorID = @supervisorID
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000);
        SET @ErrorMessage = ERROR_MESSAGE();
        RAISERROR (@ErrorMessage, 16, 1)
    END CATCH;
END;

GO

CREATE PROCEDURE GetSupervisorEmployeesWithRetry @supervisorID int
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @maxRetries INT = 5;
    DECLARE @retryInterval INT = 1000; // in milliseconds

    BEGIN TRY
        WHILE @maxRetries > 0
            BEGIN
                EXEC GetSupervisorEmployees @supervisorID;
                IF @@TRANCOUNT > 0
                    COMMIT TRANSACTION;
                SET @maxRetries -= 1;
                WAITFOR TIMEOUT @retryInterval;
            END;

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000);
        SET @ErrorMessage = ERROR_MESSAGE();
        RAISERROR (@ErrorMessage, 16, 1)
    END CATCH;
END;

GO

CREATE PROCEDURE GetSupervisorEmployeesWithCaching @supervisorID int
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @cacheKey NVARCHAR(50) = 'GetSupervisorEmployees_' + CONVERT(NVARCHAR(20), @supervisorID);

    IF EXISTS (SELECT 1 FROM Cache WHERE Key = @cacheKey)
        BEGIN
            SELECT EmployeeID, FirstName, LastName, Email, JobTitle, DepartmentName, City, Address 
            FROM Cache WHERE Key = @cacheKey;
            RETURN;
        END;

    BEGIN TRY
        EXEC GetSupervisorEmployees @supervisorID;

        INSERT INTO Cache (Key, EmployeeID, FirstName, LastName, Email, JobTitle, DepartmentName, City, Address)
        VALUES (@cacheKey, E.EmployeeID, E.FirstName, E.LastName, E.Email, E.JobTitle, E.DepartmentName, E.City, E.Address);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000);
        SET @ErrorMessage = ERROR_MESSAGE();
        RAISERROR (@ErrorMessage, 16, 1)
    END CATCH;

    SELECT EmployeeID, FirstName, LastName, Email, JobTitle, DepartmentName, City, Address 
    FROM Employees E
    WHERE E.SupervisorID = @supervisorID;
END;

GO

CREATE PROCEDURE GetSupervisorEmployeesWithTransactionIsolation @supervisorID int
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;

    SELECT EmployeeID, FirstName, LastName, Email, JobTitle, DepartmentName, City, Address 
    FROM Employees E
    WHERE E.SupervisorID = @supervisorID;

    COMMIT TRANSACTION;
END;

GO

CREATE PROCEDURE GetSupervisorEmployeesWithEventPropagation @supervisorID int
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @eventMessage NVARCHAR(100) = 'Employee updated under supervisor ' + CONVERT(NVARCHAR(20), @supervisorID);

    INSERT INTO Events (EventType, EventMessage)
    VALUES ('EmployeeUpdated', @eventMessage);

    SELECT EmployeeID, FirstName, LastName, Email, JobTitle, DepartmentName, City, Address 
    FROM Employees E
    WHERE E.SupervisorID = @supervisorID;
END;

GO

CREATE PROCEDURE GetSupervisorEmployeesWithAsyncUpdates @supervisorID int
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @queueMessage NVARCHAR(100) = 'Employee updated under supervisor ' + CONVERT(NVARCHAR(20), @supervisorID);

    INSERT INTO MessageQueue (MessageType, Message)
    VALUES ('EmployeeUpdated', @queueMessage);

    SELECT EmployeeID, FirstName, LastName, Email, JobTitle, DepartmentName, City, Address 
    FROM Employees E
    WHERE E.SupervisorID = @supervisorID;
END;

