class DataIngestionPipeline {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<SensorData> dataQueue;

public:
    void start() {
        thread t1 = thread([&]{ process(dataQueue); });
        while (true) {
            unique_lock<mutex> lk(mtx);
            if (!dataQueue.empty()) {
                SensorData d = dataQueue.front();
                dataQueue.pop();
                cout << "Received sensor data: " << d.sensorId << ", value: " << d.value << endl;
                // Ingestion logic goes here
            }
            cv.wait_for(lk, chrono::milliseconds(10));
        }
