    void stop() {
        // Stop thread gracefully
    }

    void ingestData(const SensorData& data) {
        unique_lock<mutex> lk(mtx);
        dataQueue.push(data);
        cv.notify_one();
    }

private:
    void process(queue<SensorData>& q) {
        while (true) {
            unique_lock<mutex> lk(mtx);
            cv.wait(lk, [&]{ return !q.empty(); });
            SensorData d = q.front();
