import boto3
import logging
from typing import List

class UnionFind:
    def __init__(self):
        self.parent = {}

    def find(self, x):
        if x not in self.parent:
            self.parent[x] = x
        elif self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_x] = root_y

class LogProcessor:
    def __init__(self, s3_bucket: str):
        self.s3 = boto3.client('s3')
        self.uf = UnionFind()
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def process_log_file(self, file_key: str) -> int:
        response = self.s3.get_object(Bucket=s3_bucket, Key=file_key)
        log_data = response['Body'].read().decode('utf-8').splitlines()

        sequence_number = None
        disjoint_pairs = 0

        for line in log_data:
            if not line:
                continue
            arrays = [int(x) for x in line.split(',')]

            for array in arrays:
                for i, elem in enumerate(array):
                    for j in range(i+1, len(array)):
                        if self.uf.find(elem) != self.uf.find(array[j]):
                            self.uf.union(elem, array[j])
                            disjoint_pairs += 1

        sequence_number = int(log_data[-1].split('=')[1])

        return sequence_number, disjoint_pairs

    def get_sequence_number(self, file_key: str) -> int:
        response = self.s3.get_object(Bucket=s3_bucket, Key=file_key)
        log_data = response['Body'].read().decode('utf-8').splitlines()
        return int(log_data[-1].split('=')[1])

    def start_processing(self):
        while True:
            try:
                file_key = next(file_key for file_key in self.s3.list_objects(Bucket=s3_bucket)['Contents'] if 'log_' in file_key['Key'])
                sequence_number, disjoint_pairs = self.process_log_file(file_key)
                print(f"Processing time: {self.get_processing_time()} ms")
                print(f"Sequence number: {sequence_number}")
                print(f"Disjoint pairs: {disjoint_pairs}")
            except Exception as e:
                self.logger.error("Error processing log file:", e)

    def get_processing_time(self) -> int:
        return 0

if __name__ == "__main__":
    s3_bucket = 'your_s3_bucket'
    processor = LogProcessor(s3_bucket)
    processor.start_processing()
