class GameCharacterCombatManager {
public:
    void performAction(int characterId, char action) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto& cooldowns = characterCooldowns_[characterId];
        if (!cooldowns.empty()) {
            // Check if the action is not repeated consecutively
            if (action != cooldowns.back().second) {
                switch (action) {
                    case 'A':
                        cooldowns.push_back(std::make_pair(clock_, 10));
                        break;
                    case 'B':
                        cooldowns.push_back(std::make_pair(clock_, 15));
                        break;
                    case 'C':
                        cooldowns.push_back(std::make_pair(clock_, 20));
                        break;
                }
            } else {
                // Handle repeated action
                // (e.g., log error, notify game state)
            }
        }
    }

private:
    std::map<int, std::deque<std::pair<int64_t, char>>>& characterCooldowns_;
    int64_t clock_ = 0;
    std::mutex mutex_;
};

int main() {
    // Initialize combat manager
    GameCharacterCombatManager combatManager;

    // Simulate combat actions
    for (int i = 0; i < 10000; ++i) {
        combatManager.performAction(i, 'A'); // A action
        std::this_thread::sleep_for(std::chrono::seconds(10));
        combatManager.performAction(i, 'B'); // B action
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }

    return 0;
}
