import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

@SpringBootApplication
@RestController
public class BatchProcessingEngine {

    private static final String SCHEMA_FILE = "schema.csv";
    private static final int MAX_RETRY_ATTEMPTS = 3;

    @Bean
    public ExecutorService executorService() {
        return Executors.newFixedThreadPool(10);
    }

    @PostMapping("/process")
    public ResponseEntity<String> process(@RequestBody JobRequest request) {
        // Validate input directory and files
        validateInputDirectory(request.getInputDirectory());
        validateCSVFiles(request.getInputDirectory());

        // Start job processing
        List<Job> jobs = new ArrayList<>();
        for (File file : request.getInputDirectory().listFiles()) {
            if (file.getName().endsWith(".csv")) {
                Job job = new Job(file);
                jobs.add(job);
            }
        }

        // Concurrency and Fault Tolerance
        executorService().submit(() -> {
            try {
                processJobs(jobs);
            } catch (Exception e) {
                // Handle failures gracefully
                handleFailure(e);
            }
        });

        return ResponseEntity.status(HttpStatus.ACCEPTED).body("Job submitted successfully");
    }

    private void validateInputDirectory(File directory) {
