// modular_loader.js
const fs = require('fs');
const path = require('path');
const { createRequire } = require('module');

class ModularLoader {
  constructor(config) {
    this.config = config;
    this.dependencies = {};
    this.loadedModules = [];
  }

  async loadDependencies() {
    for (const module of Object.keys(this.config.dependencies)) {
      try {
        const dep = await import(module);
        this.dependencies[module] = dep.default;
      } catch (error) {
        console.error(`Error loading dependency: ${module}`);
      }
    }
  }

  async executeModules() {
    for (const module of this.config.modules) {
      try {
        const code = await fs.readFile(module, 'utf8');
        const require = createRequire();
        const executionContext = {};
        const result = require('vm').runInThisContext(code, { filename: module, require });
        if (result !== undefined) {
          this.loadedModules.push({ module, result });
        }
      } catch (error) {
        console.error(`Error executing module: ${module}`);
      }
    }
  }

  async getLoadedModules() {
    return this.loadedModules;
  }

  async start() {
    await this.loadDependencies();
    await this.executeModules();
  }
}

// config.js
const config = {
  dependencies: [
    'node_modules/dependency1',
    'node_modules/dependency2'
  ],
  modules: [
    'user_files/module1.js',
    'user_files/module2.js'
  ]
};

// usage:
