    public class FileProcessor : IDisposable
    {
        private readonly ILogger<FileProcessor> _logger;
        private readonly SemaphoreSlim _semaphore;
        private readonly string _kmsToken;
        private readonly int _maxConcurrentDecryptionOperations;

        public FileProcessor(ILogger<FileProcessor> logger, string kmsToken, int maxConcurrentDecryptionOperations)
        {
            _logger = logger;
            _kmsToken = kmsToken;
            _maxConcurrentDecryptionOperations = maxConcurrentDecryptionOperations;
            _semaphore = new SemaphoreSlim(_maxConcurrentDecryptionOperations);
        }

        public async Task ProcessFileAsync(string filePath)
        {
            try
            {
                using var fileStream = File.OpenRead(filePath);
                using var memoryStream = new MemoryStream();

                await DecryptFileAsync(fileStream, memoryStream);

                // Process decrypted file contents
                using var outputFile = File.Create("decrypted_file.bin");
                await memoryStream.CopyToAsync(outputFile);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing file {FilePath}", filePath);
            }
        }

        private async Task DecryptFileAsync(Stream inputFileStream, Stream outputMemoryStream)
        {
            using var aesGcm = AesGcm.Create(_kmsToken);

            int chunkSize = 1024 * 1024; // 1MB chunks
            byte[] buffer = new byte[chunkSize];

            while (true)
            {
                try
                {
                    await _semaphore.WaitAsync();

                    int bytesRead = inputFileStream.Read(buffer, 0, chunkSize);
                    if (bytesRead == 0) break;

                    using var encryptedChunkStream = new MemoryStream();
                    encryptedChunkStream.Write(buffer, 0, bytesRead);

                    // Decrypt chunk using AES-GCM
                    byte[] decryptedChunk;
                    try
                    {
                        decryptedChunk = aesGcm.Decrypt(encryptedChunkStream);
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Error decrypting file chunk");
                        await _semaphore.ReleaseAsync();
                        continue;
                    }

                    encryptedChunkStream.Position = 0;

                    await outputMemoryStream.WriteAsync(decryptedChunk);

                    // Release semaphore for the next operation
                    await _semaphore.ReleaseAsync();
                }
                catch (OperationCanceledException)
                {
                    // Handle cancellation request
                }
            }
        }

        public void Dispose()
        {
            _logger.Dispose();
            _semaphore.Dispose();
        }
    }

    public class AesGcm : IDisposable
    {
        private readonly string _kmsToken;

