// Data Ingestion
class WebSocketClient : IDisposable
{
    private readonly Dictionary<string, WebSocket> _connections = new();
    private Timer _heartbeatTimer;

    public void Connect(string provider)
    {
        if (_connections.ContainsKey(provider))
            return;

        _connections.Add(provider, new WebSocket($"ws://{provider}.com"));
    }

    public async Task ReceiveDataAsync()
    {
        foreach (var connection in _connections.Values)
        {
            await connection.ReceiveAsync();
        }
    }

    public void StartHeartbeatTimer()
    {
        _heartbeatTimer = new Timer(SendHeartbeat, null, TimeSpan.FromMinutes(1), TimeSpan.FromMinutes(2));
    }

    private async void SendHeartbeat(object state)
    {
        foreach (var connection in _connections.Values)
        {
            await connection.SendAsync("heartBeat", true);
        }
    }

    public void Dispose()
    {
        _heartbeatTimer?.Change(TimeSpan.Zero, TimeSpan.Zero);
    }
}

