int DynamicValueGenerator::generateRandomValue(int minValue, int maxValue) {
    if (minValue >= maxValue) {
        throw std::invalid_argument("Invalid range: minVal >= maxVal");
    }

    return distribution(gen) % (maxValue - minValue + 1) + minValue;
