public:
    virtual ~PaymentGateway() {}
    virtual bool processPayment(const std::string& transactionId) = 0;
};

// UserSession class
class UserSession {
private:
    std::string username_;
    std::string token_;
    int64_t expirationTime_;
    bool authenticated_;
    AuthenticationService* authService_;
    OAuthProvider* oAuthProvider_;

public:
    UserSession(const std::string& username, const std::string& password,
                AuthenticationService* authService, OAuthProvider* oAuthProvider)
        : username_(username), token_(""), expirationTime_(0),
          authenticated_(false), authService_(authService), oAuthProvider_(oAuthProvider) {
        if (!authenticate(password)) {
            throw std::runtime_error("Authentication failed");
        }
    }

    ~UserSession() {}

    void refreshToken() {
        if (expirationTime_ > 0 && expirationTime_ < chrono::system_clock::now().time_since_epoch().count()) {
            token_ = oAuthProvider_->getToken(username_, token_);
            expirationTime_ = chrono::system_clock::now().time_since_epoch().count() + 3600; // 1 hour
        }
    }

    void expireSession() {
        if (expirationTime_ > 0) {
            expirationTime_ = 0;
        }
    }

    bool isSessionValid() const {
        return expirationTime_ > 0 && chrono::system_clock::now().time_since_epoch().count() < expirationTime_;
    }

    void processPayment(const std::string& transactionId) {
        if (isSessionValid()) {
            PaymentGateway* paymentGateway = new PaymentGateway();
            if (!paymentGateway->processPayment(transactionId)) {
                throw std::runtime_error("Payment failed");
            }
            delete paymentGateway;
        } else {
