            // process log entry
        }
    }

    public class AsyncLogger extends LogService {

        private BlockingQueue<String> queue = new LinkedBlockingQueue<>();

        @Override
        public void log(String message, int logLevel) {
            try {
                queue.put(message);
            } catch (IOException e) {
                // handle error
            }
        }

        public void run() {
            while (true) {
                String message = queue.take();
                processLogEntry(message);
            }
        }
