// Function to handle API call and return response
int make_api_call(char* url, char* method, char* data) {
    // Create a socket
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        printf("Error creating socket\n");
        return -1;
    }

    // Set up server address structure
    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);

    // Convert URL to IP and port
    char* ip_addr = (char*) malloc(strlen(url) + 1);
    strcpy(ip_addr, url);
    int pos = strlen(ip_addr);
    for (; pos > 0; --pos) {
        if (ip_addr[pos-1] == ':') {
            ip_addr[pos-1] = '\0';
            break;
        }
    }

    // Connect to the server
    inet_pton(AF_INET, ip_addr, &(serv_addr.sin_addr));
    connect(sockfd, (struct sockaddr*) &serv_addr, sizeof(serv_addr));

    // Send HTTP request and receive response
    send(sockfd, method, strlen(method), 0);
    char buffer[1024];
    recv(sockfd, buffer, 1024, 0);

    // Close the socket
    close(sockfd);

    return 0;
}

