// Function to parse TIFF image file and extract bits per sample and sample per pixel details
int parse_tiff(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // Error opening file
    }

    // Read the TIFF header
    unsigned short tif_header[2];
    fread(tif_header, 2, 1, file);

    int bits_per_sample = tif_header[0] & 0x7F;
    int samples_per_pixel = (tif_header[0] >> 3) & 0x1F;

    // Check if the bits per sample is supported
    if (bits_per_sample != 8 && bits_per_sample != 16) {
        fclose(file);
        return -2; // Error: Bits per sample not supported
    }

    // Handle extra samples
    int extra_samples = tif_header[1] & 0x7F;
    if (extra_samples > 0) {
        // Process the extra samples
    }

    fclose(file);

    return bits_per_sample * samples_per_pixel;
}

int main() {
    CellMeasurementReport report;
    report.cell_id = 12345;
    report.latitude = 37.7749;
    report.longitude = -122.4194;
    strcpy(report.status, "OK");

