class SessionManager {
private:
    std::unordered_map<std::string, std::shared_ptr<UserSession>> sessions;
    std::mutex mtx;
    std::condition_variable cv;

    void updateSession(const std::string& sessionId, const std::function<void(UserSession&)>& update) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = sessions.find(sessionId);
        if (it != sessions.end()) {
            update(it->second.get());
        }
    }

public:
    void addSession(const std::string& sessionId, const UserSession& session) {
        std::unique_lock<std::mutex> lock(mtx);
        sessions[sessionId] = std::make_shared<UserSession>(session);
    }

    void removeSession(const std::string& sessionId) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = sessions.find(sessionId);
        if (it != sessions.end()) {
            sessions.erase(it);
        }
    }

    void updateSessions(const std::function<void(UserSession&)>& update) {
        std::vector<std::string> sessionIds;
        {
            std::unique_lock<stdstd::mutex>(mtx);
            for (const auto& it : sessions) {
                sessionIds.push_back(it.first);
            }
        }
        for (const auto& sessionId : sessionIds) {
            updateSession(sessionId, update);
        }
    }

    void asyncUpdateSessions(const std::function<void(UserSession&)>& update) {
        std::thread([this, update]() {
            updateSession(update);
        }).detach();
    }
};

