    void createVM(VirtualMachine* vm) {
        for (CloudProvider* provider : cloudProviders) {
            if (provider->authenticate(vm->provider)) {
                provider->createVM(vm);
            } else {
                // handle authentication failure
            }
        }
    }

    void updateVM(VirtualMachine* vm) {
        for (CloudProvider* provider : cloudProviders) {
            if (provider->authenticate(vm->provider)) {
                provider->updateVM(vm);
            } else {
                // handle authentication failure
            }
        }
    }

    void deleteVM(VirtualMachine* vm) {
        for (CloudProvider* provider : cloudProviders) {
            if (provider->authenticate(vm->provider)) {
                provider->deleteVM(vm);
            } else {
                // handle authentication failure
            }
        }
    }
