    compression_algorithm_ = compression_algorithm;
    retention_period_ = retention_period;
}

void DynamicLogAggregator::aggregateLogs(const std::vector<std::string>& logs) {
    for (const auto& log : logs) {
        processLogs(std::make_unique<LogSourceImpl>(log), nullptr);
    }
}

void DynamicLogAggregator::transmitLogs() {
    while (running_) {
        cv_.wait_for(mtx_, std::chrono::seconds(1));
        mtx_.lock();
        try {
            // Transmit logs
        } catch (...) {
            running_ = false;
        }
        mtx_.unlock();
    }
}

