// Define the structure NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_rwlock_t lock; // Read-write lock for thread-safe access
} NFAPI_CRC_INDICATION_LIST_T;

// Initialize the dynamic list
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_init() {
    NFAPI_CRC_INDATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) return NULL;
    list->data = NULL;
    list->capacity = 0;
    list->size = 0;
    pthread_rwlock_init(&list->lock, NULL);
    return list;
}

// Add a new NFAPI_CRC_INDICATION_PDU_T structure to the dynamic list
int nfapi_crc_indication_list_append(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (!list || !data) return -1;
    pthread_rwlock_wrlock(&list->lock);
    if (list->size >= list->capacity) {
        // Dynamically resize the memory pool
        size_t new_capacity = list->capacity * 2 + 1;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_rwlock_unlock(&list->lock);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    memcpy(&list->data[list->size], data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size++;
    pthread_rwlock_unlock(&list->lock);
    return 0;
}

// Retrieve a NFAPI_CRC_INDICATION_PDU_T structure from the dynamic list
NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_list_get(NFAPI_CRC_INDICATION_LIST_T* list, size_t index) {
    if (!list || index >= list->size) return NULL;
    pthread_rwlock_rdlock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* data = &list->data[index];
    pthread_rwlock_unlock(&list->lock);
    return data;
}

// Free the dynamic list
void nfapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (!list) return;
    pthread_rwlock_destroy(&list->lock);
    free(list->data);
    free(list);
}
