```cpp
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class NetworkRequestManager {
public:
    NetworkRequestManager();
    ~NetworkRequestManager();

    void configure(const std::string& api_key, const std::string& token);

    void send_request(const std::string& url);

    void set_max_concurrent_requests(int max_requests);

private:
    struct Request {
        std::string url;
        int retries = 0;

        bool operator==(const Request& other) const {
            return url == other.url;
        }
    };

    enum class Status { IDLE, PENDING, FINISHED };

    using HttpClient = std::function<void(const std::string&)>;

    struct Client {
        HttpClient client;
        int attempts = 0;
        bool is_active = true;

        void send_request(const std::string& url) const {
            client(url);
        }
    };

    std::vector<Client> clients;

    std::mutex mtx;
    std::condition_variable cv;

    Status status = Status::IDLE;
    int max_concurrent_requests = 10;
    int current_requests = 0;
    std::map<std::string, Request> requests;

    void worker();

    void process_request(const Request& request);
};

NetworkRequestManager::NetworkRequestManager() {
    for (int i = 0; i < 3; ++i) {
        clients.emplace_back();
    }
}

NetworkRequestManager::~NetworkRequestManager() {}

void NetworkRequestManager::configure(const std::string& api_key, const std::string& token) {
    // configure API key and token
}

void NetworkRequestManager::send_request(const std::string& url) {
    if (current_requests >= max_concurrent_requests) {
        // wait for available slot
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return current_requests < max_concurrent_requests; });
    }

    ++current_requests;

    Request request = {url};
    requests[url] = request;

    status = Status::PENDING;
    worker();

    // handle response
}

void NetworkRequestManager::set_max_concurrent_requests(int max_requests) {
    max_concurrent_requests = max_requests;
}

void NetworkRequestManager::worker() {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx);

        while (!requests.empty()) {
            auto it = requests.begin();
            const Request& request = it->second;

            if (request.retries >= 3) {
                // handle permanent failure
                break;
            }

            Client client = clients[0];
            client.send_request(request.url);
            ++client.attempts;

            if (client.attempts >= 3) {
                requests.erase(it);
                continue;
            }

            requests.erase(it);

            --current_requests;
        }

        lock.unlock();

        cv.notify_all();
    }
}

void NetworkRequestManager::process_request(const Request& request) {
    // process response
}
