    private readonly Dictionary<string, string> _configCache = new Dictionary<string, string>();
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly ILogger _logger = LoggerFactory.CreateLogger("ConfigService");

    public void UpdateConfig(string tenantId, string configKey, string value)
    {
        // Validate configuration key and value
        if (!IsValidConfigKey(configKey))
        {
            throw new ArgumentException($"Invalid config key: {configKey}");
        }

        // Get current value from cache or external source (if available)
        string currentValue = _configCache.ContainsKey(tenantId) ? _configCache[tenantId] : string.Empty;
        if (currentValue == value)
        {
            return; // No change, nothing to update
        }

        try
        {
            // Update cache and external source (if available)
            _configCache.AddOrUpdate(tenantId, value, (k, v) => v);
            if (_httpClient.IsNetworkAvailable())
            {
                _httpClient.PostAsync("https://remote-api.com/config", new StringContent(JsonConvert.SerializeObject(new { tenantId, configKey, value })));
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating configuration");
        }
    }

    public string GetConfigValue(string tenantId, string configKey)
    {
        // Check cache first
        if (_configCache.ContainsKey(tenantId) && _configCache[tenantId].ContainsKey(configKey))
        {
            return _configCache[tenantId][configKey];
        }

        // Fallback to external source (if available)
        if (_httpClient.IsNetworkAvailable())
        {
            try
            {
                var response = _httpClient.GetAsync($"https://remote-api.com/config/{tenantId}/{configKey}").Result;
                if (response.IsSuccessStatusCode)
                {
                    return JsonConvert.DeserializeObject<string>(response.Content.ReadAsStringAsync().Result);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error retrieving configuration value");
            }
        }

        // Default fallback
        return string.Empty;
    }

    private bool IsValidConfigKey(string configKey)
    {
        // Implement schema validation here
        return true; // Replace with actual validation logic
    }
}
