    def add_task(self, task):
        self.tasks.append(task)

    def execute_tasks(self):
        for task in self.tasks:
            cloud_provider = self.cloud_providers.get(task['cloud_provider'])
            if cloud_provider:
                cloud_provider.execute_task(task)
            else:
                logging.error(f"Cloud provider {task['cloud_provider']} not supported")

    def get_status(self):
        statuses = {}
        for task in self.tasks:
            cloud_provider = self.cloud_providers.get(task['cloud_provider'])
            if cloud_provider:
                status = cloud_provider.get_status()
                statuses[task['name']] = status
            else:
                statuses[task['name']] = 'Cloud provider not supported'
        return statuses

class Task:
    def __init__(self, name, cloud_provider):
        self.name = name
        self.cloud_provider = cloud_provider

if __name__ == "__main__":
    workflow = Workflow()
    task1 = Task('Task 1', 'AWS')
    task2 = Task('Task 2', 'Azure')
    task3 = Task('Task 3', 'GoogleCloud')

    workflow.add_task(task1)
    workflow.add_task(task2)
    workflow.add_task(task3)

    workflow.execute_tasks()
    print(workflow.get_status())
```']

