package com.example.distributedcache;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class DistributedCache {
    private ConcurrentHashMap<String, String> mainMemoryCache = new ConcurrentHashMap<>();
    private ConcurrentHashMap<String, String> secondaryMemoryCache = new ConcurrentHashMap<>();

    private Lock lock = new ReentrantLock();

    public void put(String key, String value) {
        mainMemoryCache.put(key, value);
        // Implement the replication mechanism to prevent data loss
        replicateDataToSecondaryMemory(key, value);
    }

    public String get(String key) {
        if (mainMemoryCache.containsKey(key)) {
            return mainMemoryCache.get(key);
        } else {
            return secondaryMemoryCache.getOrDefault(key, null);
        }
    }

    private void replicateDataToSecondaryMemory(String key, String value) {
        // Implement the replication mechanism to prevent data loss
        try {
            Thread.sleep(5000); // Simulate the time it takes to replicate data
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void delete(String key) {
        mainMemoryCache.remove(key);
        secondaryMemoryCache.remove(key);
    }

    public long size() {
        return mainMemoryCache.size() + secondaryMemoryCache.size();
    }
}
