#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

#define MAX_CLIENTS 10000
#define BUFFER_SIZE 1024

typedef struct {
    int socket;
    pthread_mutex_t lock;
} Client;

void *client_handler(void *arg) {
    Client *client = (Client *) arg;
    // Handle client request
}

int main() {
    // Create a pool of client handlers
    pthread_t client_handlers[MAX_CLIENTS];
    for(int i=0; i<MAX_CLIENTS; i++) {
        pthread_create(&client_handlers[i], NULL, client_handler, NULL);
    }

    while(1) {
        // Accept incoming connections
        int sock = accept(listen_sock, (struct sockaddr *)&addr, &len);
        if(sock < 0) {
            perror("Error accepting connection");
            continue;
        }

        // Create a new client struct and assign the socket to it
        Client *client = malloc(sizeof(Client));
        client->socket = sock;

        // Add the client to the pool of client handlers
        pthread_mutex_lock(&client->lock);
        pthread_t handler = client_handlers[sock % MAX_CLIENTS];
        pthread_create(&handler, NULL, client_handler, client);
        pthread_mutex_unlock(&client->lock);

    }

    return 0;
}

