    public static void main(String[] args) {
        SpringApplication.run(Md5HashServiceApplication.class, args);
    }
}

@RestController
@Caching
class Md5HashController {
    @Inject
    private ApplicationContext applicationContext;

    @PostMapping("/compute-md5")
    public String computeMd5(@RequestBody String input) throws Exception {
        // Verify user identity using external service
        UserIdentityService userIdentityService = 
                (UserIdentityService)applicationContext.getBean(UserIdentityService.class);
        boolean isValidUser = userIdentityService.verifyUser(input);

        if (!isValidUser) {
            throw new Exception("Unauthorized access");
        }

        String md5Hash = Md5HashGenerator.generateMd5(input);

        // Store the hash in distributed cache
        Cache cache = (Cache)applicationContext.getBean(Cache.class);
        cache.put("md5_hash", md5Hash);

        return "MD5 Hash: " + md5Hash;
    }
}

class UserIdentityService {
    public boolean verifyUser(String input) {
        // Implement external identity verification logic here
        return true; // For demonstration purposes only
    }
}

interface Cache {
    void put(String key, String value);
    String get(String key);
}

@Caching
class Md5HashGenerator {
    @Cacheable("md5_hash")
    public String generateMd5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = input.getBytes();
            byte[] hashBytes = md.digest(bytes);

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(Integer.toHexString((b & 0xFF) | 0x100).substring(1,3));
            }

            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
