// Define the structure for CryptoMoSTStateManager
typedef struct {
    int state;
    char *role;
} MoSTState;

// Initialize the CryptoMoSTStateManager
void initCryptoMoSTStateManager(MoSTState *state) {
    state->state = 0;
    state->role = NULL;
}

// Transition to a new state based on configuration rules
int transition(MoSTState *state, int new_state, char *new_role) {
    // Check if the current role allows this state transition
    if (!checkRole(state->role, new_role)) {
        return -1;  // Role not allowed for this state transition
    }

    // Transition to the new state and update the role
    state->state = new_state;
    free(state->role);
    state->role = strdup(new_role);

    return 0;
}

// Check if a role is allowed for a given state transition
int checkRole(char *current_role, char *new_role) {
    // Load configuration rules from the database
    int *rules = loadRules();

    // Iterate through the rules to check if this role is allowed for the new state
    for (int i = 0; i < sizeof(rules) / sizeof(int); i++) {
        if (rules[i] == current_role && rules[i+1] == new_state) {
            return 1;  // Role allowed for this state transition
        }
    }

    return -1;  // Role not allowed for this state transition
}

// Load configuration rules from the database
