    int lineCount = 0;
    FILE* inputFile = NULL;
    FILE* outputFile = NULL;
    char* keyword = NULL;
    int printHelp = 0;

    // Parse the command-line flags
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printHelp = 1;
        } else if (strcmp(argv[i], "-cs") == 0 && i + 1 < argc) {
            keyword = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
