    // Log the operation details using an external database system
    MYSQL *mysql = mysql_init(NULL);
    if (mysql_real_connect(mysql, LOG_DB_HOST, LOG_DB_USER, LOG_DB_PASSWORD, 0, NULL, NULL, 0) != 0) {
