package com.example.financialtransactions;

import com.amazonaws.services.dynamodbv2.AmazonDynamoDB;
import com.amazonaws.services.dynamodbv2.AmazonDynamoDBClientBuilder;
import com.amazonaws.services.dynamodbv2.document.Table;
import com.amazonaws.services.dynamodbv2.model.CreateTableRequest;
import com.amazonaws.services.dynamodbv2.model.PutItemRequest;
import com.google.common.collect.Lists;

import javax.ws.rs.Consumes;
import javax.ws.rs.GET;
import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@Path("/transactions")
public class TransactionResource {

    private static final AmazonDynamoDB dynamoDbClient = AmazonDynamoDBClientBuilder.standard().build();
    private static final Table table = dynamoDbClient.getTable("financial_transactions");
    private static final ExecutorService executor = Executors.newFixedThreadPool(5);

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    public Response createTransaction(FinancialTransaction transaction) {
        // Validate and sanitize the transaction data
        List<String> errors = Lists.newArrayList();
        if (!validateTransaction(transaction, errors)) {
            return Response.status(Status.BAD_REQUEST).entity(errors).build();
        }
        PutItemRequest request = new PutItemRequest()
                .withTableName("financial_transactions")
                .withItem(transaction.toMap());
        table.putItem(request);
        return Response.ok().build();
    }

    @GET
    @Path("/batch/{accountId}/{transactionTime}")
    public Response getTransactions(@PathParam("accountId") String accountId, @PathParam("transactionTime") String transactionTime) {
        List<FinancialTransaction> transactions = Lists.newArrayList();
        try (AmazonDynamoDBClient dynamoDbClient = AmazonDynamoDBClientBuilder.standard().build()) {
            CreateTableRequest request = new CreateTableRequest()
                    .withTableName("financial_transactions")
                    .withKeySchema(Lists.newArrayList(new KeySchemaElement("accountId", "S")))
                    .withAttributeDefinitions(Lists.newArrayList(
                            new AttributeDefinition().withAttributeName("transactionTime").withAttributeType("S"),
                            new AttributeDefinition().withAttributeName("amount").withAttributeType("N")));
            dynamoDbClient.createTable(request);
        }
        return Response.ok(transactions).build();
    }

    private boolean validateTransaction(FinancialTransaction transaction, List<String> errors) {
        // Validate account ID and transaction time
        if (!transaction.getAccountId().matches("[0-9a-zA-Z]+")) {
            errors.add("Invalid account ID");
            return false;
        }
        // Validate amount and currency
        if (transaction.getAmount() < 0 || !transaction.getCurrency().matches("[0-9a-zA-Z]+")) {
            errors.add("Invalid transaction amount or currency");
            return false;
        }
        // Validate transaction type and status
        if (!transaction.getTransactionType().matches("[0-9a-zA-Z]+") || !transaction.getStatus().matches("[0-9a-zA-Z]+")) {
            errors.add("Invalid transaction type or status");
            return false;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        // Start the application
        System.out.println("Starting the financial transactions application...");
        executor.submit(new Runnable() {
            @Override
            public void run() {
                // Perform batch insertions and updates
                List<FinancialTransaction> transactions = Lists.newArrayList();
                for (int i = 0; i < 100; i++) {
                    FinancialTransaction transaction = new FinancialTransaction();
                    transaction.setAccountId("account-" + i);
                    transaction.setTransactionTime(System.currentTimeMillis());
                    transaction.setAmount(i * 10.00);
                    transaction.setCurrency("USD");
                    transaction.setTransactionType("DEBIT");
                    transaction.setStatus("SUCCESSFUL");
                    transactions.add(transaction);
                }
                for (FinancialTransaction transaction : transactions) {
                    PutItemRequest request = new PutItemRequest()
                            .withTableName("financial_transactions")
                            .withItem(transaction.toMap());
                    table.putItem(request);
                }
            }
        });
    }
}
