#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <map>

class DataProcessor {
public:
    DataProcessor(int numThreads) : running(true), threads(numThreads) {
        for (int i = 0; i < numThreads; ++i) {
            threads.emplace_back([this, i] {
                while (running) {
                    std::unique_lock<std::mutex> lock(processQueueMutex);
                    processQueue.wait(lock, [this] { return !dataQueue.empty() || !running; });
                    if (!running) {
                        break;
                    }
                    auto data = dataQueue.front();
                    dataQueue.pop();
                    // Process the data
                }
            });
        }
    }

    ~DataProcessor() {
        running = false;
        processQueue.notify_all();
        for (auto& thread : threads) {
            thread.join();
        }
    }

    void pushData(const std::string& data) {
        std::lock_guard<std::mutex> lock(dataQueueMutex);
        dataQueue.push(data);
    }

private:
    bool running;
    int numThreads;
    std::vector<std::thread> threads;
    mutable std::mutex processQueueMutex;
    std::condition_variable processQueue;
    std::queue<std::string> dataQueue;
};

class SensorData {
public:
    int sensorId;
    double temperature;
    double humidity;

    friend std::ostream& operator<<(std::ostream& os, const SensorData& data) {
        os << "Sensor ID: " << data.sensorId
           << ", Temperature: " << data.temperature
           << ", Humidity: " << data.humidity;
        return os;
    }
};

int main() {
    DataProcessor processor(4);

    for (int i = 0; i < 10; ++i) {
        SensorData data = {i, 25.5, 60.3};
        processor.pushData(std::to_string(data));
    }

    return 0;
}
```

This code defines a `DataProcessor` class that manages a queue of sensor data and processes the data concurrently using multiple threads. The `pushData` method adds new data to the queue, which is then processed by the threads.

The `SensorData` class represents a single sensor reading with an ID, temperature, and humidity value.

In the `main` function, we create a `DataProcessor` instance with 4 threads, generate some sample sensor data, and push it into the processor's queue.']

