// Initialize the dynamic list with a specified initial capacity
DynamicList* initializeDynamicList(int initialCapacity) {
    DynamicList* result = (DynamicList*)malloc(sizeof(DynamicList));
    result->size = 0;
    result->capacity = initialCapacity;
    result->entries = (NFAPI_CRC_INDICATION_PDU_T**)malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_init(&result->lock, NULL);
    return result;
}

// Add an entry to the dynamic list
void addEntry(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        // Resize the list if it's full
        int newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** newEntries = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list->entries, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        for (int i = 0; i < list->size; i++) {
            newEntries[i] = list->entries[i];
        }
        free(list->entries);
        list->entries = newEntries;
        list->capacity = newCapacity;
    }
    list->entries[list->size++] = entry;
