    WebSocketServer(int port) : uv_loop(uv_default_loop()) {}

    void run() {
        uv_tcp_init(uv_loop(), &server, port);
        server.data = this;
        uv_listen((uv_stream_t*)&server, 16, on_connection);
    }

private:
