        {
            _httpClient.BaseAddress = new Uri(externalApiUrl);
        }

        public async Task<ValidationResult> ValidateAsync(XmlDocument document, string schemaId)
        {
            if (!_schemaCache.TryGetValue(schemaId, out XsdSchema schema))
            {
                await FetchAndCacheSchemaAsync(schemaId);
            }

            return await ValidateAsync(document, schema);
        }

        private async Task FetchAndCacheSchemaAsync(string schemaId)
        {
            XsdSchema schema;
            try
            {
                using (var response = await _httpClient.GetAsync($"schemas/{schemaId}.xsd"))
                {
                    response.EnsureSuccessStatusCode();
                    using (var stream = await response.Content.ReadAsStreamAsync())
                    {
                        schema = new XsdSchema(stream);
                        _schemaCache.Add(schemaId, schema);
                    }
                }
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Failed to fetch schema {schemaId}", schemaId);
            }
        }

        private async Task<ValidationResult> ValidateAsync(XmlDocument document, XsdSchema schema)
        {
            using (var stream = new MemoryStream())
            {
                document.Save(stream);
                stream.Position = 0;

                using (var reader = XmlReader.Create(stream))
                {
                    ValidationResult result;
                    try
                    {
                        result = await ValidateXmlAsync(reader, schema);
                    }
                    catch (XmlException ex)
                    {
                        _logger.LogError(ex, "Failed to validate XML {filename}", document.FileName);
                        return new ValidationResult(false, ex.Message);
