    void authenticate() {
        // Authenticate with the cloud provider
    }

    VirtualMachine createVM(VirtualMachine vm) {
        // Create a virtual machine on the specified cloud provider
    }

    void updateVM(VirtualMachine vm) {
        // Update a virtual machine on the specified cloud provider
    }

    void deleteVM(VirtualMachine vm) {
        // Delete a virtual machine on the specified cloud provider
    }

private:
    std::string provider_;
};

class OrchestrationPlatform {
public:
    OrchestrationPlatform(std::vector<CloudProvider> providers) : providers_(providers) {}

    void createVM(VirtualMachine vm) {
        for (auto& provider : providers_) {
            if (provider.createVM(vm)) {
                std::cout << "Virtual machine created successfully on " << provider.provider_ << " cloud." << std::endl;
                return;
            }
        }
        std::cout << "Error creating virtual machine." << std::endl;
    }

    void updateVM(VirtualMachine vm) {
        for (auto& provider : providers_) {
            if (provider.updateVM(vm)) {
                std::cout << "Virtual machine updated successfully on " << provider.provider_ << " cloud." << std::endl;
                return;
            }
        }
        std::cout << "Error updating virtual machine." << std::endl;
    }

    void deleteVM(VirtualMachine vm) {
        for (auto& provider : providers_) {
            if (provider.deleteVM(vm)) {
                std::cout << "Virtual machine deleted successfully on " << provider.provider_ << " cloud." << std::endl;
                return;
            }
        }
        std::cout << "Error deleting virtual machine." << std::endl;
    }

private:
    std::vector<CloudProvider> providers_;
};

int main() {
    OrchestrationPlatform platform = OrchestrationPlatform({CloudProvider("AWS"), CloudProvider("Azure"), CloudProvider("Google Cloud")});

    VirtualMachine vm1 = VirtualMachine("my-vm-1", "AWS");
    platform.createVM(vm1);

    VirtualMachine vm2 = VirtualMachine("my-vm-2", "Azure");
    platform.updateVM(vm2);

    VirtualMachine vm3 = VirtualMachine("my-vm-3", "Google Cloud");
    platform.deleteVM(vm3);

    return 0;
}
