                insertStatement.execute();

                // Produce processed data to another Kafka topic
                kafkaProducer.send("processed_topic", data);

                // Commit message offset
                kafkaConsumer.commitSync();
            } catch (Exception e) {
                // Handle errors and exceptions
                System.out.println("Error processing real-time data: " + e.getMessage());
            }
        }
    }

    public void startPipeline() {
        while (true) {
            processRealTimeData();
            try {
                Thread.sleep(1000); // Process data at 1-second intervals
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public static void main(String[] args) {
        RealTimeDataPipeline pipeline = new RealTimeDataPipeline();
        pipeline.startPipeline();
    }
}
```']

