        while (true) {
            // Wait for new requests or exit signal
            std::unique_lock<std::mutex> lock(mutex_);
            conditionVariable_.wait(lock, [&] { return requestQueue_.empty() || !validationThread_.joinable(); });

            // Process batch of transactions
