                // Perform state transition based on business rules and user-defined actions
                await stateMachineConfig.ExecuteAsyncTransition(accessToken);

                // If successful, return
                return;
            }
            catch (Exception ex) when (IsTransientFailure(ex))
            {
                // Retry with backoff strategy
                await retryPolicy.Execute(() => ExecuteAsyncTransition(transitionId));
