    if let Err(err) = report_software_vulnerabilities().await {
        return HttpResponse::InternalServerError().body(format!("Error generating report: {}", err)).finish();
    }

    Ok(HttpResponse::Ok().body("Report generated successfully"))
}

#[actix_webmain]
