    public class CircuitBreaker
    {
        private readonly int _maxRetries;

        public CircuitBreaker()
        {
            _maxRetries = 3;
        }

        public async Task ExecuteAsync(Func<Task> action)
        {
            var retryCount = 0;
            while (true)
            {
                try
                {
                    await action();
                    break;
                }
                catch (Exception ex)
                {
                    if (++retryCount >= _maxRetries)
                    {
                        throw new Exception("Circuit breaker tripped", ex);
