import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class ResourceConfig {
    private String name;
    private int id;
    // getters and setters
}

public interface IResourceConfigRepository {
    void save(ResourceConfig config);
    ResourceConfig get(int id);
}

public class CloudDatabase implements IResourceConfigRepository {
    // implementation for cloud database
}

public class LocalCache {
    private Map<Integer, ResourceConfig> cacheMap = new HashMap<>();
    private Lock lock = new ReentrantLock();

    public void put(int id, ResourceConfig config) {
        lock.lock();
        try {
            cacheMap.put(id, config);
        } finally {
            lock.unlock();
        }
    }

    public ResourceConfig get(int id) {
        lock.lock();
        try {
            return cacheMap.get(id);
        } finally {
            lock.unlock();
        }
    }
}

public class CachingStrategy {
    private int cacheSize;
    private LocalCache localCache;
    private CloudDatabase cloudDatabase;

    public void setup(int cacheSize, LocalCache localCache, CloudDatabase cloudDatabase) {
        this.cacheSize = cacheSize;
        this.localCache = localCache;
        this.cloudDatabase = cloudDatabase;
    }

    public void put(int id, ResourceConfig config) {
        if (localCache.get(id) == null || !config.equals(localCache.get(id))) {
            localCache.put(id, config);
            // check cache size and sync with cloud database
            if (cacheSize < 10000 && localCache.size() > cacheSize) {
                cloudDatabase.save(config);
                localCache.remove(id);
            }
        }
    }

    public ResourceConfig get(int id) {
        return localCache.get(id);
    }
}

public class Service {
    private CachingStrategy cachingStrategy;
    private IResourceConfigRepository repository;

    public void setup(CachingStrategy cachingStrategy, IResourceConfigRepository repository) {
        this.cachingStrategy = cachingStrategy;
        this.repository = repository;
    }

    public ResourceConfig getResourceConfig(int id) {
        return cachingStrategy.get(id);
    }
}

public class Main {
