class TestHarness {
  constructor(config) {
    this.config = config;
    this.retryStrategies = [];
    this.logger = null;
    this.concurrentLimit = 5; // initial concurrency limit
  }

  async runTests(moduleName) {
    try {
      const serviceModule = require(`./${moduleName}.js`);
      await this.executeTests(serviceModule, this.config);
    } catch (error) {
      console.error('Error running tests:', error);
    }
  }

  async executeTests(serviceModule, config) {
    const testQueue = [];
    for (const test of serviceModule.tests) {
      testQueue.push(test);
    }

    while (testQueue.length > 0) {
      await this.runTestLoop(testQueue, config.concurrentLimit);
    }
  }

  async runTestLoop(tests, concurrencyLimit) {
    const concurrentTests = [];
    for (let i = 0; i < concurrencyLimit && i < tests.length; i++) {
      concurrentTests.push(tests[i]);
    }

    try {
      await Promise.all(concurrentTests.map((test) => this.runTest(test)));
    } catch (error) {
      console.error('Error running test:', error);
    } finally {
      if (concurrencyLimit > 0 && tests.length > concurrencyLimit) {
        await new Promise((resolve) =>
          setTimeout(() => resolve(), this.config.retryTimeout)
        );
        await this.runTestLoop(tests.slice(concurrencyLimit), concurrencyLimit);
      }
    }
  }

  async runTest(test) {
    try {
      await test();
    } catch (error) {
      if (!this.config.ignoreErrors || error.name !== 'RetryError') {
        throw error;
      }
    }
  }

  log(message, level = 'info') {
    this.logger[level](message);
  }
}

module.exports = TestHarness;
