      try {
        const { code, dependencies } = script;
        const minifiedCode = minimizeJS(code);

        // Load and validate dependencies
        const depsLoaded = await loadDependencies(dependencies);

        // Load and render the script
        const renderedScript = `<script>${minifiedCode}</script>`;
        fsa.transition('loaded');
        resolve(renderedScript);
      } catch (error) {
        fsa.transition('errored');
        reject(error);
      }
    });
  }

  async function loadDependencies(dependencies) {
    const loadedDebs = [];

    for (const dep of dependencies) {
      try {
        if (dep.local) {
          // Load local dependency
          const code = await loadLocalDependency(dep);
          loadedDebs.push(code);
        } else {
          // Load external dependency with retry logic and fallback
          const code = await loadExternalDependency(dep, 3, 1000);
