          .then(response => response.text())
          .catch(error => console.error(`Error loading external dependency: ${error}`));

        return code;
      } catch (error) {
        if (retries < maxRetries - 1) {
          retries++;
          await timeout(timeout);
        } else {
          throw error;
        }
