    visualizeProgress
  };
}

class FiniteStateAutomaton {
  constructor() {
    this.state = 'idle';
  }

  transition(state) {
    this.state = state;

    switch (this.state) {
      case 'loaded':
        console.log('Script loaded and rendered');
        break;
      case 'errored':
        console.error('Error loading script');
        break;
      default:
        console.log('Idle');
    }
