  async updateConfig(configData) {
    try {
      // Validate config data
      if (!this.validateConfig(configData)) throw new Error('Invalid configuration');

      // Backup existing config file (timestamped)
      const backupPath = path.join(__dirname, `config_backup_${new Date().getTime()}.json`);
      fs.copyFile(path.join(__dirname, 'config.json'), backupPath);

      // Update the current config file
      await fs.promises.writeFile('config.json', JSON.stringify(configData));

      return { message: 'Config updated successfully' };
    } catch (error) {
      // Revert to previous state and notify operations team
      try {
        fs.copyFile(backupPath, path.join(__dirname, 'config.json'));
        await axios.post('https://reliable-notification-service.com', { error });
      } catch (e) {
        console.error(e);
      }
    }
  }

