using Amazon.S3;
using Amazon.S3.Model;
using Confluent.Kafka;
using Microsoft.Extensions.Logging;
using System;
using System.Threading;
using System.Threading.Tasks;

namespace LargeFileUploadService
{
    public class LargeFileUploadService : IFileUploadService
    {
        private readonly ILogger _logger;
        private readonly AmazonS3Client _s3Client;
        private readonly IKafkaProducer<string> _kafkaProducer;

        public LargeFileUploadService(ILogger<LargeFileUploadService> logger, 
            AmazonS3Client s3Client, IKafkaProducer<string> kafkaProducer)
        {
            _logger = logger;
            _s3Client = s3Client;
            _kafkaProducer = kafkaProducer;
        }

        public async Task UploadFileAsync(string bucketName, string key, Stream fileStream, int retryCount = 5)
        {
            await UploadFileAsync(bucketName, key, fileStream, retryCount, CancellationToken.None);
        }

        private async Task UploadFileAsync(string bucketName, string key, Stream fileStream, int retryCount, CancellationToken cancellationToken)
        {
            int attempts = 0;
            while (attempts < retryCount)
            {
                try
                {
                    using (var uploadRequest = new PutObjectRequest(bucketName, key, fileStream))
                    {
                        await _s3Client.PutObjectAsync(uploadRequest);
                    }
                    break; // File uploaded successfully, exit the loop
                }
                catch (AmazonS3Exception s3Error)
                {
                    if (s3Error.ErrorCode != null && s3Error.ErrorCode.Contains("Throttling"))
                    {
                        _logger.LogInformation("S3 throttling error, waiting before retrying.");
                        await Task.Delay(1000); // Wait 1 second
                    }
                    else
                    {
                        attempts++;
                        if (attempts < retryCount)
                        {
                            await Task.Delay(Math.Pow(2, attempts) * 1000); // Retry after exponential delay
                        }
                        else
                        {
                            _logger.LogError("Failed to upload file after {count} retries.", retryCount);
                            throw;
                        }
                    }
                }
                catch (OperationCanceledException)
                {
                    _logger.LogInformation("Upload cancelled.");
                    break; // Cancelled, exit the loop
                }
                catch (Exception ex)
                {
                    attempts++;
                    if (attempts < retryCount)
                    {
                        await Task.Delay(Math.Pow(2, attempts) * 1000); // Retry after exponential delay
                    }
                    else
                    {
                        _logger.LogError("Failed to upload file after {count} retries.", retryCount);
                        throw;
                    }
                }
            }
        }

        public async Task ProduceKafkaMessageAsync(string topicName, string key)
        {
            try
            {
                await _kafkaProducer.ProduceAsync(new Message<string> { Value = key, TopicPartition = new TopicPartition(topicName) });
            }
            catch (Exception ex)
            {
                _logger.LogError("Failed to produce Kafka message: {ex}", ex);
                throw;
            }
        }
    }

    public interface IFileUploadService
    {
        Task UploadFileAsync(string bucketName, string key, Stream fileStream);
    }
}
```

