['Here is a sample C# function to calculate the MD5 hash of a file given its path:

```csharp
using System;
using System.IO;
using System.Security.Cryptography;

public static string CalculateMD5Hash(string filePath)
{
    using (var md5 = MD5.Create())
    {
        using (var stream = File.OpenRead(filePath))
        {
            var buffer = new byte[0x10000];
            int read;
            while ((read = stream.Read(buffer, 0, buffer.Length)) > 0)
            {
                md5.TransformBlock(buffer, 0, read);
            }
            md5.TransformFinalBlock(buffer, read, buffer.Length - read);
        }

        return BitConverter.ToString(md5.Hash).Replace("-", string.Empty).ToLower();
    }
}
