    public void deserializeAndProcess(byte[] data) throws IOException {
        ObjectInputStream inputStream = null;
        try {
            inputStream = new ObjectInputStream(new ByteArrayInputStream(data));
            Object obj = inputStream.readObject();
            processSerializedObject(obj);
        } catch (ClassNotFoundException e) {
            handleDeserializationError(e, "Class not found");
        } finally {
            if (inputStream != null) {
                inputStream.close();
            }
        }
    }

    private void processSerializedObject(Object obj) {
        // Implement custom processing logic for the deserialized object
    }

    private void handleDeserializationError(Throwable t, String message) {
        // Log and log error handling logic
    }
}

