#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct for finite state automata
typedef struct {
    char *name;
    int initial_state;
    int num_states;
    int **transitions;
} FSA;

// Function to create an FSA
FSA* fsa_create(char *name, int initial_state, int num_states) {
    FSA* fsa = (FSA*)malloc(sizeof(FSA));
    fsa->name = name;
    fsa->initial_state = initial_state;
    fsa->num_states = num_states;
    fsa->transitions = (int**)malloc(num_states * sizeof(int*));
    for (int i = 0; i < num_states; i++) {
        fsa->transitions[i] = (int*)malloc(2 * sizeof(int));
    }
    return fsa;
}

// Function to add a transition to an FSA
void fsa_add_transition(FSA* fsa, int from_state, int input, int to_state) {
    fsa->transitions[from_state][0] = input;
    fsa->transitions[from_state][1] = to_state;
}

// Function to run the FSA and get the final state
int fsa_run(FSA* fsa, char *input_str) {
    int current_state = fsa->initial_state;
    for (char c : input_str) {
        int i;
        for (i = 0; i < fsa->num_states; i++) {
            if (fsa->transitions[i][0] == c && fsa->transitions[i][1] == current_state) {
                current_state = fsa->transitions[i][1];
                break;
            }
        }
    }
    return current_state;
}

// Function to free the FSA
void fsa_free(FSA* fsa) {
    for (int i = 0; i < fsa->num_states; i++) {
        free(fsa->transitions[i]);
    }
    free(fsa->transitions);
    free(fsa);
}
