#include <iostream>
#include <string>
#include <thread>
#include <mutex>
#include <queue>

class EventDrivenSystem {
public:
    void sendMessage(std::string message) {
        // Asynchronous message processing pipeline
        std::lock_guard<std::mutex> lock(mutex_);
        eventQueue_.push(message);
    }

private:
    std::mutex mutex_;
    std::queue<std::string> eventQueue_;

    void processEvents() {
        while (true) {
            if (!eventQueue_.empty()) {
                std::string message = eventQueue_.front();
                // Process the message
                eventQueue_.pop();
            }
            else {
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        }
    }

    void startProcessing() {
        thread_ = std::thread(&EventDrivenSystem::processEvents, this);
    }

    void stopProcessing() {
        if (thread_.joinable()) {
            thread_.join();
        }
    }

    std::thread thread_;
};

int main() {
    EventDrivenSystem system;
    system.startProcessing();

    // Send messages
    for (int i = 0; i < 10; ++i) {
        system.sendMessage("Message " + std::to_string(i));
    }

    system.stopProcessing();
    return 0;
}
