int main(int argc, char** argv) {
    std::map<std::string, std::string> options;
    bool help = false;
    std::string keyword = "";
    std::string output_file = "";
    int line_count = 0;

    for (int i = 1; i < argc; i++) {
        if (std::string(argv[i]) == "--help" || std::string(argv[i]) == "-h") {
            help = true;
        } else if (std::string(argv[i]).find("-k") == 0) {
            keyword = std::string(argv[i]).substr(2);
        } else if (std::string(argv[i]).find("-o") == 0) {
            output_file = std::string(argv[i]).substr(2);
        }
    }

    if (help || argc < 2) {
        std::cout << "Usage: " << argv[0] << " [input file] [-k <keyword>] [-o <output file>]" << std::endl;
        return 1;
    }

    std::ifstream input_file(argv[1]);
    if (!input_file.is_open()) {
        std::cerr << "Error opening input file: " << argv[1] << std::endl;
        return 1;
    }

    if (keyword != "") {
        while (input_file) {
            std::string line;
            std::getline(input_file, line);
            if (line.find(keyword) != std::string::npos) {
                line_count++;
            }
        }
    } else {
        while (std::getline(input_file, line)) {
            line_count++;
        }
    }

    input_file.close();

    if (output_file != "") {
        std::ofstream output(output_file);
        output << "Total lines: " << line_count << std::endl;
        output.close();
    } else {
        std::cout << "Total lines: " << line_count << std::endl;
    }

    return 0;
}
