func NewRecommendationSystem(providers ...DataProvider) *RecommendationSystem {
	rs := &RecommendationSystem{
		providers: make([]DataProvider, len(providers)),
	}
	for i, provider := range providers {
		rs.providers[i] = provider
	}
	rs.cache = make(map[string][]byte)
