	// Try to get data from the primary data source
	data, err := rs.getPrimaryData(ctx, userId)
	if err == nil {
		return data, nil
	}

	// If the primary data source fails, try alternative sources
	for _, provider := range rs.providers[1:] {
		data, err = rs.getAlternativeData(ctx, provider, userId)
		if err == nil {
