#include <iostream>
#include <thread>
#include <chrono>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>
#include <map>

class SensorData {
public:
    std::string sensor_id;
    int value;
    std::time_t timestamp;

    SensorData(std::string id, int val) : 
        sensor_id(id), value(val), timestamp(std::time(nullptr)) {}
};

class DataStream {
public:
    static const int MAX_BUFFER_SIZE = 1000;

    DataStream() : buffer_(new std::queue<SensorData>()), cond_(new std::condition_variable),
                 lock_(*new std::mutex) {}

    void push(SensorData data) {
        {
            std::unique_lock<std::mutex> ul(lock_);
            buffer_->push(data);
        }
        cond_->notify_one();
    }

    SensorData pop() {
        SensorData data;
        {
            std::unique_lock<std::mutex> ul(lock_);
            while (buffer_->empty()) {
                cond_->wait(ul);
            }
            data = buffer_->front();
            buffer_->pop();
        }
        return data;
    }

    void drain(std::function<void(SensorData)> consumer) {
        SensorData data;
        while (true) {
            std::unique_lock<std::mutex> ul(lock_);
            if (buffer_->empty()) {
                break;
            }
            data = buffer_->front();
            buffer_->pop();
            consumer(data);
        }
    }

private:
    std::unique_ptr<std::queue<SensorData>> buffer_;
    std::unique_ptr<std::condition_variable> cond_;
    std::unique_ptr<std::mutex> lock_;
};

class IoTDevice {
public:
    void start_streaming() {
        stream_thread_ = std::thread([this]() { this->stream_data(); });
    }

    void stop_streaming() {
        streaming_ = false;
        if (stream_thread_.joinable()) {
            stream_thread_.join();
        }
    }

private:
    void stream_data() {
        while (streaming_) {
            SensorData data;
            // Read sensor data from hardware
            // ...

            // Push data to the buffer
            DataStream::getInstance().push(data);
            std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate streaming rate
        }
    }

    bool streaming_;
    std::thread stream_thread_;
};

class IoTSystem {
public:
    void start_processing() {
        processing_thread_ = std::thread([this]() { this->process_data(); });
    }

    void stop_processing() {
        processing_ = false;
        if (processing_thread_.joinable()) {
            processing_thread_.join();
        }
    }

private:
    void process_data() {
        while (processing_) {
            SensorData data;
            // Consume data from the buffer
            DataStream::getInstance().drain([this, &data](SensorData d) {
                // Process sensor data
                // ...
            });
            std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate processing rate
        }
    }

    bool processing_;
    std::thread processing_thread_;
};

int main() {
    IoTDevice device;
    device.start_streaming();

    IoTSystem system;
    system.start_processing();

    // Use a timer to stop the streaming and processing after some time
    // ...

    return 0;
}

