#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <zlib.h>

typedef enum {
    OPTION_MANPAGE,
    OPTION_COUNT_SPACES,
    OPTION_OUTPUT_REDIRECT,
} Option;

void print_usage(char **argv) {
    printf("Usage: %s [options] input_file\n", argv[0]);
    printf("\t--manpage\tPrint this help message\n");
    printf("\t-cs\tCount spaces in the input file\n");
    printf("\t-o\tRedirect output to a file\n");
}

int main(int argc, char **argv) {
    int count_spaces = 0;
    int output_redirected = 0;

    Option option = OPTION_MANPAGE;

    while (argc > 1 && argv[1][0] == '-') {
        if (strcmp(argv[1], "--manpage") == 0) {
            print_usage(argv);
            return 0;
        } else if (strcmp(argv[1], "-cs") == 0) {
            count_spaces = 1;
        } else if (strcmp(argv[1], "-o") == 0) {
            output_redirected = 1;
        }
        argc--;
        argv++;
    }

    // Parse command-line arguments
    char *input_file = argv[argc - 1];

    FILE *file = fopen(input_file, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening file: %s\n", input_file);
        return 1;
    }

    int line_count = 0;

    while (!feof(file)) {
        char buffer[1024];

        // Read a chunk of the file
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);

        // Count lines and spaces in the chunk
        for (size_t i = 0; i < bytes_read; i++) {
            if (buffer[i] == '\n') {
                line_count++;
            } else if (count_spaces && buffer[i] == ' ') {
                count_spaces++;
            }
        }

        // Check if we reached the end of a line
        if (ferror(file)) {
            break;
        }
    }

    fclose(file);

    printf("Line count: %d\n", line_count);

    return 0;
}
