        for (Event event : highPriorityEvents) {
            // Perform any necessary processing or logging
        }
    }

    static class EventProcessorTask extends RecursiveAction {

        private List<Event> events;
        public EventProcessorTask(List<Event> events) { this.events = events; }

        @Override
        protected void compute() {
            if (events.size() > 10) {
                int midpoint = events.size() / 2;
                List<Event> left = new ArrayList<>(events.subList(0, midpoint));
                List<Event> right = new ArrayList<>(events.subList(midpoint, events.size()));

                invokeAll(new EventProcessorTask(left), new EventProcessorTask(right));
            } else {
                processLowPriorityEvents(events);
            }
        }

