typedef struct {
    int numOffsets;
    int numKeys;
} config_t;

config_t* config = NULL;

void initializeDatabase(config_t* config) {
    srand(time(NULL));

    // Dynamic and Scalable Memory Allocation
    long* offset = (long*)malloc(sizeof(long) * config->numOffsets);
    int* key = (int*)malloc(sizeof(int) * config->numKeys);

    if (!offset || !key) {
        for (int i = 0; i < config->numOffsets; i++) {
            free((void*)offset);
        }
        for (int i = 0; i < config->numKeys; i++) {
            free((void*)key);
        }
        return;
    }

    // Initialize offset with sequential values
    for (int i = 0; i < config->numOffsets; i++) {
        offset[i] = i;
    }

    // Initialize key with unique identifiers derived from offset and config->numKeys
    for (int i = 0; i < config->numKeys; i++) {
        key[i] = (int)(i * config->numOffsets);
    }

    int* records = (int*)malloc(sizeof(int) * config->numOffsets);

    if (!records) {
        for (int i = 0; i < config->numOffsets; i++) {
            free((void*)offset);
        }
        for (int i = 0; i < config->numKeys; i++) {
            free((void*)key);
        }
        return;
    }

    // Data Population and Randomization
    int minValue = -10000, maxValue = 10000;
    for (int i = 0; i < config->numOffsets; i++) {
        records[i] = rand() % (maxValue - minValue + 1) + minValue;
    }

    printf("Database initialized successfully!\n");
}
