function initDatabaseFromRemoteSource(remoteJsonFeedUrl, randomGenerator) {
  try {
    // Dynamic memory allocation and initialization
    const jsonData = await fetch(remoteJsonFeedUrl);
    if (!jsonData.ok) {
      throw new Error('Failed to load JSON data');
    }
    const { offset, key } = jsonData.json();
    const records = [];
    let allocSize = 0;
    for (let i = 0; i < offset.length; i++) {
      allocSize += sizeof(long);
      if (i > 0) {
        allocSize += sizeof(int); // Add padding between elements
      }
    }
    const ptr = malloc(allocSize);
    let ptrOffset = 0;
    for (let i = 0; i < offset.length; i++) {
      *(long*) (ptr + ptrOffset) = offset[i];
      ptrOffset += sizeof(long);
      records.push(key[i]);
    }

    // Data extraction and validation
    const { data } = jsonData.json();
    if (!Array.isArray(data)) {
      throw new Error('Invalid JSON data');
    }

    // Data transformation and population
    for (let i = 0; i < data.length; i++) {
      records.push(randomGenerator(minValue, maxValue));
    }

    // External database integration
    await dbConnect();
    try {
      // Persist initialized data to the external database
      await dbInsert(records);
    } catch (error) {
      // Roll back changes and log errors on failure
      await dbRollback();
      console.error('Error persisting data:', error);
    }

    free(ptr);
  } catch (error) {
    // Log detailed error messages and return NULL
    console.error('Error initializing database:', error);
    return null;
  }
}
