import org.apache.kafka.clients.consumer.ConsumerRecord;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;

public class EventStreamProcessor<T> {
    private final ExecutorService executor;
    private final EventProcessor<T> processor;
    private final Aggregator<T, U> aggregator;
    private final Sink<T> sink;
    private final BlockingQueue<ConsumerRecord<T>> queue;

    public EventStreamProcessor(ExecutorService executor, EventProcessor<T> processor, Aggregator<T, U> aggregator, Sink<T> sink) {
        this.executor = executor;
        this.processor = processor;
        this.aggregator = aggregator;
        this.sink = sink;
        this.queue = new LinkedBlockingQueue<>();
    }

    public void processEvent(T event) {
        // Process event using custom processors and aggregators
        T processedEvent = processor.process(event);
        U aggregatedValue = aggregator.aggregate(processedEvent);
        sink.send(aggregatedValue);
    }
}
