    private readonly object _syncLock = new();

    public void RegisterService(string serviceName, IExternalService service)
    {
        lock (_syncLock)
        {
            _services.Add(serviceName, service);
        }
    }

    public async Task<Vector3[]> GenerateSequenceAsync(int size)
    {
        var vectors = new List<Vector3>();

        foreach (var (serviceName, service) in _services)
        {
            while (!await IsServiceAvailableAsync(service))
            {
                await Task.Delay(100); // Wait for 100ms before retrying
            }

            try
            {
                if (!await ServiceIsReadyAsync(service))
                {
                    throw new Exception($"Service {serviceName} is not ready");
                }

                var sequence = await service.GenerateSequenceAsync(size);
                vectors.AddRange(sequence);
            }
            catch (Exception ex)
            {
                // Log the error and skip this service
                Console.WriteLine($"Error generating sequence from service {serviceName}: {ex.Message}");
            }
        }

        return vectors.ToArray();
    }

    public async Task ExecuteSecureCallbackAsync(Func<string, Task> callback, string password)
    {
        while (!await IsServiceAvailableAsync("AuthService"))
        {
            await Task.Delay(100); // Wait for 100ms before retrying
        }

        try
        {
            if (!await AuthServiceIsReadyAsync())
            {
                throw new Exception("Authentication service is not ready");
            }

            var result = await callback(password);
            return result;
        }
        catch (Exception ex)
        {
            // Log the error and fallback to another authentication mechanism
            Console.WriteLine($"Error executing secure callback: {ex.Message}");
        }
    }

    private async Task<bool> IsServiceAvailableAsync(IExternalService service) => await service.IsAvailableAsync();

    private async Task<bool> ServiceIsReadyAsync(IExternalService service) => await service.IsReadyAsync();

    private async Task<bool> AuthServiceIsReadyAsync() => await _services["AuthService"].IsReadyAsync();
}
