        // Verify the integrity of the populated structure against predefined checksums
        int checksum = i + (array[i]->RX_UE_INFORMATION_TAG * 100) + (array[i]->RNTI * 10);
        if (checksum != array[i]->CRC_INDICATION_REL8_TAG.crcFlag) {
