#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/types.h>
#include <pthread.h>

typedef struct {
    int key;
    long offset;
    time_t last_update;
    int valid;
} record;

record *records = NULL;
int records_count = 0;
pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_record(int key, long offset) {
    pthread_mutex_lock(&records_mutex);
    record *new_rec = (record *)malloc(sizeof(record));
    new_rec->key = key;
    new_rec->offset = offset;
    time(&new_rec->last_update);
    new_rec->valid = 1;
    records_count++;
    if (!records) {
        records = (record **)malloc(sizeof(record *));
        records[0] = new_rec;
    } else {
        record **tmp = (record **)realloc(records, sizeof(record *) * (records_count + 1));
        tmp[records_count - 1] = NULL;
        for (int i = 0; i < records_count; i++) {
            tmp[i] = records[i];
        }
        records = tmp;
    }
    pthread_mutex_unlock(&records_mutex);
}

void remove_record(int key) {
    pthread_mutex_lock(&records_mutex);
    record **tmp = (record **)malloc(sizeof(record *) * (records_count - 1));
    int j = 0;
    for (int i = 0; i < records_count; i++) {
        if (records[i]->key != key) {
            tmp[j++] = records[i];
        }
    }
    free(records);
    records = tmp;
    records_count--;
    pthread_mutex_unlock(&records_mutex);
}

void update_record(int key, long offset) {
    pthread_mutex_lock(&records_mutex);
    for (int i = 0; i < records_count; i++) {
        if (records[i]->key == key) {
            records[i]->offset = offset;
            time(&records[i]->last_update);
            return;
        }
    }
    pthread_mutex_unlock(&records_mutex);
}

void validate_records() {
    pthread_mutex_lock(&records_mutex);
    for (int i = 0; i < records_count; i++) {
        if (!records[i]->valid) {
            // Handle invalid record
        }
    }
    pthread_mutex_unlock(&records_mutex);
}

