#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <unistd.h>
#include <pthread.h>

// Define the maximum number of concurrent requests
#define MAX_CONCURRENT_REQUESTS 50000

// Define the size of the buffer for receiving data
#define BUFFER_SIZE 1024

// Structure to represent a connection
typedef struct {
    int sock;
    pthread_mutex_t mutex;
} Connection;

// Function to establish a new connection
Connection* establish_connection(int host, int port) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return NULL;
    }

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);

    if (connect(sock, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(sock);
        return NULL;
    }

    Connection* conn = malloc(sizeof(Connection));
    conn->sock = sock;
    pthread_mutex_init(&conn->mutex, NULL);
    return conn;
}

// Function to send data over a connection
void send_data(Connection* conn, char* data) {
    pthread_mutex_lock(&conn->mutex);
    send(conn->sock, data, strlen(data), 0);
    pthread_mutex_unlock(&conn->mutex);
}

// Function to receive data from a connection
char* receive_data(Connection* conn) {
    pthread_mutex_lock(&conn->mutex);
    char* buffer = malloc(BUFFER_SIZE);
    recv(conn->sock, buffer, BUFFER_SIZE - 1, 0);
    pthread_mutex_unlock(&conn->mutex);
    return buffer;
}

// Function to handle a request
void* handle_request(void* arg) {
    Connection* conn = (Connection*)arg;

    // Send data over the connection
    send_data(conn, "GET / HTTP/1.1\r\n");

    // Receive response from the server
    char* response = receive_data(conn);

    // Print the response
    printf("%s", response);

    free(response);
}

int main() {
    int num_threads;
    printf("Enter the number of threads: ");
    scanf("%d", &num_threads);

    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    Connection* conn;

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        conn = establish_connection(127, 80);
        if (!conn) {
            perror("establish_connection");
            continue;
        }

        // Start a new thread to handle the request
        pthread_create(&threads[i], NULL, handle_request, (void*)conn);

        // Manage concurrent connections
        for (int j = 0; j < i; j++) {
            pthread_join(threads[j], NULL);
            free(conn);
            conn = establish_connection(127, 80);
        }
    }

    return 0;
}

