    let best_gateway = determine_best_gateway(&payment_request);

    match best_gateway {
        Some(gateway) => {
            // initiate a connection to the chosen gateway
            let (stream, _) = TcpStream::connect(&gateway).await.unwrap();
            // send the payment request to the gateway
            stream.write_all(payment_request.serialize().as_bytes()).await.unwrap();

            // receive and process the response from the gateway
            let response = stream.read_until(b'\n', 1024).await.unwrap();
            let payment_result = PaymentResult::deserialize(&response);
            println!("Payment result: {:?}", payment_result);

            // handle any potential errors or exceptions that may occur during the payment processing
        }
