    loop {
        match listener.accept().await {
            Ok((stream, _)) => {
                println!("New connection from {:?}", stream.peer_addr());

                // process the payment request
                let (reader, writer) = stream.split();
                let payment_request = PaymentRequest::deserialize(&reader.read_until(b'\n', 1024).await.unwrap());
                process_payment(payment_request).await;

                // close the connection
                writer.write_all(b"Payment processed successfully.\n").await?;
