        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("https://config-service.example.com/config"))
            .header("Accept", "application/json")
            .build();

        // Fetch initial configuration settings from external service
        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
        ObjectMapper mapper = new ObjectMapper();
        JsonNode config = mapper.readTree(response.body());

        // Initialize firmware update ranges and policies based on real-time system metrics
        List<Pair<String, String>> firmwareUpdates = new ArrayList<>();
        for (JsonNode device : config.get("devices")) {
            if (device.has("firmware_update_range")) {
                firmwareUpdates.add(Pair.of(device.get("name").asText(), device.get("firmware_update_range").asText()));
            }
        }

        // Implement robust rollback strategy for critical failures
        try {
            // Update firmware and monitor devices in parallel using multi-threaded operations
            List<Thread> threads = new ArrayList<>();
            for (String deviceName : config.get("devices").fieldNames()) {
                Thread thread = new Thread(() -> {
                    try {
                        // Fetch device status and send OTA update request
