class LogAggregator {
public:
    LogAggregator() : running(true) {}

    void start() {
        std::thread t([this] { this->run(); });
        t.detach();
    }

    void stop() {
        running = false;
    }

private:
    bool running;

    void run() {
        while (running) {
            // Wait for new log messages
            std::unique_lock<std::mutex> lock(mutex);
            cond.wait(lock, [this] { return !logQueue.empty(); });

            // Process log message
            LogMessage message = logQueue.front();
            logQueue.pop();

            // Handle and store the log message

            // (Optional) Send the log message to other services or APIs
        }
    }

public:
    void addLog(const std::string& message) {
        std::unique_lock<std::mutex> lock(mutex);
        logQueue.push(LogMessage(message));
        cond.notify_one();
    }

private:
    std::mutex mutex;
    std::condition_variable cond;
    std::queue<LogMessage> logQueue;

};

class LogMessage {
public:
    LogMessage(const std::string& message) : message(message) {}

    const std::string& getMessage() const { return message; }

private:
    std::string message;
};
