def count_lines(filename):
    try:
        with open(filename) as f:
            return sum(1 for line in f)
    except Exception as e:
        logging.error(f"Error reading file: {e}")

def parse_args():
    parser = argparse.ArgumentParser(description="Count lines in a file")
    parser.add_argument("-o", "--output", help="Output redirection")
    parser.add_argument("-cs", "--count-spaces", action="store_true", help="Count spaces")
    parser.add_argument("--manpage", action="store_true", help="Show man page")
    parser.add_argument("filename", help="Input file name")
    return parser.parse_args()

if __name__ == "__main__":
    args = parse_args()
    if args.manpage:
        print(__doc__)
    else:
        try:
            lines = count_lines(args.filename)
            if args.count_spaces:
                spaces = sum(1 for line in open(args.filename) if " " in line)
                print(f"Lines: {lines}, Spaces: {spaces}")
            elif args.output:
                with open(args.output, "w") as f:
                    f.write(str(lines))
            else:
                print(f"Lines: {lines}")
        except Exception as e:
            logging.error(f"Error processing file: {e}")

