import socket
import json
import threading
import queue
import time
from collections import deque

class MessageProcessor:
    def __init__(self):
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.bind(('0.0.0.0', 8080))
        self.socket.listen(10)  # accept up to 10 connections
        self.buffer = queue.Queue(maxsize=10000)  # buffer for incoming messages
        self.prioritized_buffer = deque()  # buffer for prioritized messages
        self.paused = False  # flag for pausing message collection

    def start(self):
        while True:
            if not self.paused:
                connection, address = self.socket.accept()
                threading.Thread(target=self.process_message, args=(connection,)).start()

    def process_message(self, conn):
        try:
            while True:
                data = conn.recv(1024)
                if not data:
                    break
                message = json.loads(data.decode()) if data.startswith(b'{"') else bytearray(data)  # handle JSON or binary messages
                self.buffer.put(message)
                if self.paused:
                    time.sleep(0.1)  # pause for a short period when paused

        except ConnectionResetError:
            pass  # handle disconnection gracefully

    def prioritize_message(self, message, priority):
        self.prioritized_buffer.append((message, priority))
        self.buffer.get()  # remove oldest message from buffer to make room for prioritized one
        self.buffer.put(message)

    def pause_collection(self):
        self.paused = True

    def resume_collection(self):
        self.paused = False

    def handle_disconnection(self, conn):
        try:
            conn.close()
        except ConnectionResetError:
            pass  # handle disconnection gracefully

    def monitor_network(self):
        while True:
            if not self.paused:
                try:
                    self.socket.getsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE)  # keep connection alive
                except socket.error as e:
                    print(f"Error monitoring network: {e}")
            time.sleep(0.1)

    def run(self):
        threading.Thread(target=self.start).start()
        threading.Thread(target=self.monitor_network).start()

if __name__ == "__main__":
    processor = MessageProcessor()
    processor.run()
