#include <chrono>

class global_transaction_aggregator {
public:
    // Constructor
    global_transaction_aggregator() : transaction_queue(), aggregator_lock{}, is_shutdown(false) {}

    // Destructor
    ~global_transaction_aggregator() {
        shutdown();
    }

    // Start the aggregator
    void start() {
        if (!is_shutdown) {
            aggregator_thread = std::thread([this] { run(); });
        }
    }

    // Shutdown the aggregator
    void shutdown() {
        is_shutdown = true;
        transaction_queue.empty();
        aggregator_lock.lock();
        aggregator_lock.unlock();
        if (aggregator_thread.joinable()) {
            aggregator_thread.join();
        }
    }

    // Run the aggregator
    void run() {
        while (!is_shutdown) {
            std::unique_lock<std::mutex> lock(aggregator_lock);
            transaction_queue.wait(lock, [this] { return is_shutdown || !transaction_queue.empty(); });
            if (is_shutdown) break;
            auto transaction = transaction_queue.front();
            transaction_queue.pop();

            // Process the transaction
            processTransaction(transaction);

            lock.unlock();
        }
    }

    // Add a transaction to the queue
    void addTransaction(const std::string& transaction) {
        std::lock_guard<std::mutex> lock(aggregator_lock);
        transaction_queue.push(transaction);
    }

private:
    std::queue<std::string> transaction_queue;
    std::mutex aggregator_lock;
    std::condition_variable transaction_queue_cond;
    bool is_shutdown;
    std::thread aggregator_thread;

    // Process a transaction
    void processTransaction(const std::string& transaction) {
