    private readonly List<SqlConnection> _sqlConnections = new();
    private readonly List<IMongoDatabase> _mongoDatabases = new();

    public void AddFsa(string name, Fsa fsa)
    {
        _fsas.Add(name, fsa);
    }

    public void Start()
    {
        foreach (var sqlConnection in _sqlConnections)
        {
            sqlConnection.Open();
        }

        foreach (var mongoDatabase in _mongoDatabases)
        {
            mongoDatabase.Connect();
        }
    }

    public void Stop()
    {
        foreach (var sqlConnection in _sqlConnections)
        {
            sqlConnection.Close();
        }

        foreach (var mongoDatabase in _mongoDatabases)
        {
            mongoDatabase.Disconnect();
        }
    }

