import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.filter.OncePerRequestFilter;

public class JWTAuthFilter extends OncePerRequestFilter {
    private AuthenticationManager authenticationManager;

    public JWTAuthFilter(AuthenticationManager authenticationManager) {
        this.authenticationManager = authenticationManager;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            throws ServletException, IOException {
        // Authenticate requests using JSON Web Tokens (JWT)
        String token = request.getHeader("Authorization");
        if (token != null) {
            try {
                JwsVerifier verifier = Jwts.parser().setSigningKey(Base64.getEncoder().encodeToString("secret".getBytes()));
                UsernamePasswordAuthenticationToken authenticationToken = new UsernamePasswordAuthenticationToken(
                        verifier.extractClaims(token), null, getAuthorities());
                SecurityContextHolder.getContext().setAuthentication(authenticationToken);
            } catch (SignatureException e) {
                logger.error("Invalid JWT token: {}", token);
            }
        }
    }

    private List<GrantedAuthority> getAuthorities() {
        // Return a list of authorities for the authenticated user
