public class PaymentRetryMechanism {
    public async Task processPaymentAsync(PaymentRequest request) {
        int attempts = 0;
        while (attempts < 3) {
            try {
                await processPayment(request);
                break;
            } catch (Exception ex) {
                if (ex is GatewayTimeoutException || ex is NetworkError) {
                    // Retry with exponential backoff
                    await Task.Delay(ExponentialBackoff(attempts));
                }
            }
        }
    }
}
