['Here is a sample code block for designing a scalable, resilient data ingestion pipeline for a high-throughput log aggregation system:

```python
import logging
from datetime import datetime
from kafka import KafkaProducer
from splunklib.modularinputs import *
from elasticsearch import Elasticsearch

class LogIngestionPipeline:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.kafka_producer = KafkaProducer(bootstrap_servers=['kafka:9092'])
        self.elasticsearch = Elasticsearch([{'host': 'elasticsearch', 'port': 9200}])

    def process_log(self, log_data):
        # Handle data partitioning and sharding strategies
        shard_key = log_data['shard_key']
        partition_key = log_data['partition_key']

        if shard_key == "A":
            self.elasticsearch.index(index="log-index-A", body=log_data)
        elif shard_key == "B":
            self.elasticsearch.index(index="log-index-B", body=log_data)

    def handle_duplicates(self, log_data):
        # Detect and mitigate data duplication
        existing_logs = self.elasticsearch.search(index="log-index-*", body={"query": {"term": {"message": log_data['message']}}})
        if existing_logs['hits']['total'] > 0:
            return

        self.process_log(log_data)

    def handle_anomalies(self, log_data):
        # Detect and mitigate anomalies
        if log_data['anomaly_score'] > 5:
            self.handle_duplicates(log_data)
        else:
            self.process_log(log_data)

    def handle_missing_logs(self):
        # Handle missing logs due to transient network issues or endpoint outages
        missing_logs = self.elasticsearch.search(index="log-index-*", body={"query": {"exists": {"field": "message"}}}})
        if missing_logs['hits']['total'] > 0:
            for log in missing_logs['hits']['hits']:
                self.process_log(log['_source'])

    def start_pipeline(self):
        while True:
            try:
                logs = self.kafka_consumer.consume()
                for log in logs:
                    self.handle_duplicates(log)
                    self.handle_anomalies(log)
                    self.handle_missing_logs()
            except Exception as e:
                self.logger.error("Error processing logs: {}".format(e))
                time.sleep(1)

if __name__ == "__main__":
    pipeline = LogIngestionPipeline()
    pipeline.start_pipeline()

```

This code block provides a basic implementation of the log ingestion pipeline, including data partitioning and sharding strategies, duplicate detection and mitigation, anomaly detection and mitigation, and handling of missing logs. It also integrates with Elasticsearch for indexing and Splunk for visualization.

