class ScriptService {
  #apiEndpoints = {
    scripts: 'https://script-api.com/templates',
    numbers: 'https://number-api.com/values'
  };

  async getScripts() {
    try {
      const response = await fetch(this.#apiEndpoints.scripts);
      if (!response.ok) throw new Error('Failed to retrieve script templates');
      const templates = await response.json();
      return templates.map((template, index) => `<script id="script-${index}">${template}</script>`);
    } catch (error) {
      console.error(error);
      throw error;
    }
  }

  async reduceNumbers(numbers) {
    try {
      return numbers.reduce(async (accumulator, currentNumber, index) => {
        const cumulativeValue = await accumulator + currentNumber;
        return cumulativeValue;
      }, 0);
    } catch (error) {
      console.error(error);
      throw error;
    }
  }

  async renderScripts(scripts) {
    try {
      return Promise.all(scripts.map(script => {
        const scriptElement = document.createElement('div');
        scriptElement.innerHTML = script;
        return scriptElement;
      }));
    } catch (error) {
      console.error(error);
      throw error;
    }
  }

  async renderAndReduce() {
    try {
      const scripts = await this.getScripts();
      const numbers = [1, 2, 3, 4, 5];
      const cumulativeValue = await this.reduceNumbers(numbers);
      const renderedScripts = await this.renderScripts(scripts);

      // Handle rendered and reduced results as needed
      console.log('Rendered scripts:', renderedScripts);
      console.log('Cumulative value:', cumulativeValue);
    } catch (error) {
      console.error(error);
    }
  }

  #cache = {};

  async getScriptTemplate(id) {
    if (!this.#cache[id]) {
      const response = await fetch(`${this.#apiEndpoints.scripts}/${id}`);
      this.#cache[id] = await response.json();
    }
    return this.#cache[id];
  }

  async getNumber(valueId) {
    try {
      const response = await fetch(`${this.#apiEndpoints.numbers}/${valueId}`);
      if (!response.ok) throw new Error('Failed to retrieve number value');
      return await response.json();
    } catch (error) {
      console.error(error);
      throw error;
    }
  }

  async renderAndReduceAsync() {
    try {
      const scripts = await Promise.all(Object.keys(this.#cache).map(async id => {
        const template = await this.getScriptTemplate(id);
        return `<script id="script-${id}">${template}</script>`;
      }));

      const numbers = [1, 2, 3, 4, 5];
      const cumulativeValue = await this.reduceNumbers(numbers);

      // Handle rendered and reduced results as needed
      console.log('Rendered scripts:', scripts);
      console.log('Cumulative value:', cumulativeValue);
    } catch (error) {
      console.error(error);
    }
  }

  async init() {
    try {
      await this.renderAndReduceAsync();
    } catch (error) {
      console.error(error);
    }
  }
}

