class LogService(ABC):
    @abstractmethod
    async def send_log(self, log_message: str) -> None:
        pass

class FileLogService(LogService):
    def __init__(self, filename: str):
        self.filename = filename

    async def send_log(self, log_message: str) -> None:
        with open(self.filename, 'a') as file:
            file.write(f'{time.asctime()} - {log_message}\n')

class ConsoleLogService(LogService):
    async def send_log(self, log_message: str) -> None:
        print(log_message)

class LoggerConfig:
    def __init__(self, log_level: int = logging.INFO, 
                 log_format: str = '%(asctime)s - %(name)s - %(levelname)s - %(message)s',
                 output_channel: str = 'console'):
        self.log_level = log_level
        self.log_format = log_format
        self.output_channel = output_channel

class LoggingFramework:
    def __init__(self, config: LoggerConfig):
        self.config = config
        self.loggers = []
        self.log_service = None

    def add_logger(self, logger: Logger) -> None:
        self.loggers.append(logger)

    async def log(self, message: str) -> None:
        for logger in self.loggers:
            await logger.log(message)

    async def start_log_service(self) -> None:
        if self.config.output_channel == 'file':
            self.log_service = FileLogService(filename='logs.txt')
        elif self.config.output_channel == 'console':
            self.log_service = ConsoleLogService()
        else:
            # Add support for other output channels
            pass

    async def run(self) -> None:
        await asyncio.create_task(self.start_log_service())
        while True:
            try:
                message = input('Enter a log message: ')
                await self.log(message)
            except KeyboardInterrupt:
                break

if __name__ == '__main__':
    config = LoggerConfig(log_level=logging.INFO, output_channel='console')
    logging_framework = LoggingFramework(config)
    logging_framework.add_logger(ConsoleLogger())
    asyncio.run(logging_framework.run())

