use reqwest;
use serde_json::json;
use std::error::Error;
use tower::{Service, ServiceBuilder};
use towerhttp::attach;

#[derive(Debug)]
pub struct SecureAccountSetup {
    vault_service: String,
    terraform_config: String,
    cloudformation_template: String,
}

impl SecureAccountSetup {
    pub fn new(
        vault_service: String,
        terraform_config: String,
        cloudformation_template: String,
    ) -> Self {
        SecureAccountSetup {
            vault_service,
            terraform_config,
            cloudformation_template,
        }
    }

    pub async fn deploy(&self) -> Result<(), Box<dyn Error>> {
        let terraform_provider = TerraformProvider::new(self.terraform_config.clone())?;
        let cloudformation_stack = CloudFormationStack::new(self.cloudformation_template.clone())?;

        match self.vault_service.as_str() {
            "HashiCorp" => {
                // HashiCorp Vault setup
                println!("Setting up HashiCorp Vault...");
                vault_service_setup(&self).await?;
            }
            "AWS" => {
                // AWS Secret Manager setup
                println!("Setting up AWS Secret Manager...");
                aws_secret_manager_setup(&self).await?;
            }
            _ => return Err("Unsupported vault service".into()),
        };

        let services = vec![
            Service::new(terraform_provider)
                .add_service(ServiceBuilder::new(cloudformation_stack)),
        ];

        let mut builder = ServiceBuilder::new();
        for service in services {
            builder = builder.then(service);
        }

        let service = builder.build();

        match service.run().await {
            Ok(_) => println!("Account setup completed successfully!"),
            Err(err) => return Err(err.into()),
        };

        Ok(())
    }
}

async fn vault_service_setup(secure_account_setup: &SecureAccountSetup) -> Result<(), Box<dyn Error>> {
    // HashiCorp Vault setup implementation
    let client = reqwest::blocking::Client::new();
    let response = client
        .post("https://vault.example.com/v1/secrets")
        .json(&json!({
            "name": "secure-account",
            "description": "Secure account setup for multi-cloud environment",
            "policy": "path/to/policy.hcl"
        }))
        .send()?;

    match response.status().as_u16() {
        201 => Ok(()),
        _ => Err("Vault service setup failed".into()),
    }
}

async fn aws_secret_manager_setup(secure_account_setup: &SecureAccountSetup) -> Result<(), Box<dyn Error>> {
    // AWS Secret Manager setup implementation
    let client = reqwest::blocking::Client::new();
    let response = client
        .post("https://secretsmanager.example.com/v1/secrets")
        .json(&json!({
            "name": "secure-account",
            "description": "Secure account setup for multi-cloud environment"
        }))
        .send()?;

    match response.status().as_u16() {
        201 => Ok(()),
        _ => Err("AWS Secret Manager setup failed".into()),
    }
}
