<?php
class DynamicWebAppConfigurator {
    private $cache;
    private $processors;

    public function __construct() {
        $this->cache = new Memcached();
        $this->processors = array();
    }

    public function registerProcessor($name, $processor) {
        $this->processors[$name] = $processor;
    }

    public function configureFiles($files, $batchSize = 1000) {
        foreach ($files as $file) {
            $data = json_decode(file_get_contents($file), true);
            if (!empty($data)) {
                try {
                    $this->processFileData($data);
                } catch (Exception $e) {
                    error_log("Error processing file: " . $file . ": " . $e->getMessage());
                }
            }
        }
    }

    private function processFileData($data) {
        if (isset($data['sequence'])) {
            usort($data, function ($a, $b) {
                return $a['sequence'] - $b['sequence'];
            });

            foreach ($data as &$fileData) {
                $this->processFile($fileData);
            }
        } else {
            $this->processFile($data);
        }
    }

    private function processFile($fileData) {
        if (isset($fileData['config'])) {
            try {
                $processor = array_key_exists('processor', $fileData) ? 
                    $this->processors[$fileData['processor']] : 
                    null;

                if ($processor) {
                    $processor->process($fileData['config']);
                } else {
                    echo "Unsupported processor for file: " . json_encode($fileData);
                }
            } catch (Exception $e) {
                error_log("Error processing file: " . json_encode($fileData) . ": " . $e->getMessage());
            }
        }
    }

    public function getCache() {
        return $this->cache;
    }
}
