        // Insert point into the octree
        std::lock_guard<std::mutex> lock(mutex_);
        if (root_ == nullptr) {
            root_.reset(new OctreeNode(lat, lon));
        } else {
            root_->insertPoint(lat, lon);
        }
    }

    void queryNearestNeighbor(double lat, double lon, int k) {
        // Perform nearest neighbor query on the octree
        std::unique_lock<std::mutex> lock(mutex_);
        if (root_ == nullptr) {
            return;
        } else {
            root_->queryNearestNeighbor(lat, lon, k);
        }
    }

