private:
    std::map<std::string, DatabaseInterface*> databases;
    std::mutex database_mutex;
    std::condition_variable database_condition;

public:
    SynchronizationService(std::vector<DatabaseInterface*>& databases) : databases(databases) {}

    void synchronize(const std::vector<NFAPI_CRC_INDICATION_PDU_T>& pdus) {
        for (auto& database : databases) {
            std::unique_lock<std::mutex> lock(database_mutex);
            while (!database->isReady()) {
                database_condition.wait(lock);
            }
            database->store(pdus);
        }
    }

    void retrieve() {
        for (auto& database : databases) {
            std::unique_lock<std::mutex> lock(database_mutex);
            database->retrieve();
        }
    }
