public static class ImageProcessor
{
    public static string CalculateMd5Hash(string filePath)
    {
        using (var md5 = MD5.Create())
        {
            byte[] buffer = new byte[1024 * 64]; // adjust this value based on your system's memory constraints
            using (var stream = File.OpenRead(filePath))
            {
                int bytesRead;
                while ((bytesRead = stream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    md5.TransformBlock(buffer, 0, bytesRead);
                }
                var hashValue = md5.Hash;
                return BitConverter.ToString(hashValue).Replace("-", string.Empty).ToLower();
            }
        }
    }
}
