    public class DataDecryptorService : IDataDecryptorService
    {
        private readonly IKMSClient _kmsClient;
        private readonly ILogger _logger;
        private readonly IConcurrencyHandler _concurrencyHandler;

        public DataDecryptorService(IKMSClient kmsClient, ILogger logger, IConcurrencyHandler concurrencyHandler)
        {
            _kmsClient = kmsClient;
            _logger = logger;
            _concurrencyHandler = concurrencyHandler;
        }

        public async Task DecryptDataAsync(string filePath)
        {
            try
            {
                using (var fileStream = File.OpenRead(filePath))
                {
                    var encryptionKey = await _kmsClient.GetEncryptionKeyAsync();
                    var initializationVector = await _kmsClient.GetInitializationVectorAsync();

                    using (var aesAlg = Aes.Create())
                    {
                        aesAlg.Key = encryptionKey;
                        aesAlg.IV = initializationVector;

                        using (var decryptor = aesAlg.CreateDecryptor())
                        {
                            int buffer_size = 256;
                            byte[] buffer = new byte[buffer_size];
                            int count = fileStream.Read(buffer, 0, buffer_size);

                            while (count > 0)
                            {
                                var decryptedBuffer = decryptor.TransformFinalBlock(buffer, 0, count);
                                await _concurrencyHandler.ProcessDecryptedDataAsync(decryptedBuffer);
                                count = fileStream.Read(buffer, 0, buffer_size);
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
        }
    }

