        public DataIngestionService(WebSocket[] webSockets)
        {
            _webSockets = webSockets;
        }

        public async Task Start()
        {
            foreach (var ws in _webSockets)
            {
                await EstablishConnection(ws);
            }
        }

        private async Task EstablishConnection(WebSocket ws)
        {
            while (!_cts.IsCancellationRequested)
            {
                try
                {
                    await ws.Send("Heartbeat", WebSocketMessageType.Text, true, CancellationToken.None);
                    await Task.Delay(TimeSpan.FromMilliseconds(100), _cts.Token);

                    if (await CheckForData(ws) != null)
                    {
                        // Handle data ingestion and processing here
