    [ApiController]
    [Route("api/[controller]")]
    public class XmlController : ControllerBase
    {
        private readonly HttpClient _httpClient;
        private readonly IMemoryCache _cache;
        private readonly string _baseUrl;

        public XmlController(HttpClient httpClient, IMemoryCache cache, string baseUrl)
        {
            _httpClient = httpClient;
            _cache = cache;
            _baseUrl = baseUrl;
        }

        [HttpGet]
        public async Task<IActionResult> GetXml(string id)
        {
            try
            {
                // Check if the XML document is already cached
                if (_cache.TryGetValue(id, out XDocument xml))
                {
                    return Ok(xml);
                }

                // Fetch the XML document from the external API
                HttpResponseMessage response = await _httpClient.GetAsync($"{_baseUrl}/{id}");
                response.EnsureSuccessStatusCode();

                // Parse the XML document and store it in the cache
                xml = XDocument.Parse(await response.Content.ReadAsStringAsync());
                _cache.Set(id, xml, new MemoryCacheEntryOptions
                {
                    SlidingExpiration = TimeSpan.FromHours(1)
                });

                return Ok(xml);
            }
            catch (HttpRequestException ex) when (ex.Message.Contains("Network unavailable"))
            {
                // Handle network unavailable error
                throw new NetworkUnavailableException();
            }
            catch (HttpRequestException ex) when (ex.Message.Contains("Invalid XML data"))
            {
                // Handle invalid XML data error
                throw new InvalidXmlException();
            }
            catch (Exception ex)
            {
                // Handle general exception
                throw;
            }
        }

        [HttpPost]
        public async Task<IActionResult> PostXml([FromBody] XDocument xml)
        {
            try
            {
                // Validate the XML document and perform any necessary transformations
                xml = await ValidateAndTransformXml(xml);

                // Store the XML document in the cache with a sliding expiration of 1 hour
                _cache.Set("xml", xml, new MemoryCacheEntryOptions
                {
                    SlidingExpiration = TimeSpan.FromHours(1)
                });

                return Ok();
            }
            catch (Exception ex)
            {
                // Handle general exception
                throw;
            }
        }

        private async Task<XDocument> ValidateAndTransformXml(XDocument xml)
        {
            // Implement XML validation and transformation logic here
            return await Task.FromResult(xml);
        }
    }
}
