        {
            if (!AreBoundsEqual(lowerBound, upperBound)) 
                throw new ArgumentException("Invalid bounds for uniform distribution.");

            var range = (T)_upperBound - (T)lowerBound;
            return (T)((T)random.NextDouble() * range + (T)lowerBound);
        }

        public static bool AreBoundsEqual(T lowerBound, T upperBound)
        {
            return AreVectorsEqual(new Vector3(lowerBound), new Vector3(upperBound));
        }
