class MessageBroker {
public:
    // Constructor
    MessageBroker() : brokerId(1), messageQueue(), ackMode("at-least-once") {}

    // Method to send a message
    void sendMessage(int id, const string& message) {
        messageQueue.push({id, message});
    }

    // Method to receive messages
    vector<string> receiveMessages(int numMessages) {
        vector<string> receivedMessages;
        for (int i = 0; i < numMessages; i++) {
            Message msg = messageQueue.front();
            messageQueue.pop();
            receivedMessages.push_back(msg.message);
        }
        return receivedMessages;
    }

private:
