    int from_state;
    int to_state;
    char *transition_name;
} FsaTransition;

// Define a structure for the FSA module
typedef struct {
    FsaNode **nodes;
    FsaTransition **transitions;
    pthread_mutex_t mutex;
} FsaModule;

// Function to initialize the FSA module
void init_fsa(FsaModule *fsa, int num_nodes) {
    fsa->nodes = (FsaNode **)malloc(num_nodes * sizeof(FsaNode *));
    fsa->transitions = (FsaTransition **)malloc(num_nodes * sizeof(FsaTransition *));
}

// Function to add a node to the FSA
void add_node(FsaModule *fsa, int state_id, char *name) {
    FsaNode *node = (FsaNode *)malloc(sizeof(FsaNode));
    node->state_id = state_id;
    node->name = name;
    fsa->nodes[state_id] = node;
}

// Function to add a transition to the FSA
void add_transition(FsaModule *fsa, int from_state, int to_state, char *transition_name) {
    FsaTransition *transition = (FsaTransition *)malloc(sizeof(FsaTransition));
    transition->from_state = from_state;
    transition->to_state = to_state;
    transition->transition_name = transition_name;
    fsa->transitions[from_state] = transition;
}

// Function to run the FSA
void run_fsa(FsaModule *fsa, int start_state) {
    int current_state = start_state;
    while (current_state != -1) {
        // Get the next state based on the current state and transitions
        FsaTransition *transition = fsa->transitions[current_state];
        if (transition == NULL) {
            break;  // No more transitions for this state, exit loop
        }
        int next_state = transition->to_state;

        // Perform any actions required when transitioning from current to next state

        current_state = next_state;
    }
}

// Function to free the FSA module
void free_fsa(FsaModule *fsa) {
    for (int i = 0; i < fsa->num_nodes; i++) {
        if (fsa->nodes[i] != NULL) {
            free(fsa->nodes[i]);
        }
        if (fsa->transitions[i] != NULL) {
            free(fsa->transitions[i]);
        }
    }
    free(fsa->nodes);
    free(fsa->transitions);
}
