typedef struct {
    int state;
    struct transition *next;
} transition;

typedef struct {
    int num_states;
    transition *states;
} fsa;

fsa* create_fsm(int num_states, int* states) {
    fsa* fsm = (fsa*)malloc(sizeof(fsa));
    fsm->num_states = num_states;
    fsm->states = (transition*)malloc(num_states * sizeof(transition));
    for (int i = 0; i < num_states; i++) {
        fsm->states[i].state = states[i];
        fsm->states[i].next = NULL;
    }
    return fsm;
}

void free_fsm(fsa* fsm) {
    if (fsm == NULL) return;
    for (int i = 0; i < fsm->num_states; i++) {
        transition* current_state = &fsm->states[i];
        while (current_state != NULL) {
            transition* next_state = current_state->next;
            free(current_state);
            current_state = next_state;
        }
    }
    free(fsm);
}

int main() {
    int num_states = 5;
    int states[] = {0, 1, 2, 3, 4};
    fsa* fsm = create_fsm(num_states, states);
    // use the FSM
    free_fsm(fsm);
    return 0;
}
