import { promises as fs } from 'fs';
import { readFileSync } from 'fs';
import { join } from 'path';
import { JSONSchemaValidator } from 'json-schema-validator';
import axios from 'axios';
import log4js from 'log4js';

// Define the logging setup
const log = log4js.getLogger('file-processor');

// Define the schema validation function
async function validateFile(file, schema) {
  try {
    const fileContent = readFileSync(file.path, 'utf8');
    const validatedData = JSONSchemaValidator.validate(fileContent, schema);
    return validatedData;
  } catch (error) {
    log.error(`Error validating ${file.name}: ${error.message}`);
    throw error;
  }
}

// Define the report generation function
async function generateReport(files, schema) {
  try {
    const reports = files.map((file) => ({
      fileName: file.name,
      isValid: await validateFile(file, schema),
    }));
    return { reports };
  } catch (error) {
    log.error(`Error generating report: ${error.message}`);
    throw error;
  }
}

// Define the main processing function
async function processFiles(directory, schemaUrl) {
  try {
    // Get the list of files in the directory
    const files = await fs.readdir(directory);

    // Make API call to retrieve the schema
    const response = await axios.get(schemaUrl);
    const schema = response.data;

    // Process each file concurrently
    const reports = await Promise.all(files.map((file) => generateReport([file], schema)));

    // Generate the aggregated report
    const aggregatedReport = reports.reduce((acc, current) => ({ ...acc, ...current.reports }), {});

    return aggregatedReport;
  } catch (error) {
    log.error(`Error processing files: ${error.message}`);
    throw error;
  }
}

// Example usage
const directory = './files';
const schemaUrl = 'https://example.com/schema.json';

processFiles(directory, schemaUrl).then((report) => console.log(report));
