            char device_id[20];
            char protocol_used[10];
        } user_connection_info;
        struct {
            float latency_avg;
            float packet_loss_rate;
            float throughput_avg;
        } network_performance_metric;
    } payload;
} NetworkEvent;

typedef struct Node {
    NetworkEvent event;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int events_count;
} NetworkEventList;

NetworkEventList ne_list = {NULL, NULL, PTHREAD_MUTEX_INITIALIZER, 0};

void insert_at_head(NetworkEvent event) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(1);
    }
    new_node->event = event;
    new_node->prev = NULL;
    new_node->next = ne_list.head;
    if (ne_list.head) {
        ne_list.head->prev = &new_node->event;
    } else {
        ne_list.tail = &new_node->event;
    }
    ne_list.head = new_node;
}

void insert_at_tail(NetworkEvent event) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(1);
    }
    new_node->event = event;
    new_node->prev = ne_list.tail;
    new_node->next = NULL;
    if (ne_list.tail) {
        ne_list.tail->next = &new_node->event;
    } else {
        ne_list.head = &new_node->event;
    }
    ne_list.tail = new_node;
}

void free_nodes() {
    Node* temp = ne_list.head;
    while (temp) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
    ne_list.head = NULL;
    ne_list.tail = NULL;
}

int main(int argc, char** argv) {
    pthread_t thread;
    pthread_create(&thread, NULL, capture_events, NULL);
    return 0;
}
