// cell_measurement_report.h
#ifndef CELL_MEASUREMENT_REPORT_H
#define CELL_MEASUREMENT_REPORT_H

#include <stdint.h>
#include <stdlib.h>

typedef struct {
    uint32_t cell_id;
    int16_t rsrp;
    int16_t rsrq;
    // add more fields as needed
} CellMeasurementReport;

#endif  // CELL_MEASUREMENT_REPORT_H

// cell_measurement_report_lib.c
#include "cell_measurement_report.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Global hash table to store CellMeasurementReports by cell ID
typedef struct {
    uint32_t cell_id;
    CellMeasurementReport* report;
} ReportHashEntry;

#define REPORT_HASH_TABLE_SIZE 1024

ReportHashEntry report_hash_table[REPORT_HASH_TABLE_SIZE];

void add_report(uint32_t cell_id, int16_t rsrp, int16_t rsrq) {
    // Find the corresponding hash entry
    uint32_t index = cell_id % REPORT_HASH_TABLE_SIZE;
    ReportHashEntry* entry = &report_hash_table[index];

    // Create a new report if none exists for this cell ID
    if (!entry->report) {
        entry->report = (CellMeasurementReport*)malloc(sizeof(CellMeasurementReport));
        *entry->report = (CellMeasurementReport){.cell_id = cell_id, .rsrp = rsrp, .rsrq = rsrq};
    } else {
        // Update the existing report
        entry->report->rsrp = rsrp;
        entry->report->rsrq = rsrq;
    }
}

double calculate_average_signal_quality(uint32_t cell_id) {
    uint32_t index = cell_id % REPORT_HASH_TABLE_SIZE;
    ReportHashEntry* entry = &report_hash_table[index];

    if (!entry->report) {
        return 0.0; // no reports for this cell ID
    }

    int16_t sum_rsrp = 0;
    int16_t sum_rsrq = 0;
    uint32_t count = 1;

    while (count > 0 && entry->report) {
        sum_rsrp += entry->report->rsrp;
        sum_rsrq += entry->report->rsrq;
        --count;

        // Move to the next hash entry
        index = (index + 1) % REPORT_HASH_TABLE_SIZE;
        entry = &report_hash_table[index];
    }

    return (double)(sum_rsrp + sum_rsrq) / count;
}

void remove_report(uint32_t cell_id) {
    uint32_t index = cell_id % REPORT_HASH_TABLE_SIZE;
    ReportHashEntry* entry = &report_hash_table[index];

    if (!entry->report) {
        return; // no report for this cell ID
    }

    free(entry->report);
    entry->report = NULL;
}

// ... (rest of the library implementation)
