class BatchProcessor {
public:
    void transformBatch(const std::function<void()>& processBatch) {
        std::mutex mtx;
        std::condition_variable cv;
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return !batches.empty(); });

        for (auto& batch : batches) {
            processBatch();

            // Handle partial failures
            if (!batch) {
                // Retry or fallback mechanism here
                std::cout << "Partial failure. Retrying..." << std::endl;
                cv.notify_one();
                return;
            }

            // Process the batch successfully
            std::cout << "Processed batch successfully." << std::endl;
        }

        // All batches processed, notify waiting threads
        cv.notify_all();
    }

    void addBatch(const std::function<void()>& processBatch) {
        // Add batch to queue and signal processing thread
        {
            std::unique_lock<std::mutex> lock(mtx);
            batches.push(processBatch);
        }
        cv.notify_one();
    }

private:
    std::queue<std::function<void()>> batches;
    std::mutex mtx;
    std::condition_variable cv;
};

int main() {
    BatchProcessor processor;

    // Example usage
    auto processBatch = [] {
        // Simulate processing a batch
        for (int i = 0; i < 10000; ++i) {
            // Some processing code here
            if (rand() % 2 == 0) {
                std::cout << "Error occurred during processing." << std::endl;
                return false; // Simulate partial failure
            }
        }
        return true; // Processed batch successfully
    };

    processor.addBatch(processBatch);
    processor.transformBatch(processBatch);

    return 0;
}
