// Structure to represent a cell measurement report
typedef struct {
    int cell_id;
    float rsrp;
    float rsrq;
} CellMeasurementReport;

// Structure to manage the collection of reports
typedef struct {
    pthread_mutex_t lock; // Lock for thread-safe operations
    size_t num_reports;
    CellMeasurementReport* reports;
} ReportCollection;

// Function to add a report to the collection
void add_report(ReportCollection* collection, int cell_id, float rsrp, float rsrq) {
    pthread_mutex_lock(&collection->lock);

    // Allocate memory for the new report
    CellMeasurementReport* new_report = (CellMeasurementReport*)malloc(sizeof(CellMeasurementReport));
    new_report->cell_id = cell_id;
    new_report->rsrp = rsrp;
    new_report->rsrq = rsrq;

    // Add the new report to the collection
    if(collection->num_reports >= sizeof(collection->reports)/sizeof(collection->reports[0])) {
        // Reallocate memory for the reports array
        CellMeasurementReport** new_reports = (CellMeasurementReport**)realloc(collection->reports, (collection->num_reports+1)*sizeof(CellMeasurementReport));
        collection->reports = new_reports;
    }

    collection->reports[collection->num_reports++] = new_report;

    pthread_mutex_unlock(&collection->lock);
}

// Function to update a report in the collection
void update_report(ReportCollection* collection, int cell_id, float rsrp, float rsrq) {
    pthread_mutex_lock(&collection->lock);

    // Find and update the report with the given cell ID
    for(size_t i = 0; i < collection->num_reports; i++) {
        if(collection->reports[i]->cell_id == cell_id) {
            collection->reports[i]->rsrp = rsrp;
            collection->reports[i]->rsrq = rsrq;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Function to remove a report from the collection
void remove_report(ReportCollection* collection, int cell_id) {
    pthread_mutex_lock(&collection->lock);

    // Find and remove the report with the given cell ID
    for(size_t i = 0; i < collection->num_reports; i++) {
        if(collection->reports[i]->cell_id == cell_id) {
            // Shift all subsequent reports down to fill the gap
            for(size_t j = i+1; j < collection->num_reports; j++) {
                collection->reports[i] = &collection->reports[j];
            }

            // Free memory for removed report
            free(collection->reports[--collection->num_reports]);

            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

// Function to calculate the average signal quality for a specific cell
float get_average_signal_quality(ReportCollection* collection, int cell_id) {
    pthread_mutex_lock(&collection->lock);

    // Initialize sum and count for average calculation
    float sum_rsrp = 0;
    size_t count_reports = 0;

    // Find all reports with the given cell ID
    for(size_t i = 0; i < collection->num_reports; i++) {
        if(collection->reports[i]->cell_id == cell_id) {
            sum_rsrp += collection->reports[i]->rsrp;
            count_reports++;
        }
    }

    // Calculate average signal quality
    float avg_rsrp = (count_reports > 0) ? sum_rsrp / count_reports : 0;

    pthread_mutex_unlock(&collection->lock);

    return avg_rsrp;
}

