// Define the data structure for a NetworkEvent
typedef struct {
    time_t timestamp;
    int eventType;
    union {
        struct {
            char* username;
            int connectionType;
        } userConnectionInfo;
        struct {
            float latency;
            int packetLoss;
        } networkPerformanceMetric;
    } payload;
} NetworkEvent;

// Define the data structure for a doubly linked list node
typedef struct Node {
    NetworkEvent event;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the doubly linked list structure
typedef struct {
    Node* head;
    Node* tail;
    int size;
} DoublyLinkedList;

// Function to create a new doubly linked list node
Node* createNode(NetworkEvent event) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->event = event;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

// Function to insert an event at the head of the list
void insertAtHead(DoublyLinkedList* dll, NetworkEvent event) {
    Node* newNode = createNode(event);
    if (dll->head == NULL) {
        dll->head = newNode;
        dll->tail = newNode;
    } else {
        newNode->next = dll->head;
        dll->head->prev = newNode;
        dll->head = newNode;
    }
}

// Function to insert an event at the tail of the list
void insertAtTail(DoublyLinkedList* dll, NetworkEvent event) {
    Node* newNode = createNode(event);
    if (dll->tail == NULL) {
        dll->head = newNode;
        dll->tail = newNode;
    } else {
        newNode->prev = dll->tail;
        dll->tail->next = newNode;
        dll->tail = newNode;
    }
}

// Function to delete an event from the list
void deleteEvent(DoublyLinkedList* dll, Node* node) {
    if (node == NULL) return;

    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        dll->head = node->next;
    }

    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        dll->tail = node->prev;
    }

    free(node);
}

// Function to print the doubly linked list
void printDLL(DoublyLinkedList* dll) {
    Node* current = dll->head;
    while (current != NULL) {
        printf("%ld %d ", current->event.timestamp, current->event.eventType);
        if (current->event.payload.userConnectionInfo != NULL) {
            printf("username: %s connectionType: %d\n", current->event.payload.userConnectionInfo.username, current->event.payload.userConnectionInfo.connectionType);
        } else {
            printf("latency: %.2f packetLoss: %d\n", current->event.payload.networkPerformanceMetric.latency, current->event.payload.networkPerformanceMetric.packetLoss);
        }
        current = current->next;
    }
}

// Function to handle a sudden influx of events
void handleInflux(DoublyLinkedList* dll) {
    // Implement batch processing and real-time processing here
}

int main() {
    DoublyLinkedList dll;
    dll.head = NULL;
    dll.tail = NULL;
    dll.size = 0;

    NetworkEvent event1 = (NetworkEvent){ .timestamp = time(NULL), .eventType = 1, .payload = { .userConnectionInfo = { .username = "Alice", .connectionType = 1 } } };
    insertAtHead(&dll, event1);

    NetworkEvent event2 = (NetworkEvent){ .timestamp = time(NULL), .eventType = 2, .payload = { .networkPerformanceMetric = { .latency = 0.5f, .packetLoss = 10 } } };
    insertAtTail(&dll, event2);

