    }

    public DisjointPairCalculator(int concurrencyLevel, int batchSize) {
        this.concurrencyLevel = concurrencyLevel;
        this.batchSize = batchSize;
        unionFind = new UnionFind();
        executorService = Executors.newFixedThreadPool(concurrencyLevel);
    }

    public int calculateDisjointPairs(int[] array) {
        List<Runnable> tasks = new ArrayList<>();
        for (int i = 0; i < array.length; i += batchSize) {
            int start = i;
            int end = Math.min(i + batchSize, array.length);
            tasks.add(() -> processBatch(array, start, end));
        }
        executorService.invokeAll(tasks).forEach(runnable -> runnable.run());
        return unionFind.getDisjointPairCount();
    }

    private void processBatch(int[] array, int start, int end) {
        for (int i = start; i < end; i++) {
            for (int j = i + 1; j < end; j++) {
                if (!unionFind.isConnected(array[i], array[j])) {
                    unionFind.union(array[i], array[j]);
                }
            }
        }
    }

    public void shutdown() {
        executorService.shutdown();
    }
}

class UnionFind {
    private List<Integer> parent;

    public UnionFind() {
        this.parent = new ArrayList<>();
    }

    public int getDisjointPairCount() {
        int count = 0;
        for (int i = 1; i < parent.size(); i++) {
            if (parent.get(i) == i) {
                count++;
            }
        }
        return count / 2;
    }

    public void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA != rootB) {
            parent.set(rootA, rootB);
        }
    }

    private int find(int x) {
        if (parent.get(x) == x) {
            return x;
        } else {
            return find(parent.get(x));
        }
    }

    public boolean isConnected(int a, int b) {
        return find(a) == find(b);
    }
}
