typedef struct node {
    NFAPI_CRC_INDATION_PDU_T data;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int list_size = 0;
FILE* log_file = fopen(LOG_FILE, "a");

void init_list() {
    pthread_mutex_lock(&lock);
    head = NULL;
    list_size = 0;
    pthread_mutex_unlock(&lock);
}

Node* insert_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Error allocating memory for node");
        return NULL;
    }
    new_node->data = data;
    new_node->next = head;
    pthread_mutex_lock(&lock);
    head = new_node;
    list_size++;
    pthread_mutex_unlock(&lock);
    return new_node;
}

void remove_node(Node* node) {
    Node* temp = head;
    if (!temp || !node)
        return;
    if (head == node) {
        head = node->next;
    } else {
        while (temp && temp->next != node)
            temp = temp->next;
        if (temp)
            temp->next = node->next;
    }
    free(node);
}

void print_list() {
    Node* current = head;
    pthread_mutex_lock(&lock);
    printf("List size: %d\n", list_size);
    while (current) {
        printf("%d %d %d %d\n", current->data.RX_UE_INFORMATION_TAG, 
               current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG, 
               current->data.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void iterate_forward() {
    Node* current = head;
    pthread_mutex_lock(&lock);
    while (current) {
        // process data
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void iterate_reverse() {
    Node* current = head;
    Node* prev = NULL;
    pthread_mutex_lock(&lock);
    while (current) {
        prev = current;
        current = current->next;
    }
    // process data
    pthread_mutex_unlock(&lock);
}

int main() {
    init_list();
    pthread_t threads[MAX_LIST_SIZE];
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        // generate random data
        ...
        Node* node = insert_node(data);
        if (!node) {
            perror("Error inserting node");
            break;
        }
    }
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        pthread_create(&threads[i], NULL, iterate_forward, NULL);
    }
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        pthread_join(threads[i], NULL);
    }
    return 0;
}

