// Logging function to track query performance and error rates
void log_query(int id, int success, int latency) {
    pthread_mutex_lock(&log_lock);
    printf("Query %d: Success - %d, Latency - %d\n", id, success, latency);
    pthread_mutex_unlock(&log_lock);
}

// DNS lookup function to resolve a query
dns_record_t *lookup(char *name, char *type) {
    // Check cache first
    for (int i = 0; i < cache->size; i++) {
        if (!strcmp(cache->records[i].name, name) && !strcmp(cache->records[i].type, type)) {
            return &cache->records[i];
        }
    }

    // If not found in cache, perform DNS lookup
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(DNS_PORT);
    inet_pton(AF_INET, "8.8.8.8", &server_addr.sin_addr);

    char query[MAX_QUERY_SIZE];
    sprintf(query, "%s IN %s", name, type);

    sendto(sockfd, query, strlen(query), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));

    struct sockaddr_in from;
    socklen_t from_len = sizeof(from);
    int response = recvfrom(sockfd, query, MAX_QUERY_SIZE, 0, (struct sockaddr *)&from, &from_len);

    dns_record_t *record = malloc(sizeof(dns_record_t));
    record->id = -1;
    record->name = strdup(name);
    record->type = strdup(type);
    if (response > 0) {
        // Handle response data
    } else {
        free(record->name);
        free(record->type);
        free(record);
        return NULL;
    }

    close(sockfd);

    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache->size; i++) {
        if (!strcmp(cache->records[i].name, name) && !strcmp(cache->records[i].type, type)) {
            free(record->name);
            free(record->type);
            free(record);
            return &cache->records[i];
        }
    }

    // Add new record to cache
    pthread_mutex_unlock(&cache_lock);

    return record;
}

