        self.k8s_api = k8s_client.ApiClient()

    # Transcode video files using FFmpeg
    def transcode_video(self, video_file):
        docker_container = self.docker_client.containers.run('ffmpeg', detach=True)
        docker_container.put_archive(video_file)
        docker_container.exec_run(['ffmpeg', '-i', 'input.mp4', '-c:v', 'libx264', '-crf', '18', 'output.mp4'])

