#include <iostream>
#include <vector>
#include <thread>
#include <mutex>

// Define a struct for video statistics and metadata
struct VideoStats {
    int resolution;
    int bitrate;
    std::string codec;
};

// Define the processAndAggregateVideoStats function
void processAndAggregateVideoStats(std::vector<VideoStats> video_stats) {
    // Initialize aggregation variables
    int total_resolution = 0;
    int total_bitrate = 0;

    // Process and aggregate video statistics
    std::mutex mutex;
    for (const auto& stat : video_stats) {
        std::lock_guard<std::mutex> lock(mutex);
        total_resolution += stat.resolution;
        total_bitrate += stat.bitrate;
    }

    // Calculate average resolution and bitrate
    double avg_resolution = static_cast<double>(total_resolution) / video_stats.size();
    double avg_bitrate = static_cast<double>(total_bitrate) / video_stats.size();

    // Output aggregated statistics
    std::cout << "Average Resolution: " << avg_resolution << std::endl;
    std::cout << "Average Bitrate: " << avg_bitrate << std::endl;
}

// Example usage:
int main() {
    std::vector<VideoStats> video_stats = {
        {1080, 5000, "H.264"},
        {720, 3000, "VP9"},
        {480, 2000, "H.265"}
    };

    processAndAggregateVideoStats(video_stats);

    return 0;
}
