#define MAX_CONCURRENT_REQUESTS 100000
#define MAX_ACTIVE_THREADS 10000
#define CACHE_SIZE 1000

typedef struct CellMeasurementReport {
    int cell_id;
    float rsrp;
    float rsrq;
} CellMeasurementReport;

// Cache of measurement reports
CellMeasurementReport *cache[CACHE_SIZE];
int cache_size = 0;

// Lock for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_report(int cell_id, float rsrp, float rsrq) {
    pthread_mutex_lock(&lock);
    // Check if report already exists in cache
    int i;
    for (i = 0; i < cache_size; i++) {
        if (cache[i]->cell_id == cell_id) {
            // Update existing report
            cache[i]->rsrp = rsrp;
            cache[i]->rsrq = rsrq;
            break;
        }
    }
    if (i == cache_size) {
        // Add new report to cache
        cache[cache_size++] = malloc(sizeof(CellMeasurementReport));
        cache[cache_size-1]->cell_id = cell_id;
        cache[cache_size-1]->rsrp = rsrp;
        cache[cache_size-1]->rsrq = rsrq;
    }
    pthread_mutex_unlock(&lock);
}

float get_average_signal_quality(int cell_id) {
    pthread_mutex_lock(&lock);
    int i;
    float sum_rsrp = 0.0f, sum_rsrq = 0.0f, count = 0;
    for (i = 0; i < cache_size; i++) {
        if (cache[i]->cell_id == cell_id) {
            sum_rsrp += cache[i]->rsrp;
            sum_rsrq += cache[i]->rsrq;
            count++;
        }
    }
    pthread_mutex_unlock(&lock);
    return (count > 0) ? (sum_rsrp / count) : -1.0f, (sum_rsrq / count);
}

int remove_report(int cell_id) {
    pthread_mutex_lock(&lock);
    int i;
    for (i = 0; i < cache_size; i++) {
        if (cache[i]->cell_id == cell_id) {
            free(cache[i]);
            memmove(cache + i, cache + i + 1, (cache_size - i - 1) * sizeof(CellMeasurementReport));
            cache_size--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return i != cache_size; // Return 1 if report was found and removed
}

