// Configuration management system
class Config {
public:
    std::vector<FilterRule> filters;
    std::vector<AggregationFunction> aggregations;

    void addFilter(const FilterRule& filter) { filters.push_back(filter); }
    void addAggregation(const AggregationFunction& aggregation) { aggregations.push_back(aggregation); }
};

// Filtering rule
class FilterRule {
public:
    std::string field;
    std::string value;
    bool include;

    FilterRule(std::string field, std::string value, bool include)
        : field(field), value(value), include(include) {}
};

// Aggregation function
class AggregationFunction {
public:
    std::string type;
    double threshold;

    AggregationFunction(std::string type, double threshold)
        : type(type), threshold(threshold) {}
};

// Logging service interface
class LoggingService {
public:
    virtual void write(const std::string& logEntry) = 0;
    virtual ~LoggingService() {} // Pure virtual destructor
};

// In-memory logging service
class MemoryLogger : public LoggingService {
private:
    std::deque<std::string> logs;

public:
    void write(const std::string& logEntry) override {
        logs.push_back(logEntry);
    }
};

// External logging service interface (e.g., AWS S3, Google Cloud Storage)
class ExternalLoggingService : public LoggingService {
public:
    virtual void write(const std::string& logEntry) = 0;
    virtual ~ExternalLoggingService() {} // Pure virtual destructor
};

// Log processor
class LogProcessor {
private:
    Config config;
    std::vector<LoggingService*> loggingServices;
    std::mutex mtx;
    std::condition_variable cv;

public:
    LogProcessor(const Config& config, const std::vector<LoggingService*>& loggingServices)
        : config(config), loggingServices(loggingServices) {}

    void processLogEntry(const std::string& logEntry) {
        for (auto& service : loggingServices) {
            service->write(logEntry);
        }
    }

    // Filter and aggregate logs
    void filterAndAggregate() {
        for (const auto& logEntry : config.filters) {
            if (!logEntry.include) continue;
            processLogEntry(logEntry.value);
        }
        for (const auto& aggregation : config.aggregations) {
            processLogEntry(aggregation.type + "(" + std::to_string(aggregation.threshold) + ")");
        }
    }

    // Start processing logs
    void startProcessing() {
        while (true) {
            cv.wait(mtx);
            filterAndAggregate();
        }
    }
};

// Main program
int main() {
    Config config;
    std::vector<LoggingService*> loggingServices;

    // Add logging services
    MemoryLogger memoryLogger;
    ExternalLoggingService* externalLogger = new ExternalLoggingService(); // Initialize external logger
    loggingServices.push_back(&memoryLogger);
    loggingServices.push_back(externalLogger);

    LogProcessor logProcessor(config, loggingServices);
    std::thread processingThread(&LogProcessor::startProcessing, &logProcessor);

    // Handle packet loss and latency spikes
    while (true) {
        // Simulate packet loss and latency spikes
        if (rand() % 2 == 0) {
            std::this_thread::sleep_for(std::chrono::milliseconds(1000));
        }
        for (const auto& service : loggingServices) {
            if (!service->write("Log entry")) {
                // Handle packet loss or connectivity issue
                break;
            }
        }
    }

    return 0;
}

