        // Process the line
        if (count_chars) {
            chars_counted += strlen(line);
        }
        // Handle other options and processing as needed
    }

    fclose(in_file);

    if (!output_to_stdout && output_filename) {
        out_file = fopen(output_filename, "w");
        if (!out_file) {
            perror("Error opening output file");
            exit(EXIT_FAILURE);
        }
        fprintf(out_file, "%d\n", chars_counted);
        fclose(out_file);
    } else {
        printf("%d\n", chars_counted);
    }

    return EXIT_SUCCESS;
}
