#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <mysql/mysql.h>

// Structure to represent NAS PDU
typedef struct {
    uint32_t rnti;
    int rx_ue_info_tag;
    int crc_indication;
} nas_pdu_t;

// Function to generate a new NAS PDU with unique RNTI and random CRC indication
nas_pdu_t* gen_nas_pdu() {
    nas_pdu_t* pdu = (nas_pdu_t*)malloc(sizeof(nas_pdu_t));
    srand(time(NULL)); // Initialize random seed
    pdu->rnti = rand() % 4294967296; // Generate unique RNTI value
    pdu->rx_ue_info_tag = rand() % 2; // Randomly set RX UE information tag
    pdu->crc_indication = (rand() % 2) ? 1 : 0; // Randomly set CRC indication flag
    return pdu;
}

// Function to store NAS PDUs in the database
int store_nas_pdu_batch(nas_pdu_t** pdus, int num_pdus) {
    // Establish MySQL connection
    MYSQL *conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", "username", "password", "database_name", 3306, NULL, 0)) {
        printf("Error connecting to database: %s\n", mysql_error(conn));
        return -1;
    }

    // Insert each PDU into the database
    for (int i = 0; i < num_pdus; i++) {
        nas_pdu_t* pdu = pdus[i];
        char query[256];
        sprintf(query, "INSERT INTO nas_pdus (rnti, rx_ue_info_tag, crc_indication) VALUES (%u, %d, %d)", pdu->rnti, pdu->rx_ue_info_tag, pdu->crc_indication);
        if (!mysql_query(conn, query)) {
            printf("Inserted PDU: RNTI=%u, RX UE info tag=%d, CRC indication flag=%d\n", pdu->rnti, pdu->rx_ue_info_tag, pdu->crc_indication);
        } else {
            printf("Error inserting PDU: %s\n", mysql_error(conn));
            return -1;
        }
    }

    // Close MySQL connection
    mysql_close(conn);
    return 0;
}

// Function to load NAS PDUs from the database
nas_pdu_t** load_nas_pdu_batch(int* num_pdus) {
    // Establish MySQL connection
    MYSQL *conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", "username", "password", "database_name", 3306, NULL, 0)) {
        printf("Error connecting to database: %s\n", mysql_error(conn));
        return NULL;
    }

    // Query the database for existing PDUs
    char query[256];
    sprintf(query, "SELECT rnti, rx_ue_info_tag, crc_indication FROM nas_pdus");
    if (!mysql_query(conn, query)) {
        MYSQL_RES *result = mysql_use_result(conn);
        int num_rows = mysql_num_rows(result);

        // Allocate memory for the PDUs
        nas_pdu_t** pdus = (nas_pdu_t**)malloc((num_rows + 1) * sizeof(nas_pdu_t*));
        for (int i = 0; i < num_rows; i++) {
            MYSQL_ROW row = mysql_fetch_row(result);
            nas_pdu_t* pdu = (nas_pdu_t*)malloc(sizeof(nas_pdu_t));
            pdu->rnti = atoi(row[0]);
            pdu->rx_ue_info_tag = atoi(row[1]);
            pdu->crc_indication = atoi(row[2]);
            pdus[i] = pdu;
        }
        mysql_free_result(result);
    } else {
        printf("Error querying database: %s\n", mysql_error(conn));
        return NULL;
    }

    // Close MySQL connection
    mysql_close(conn);

    *num_pdus = num_rows;
    return pdus;
}

// Function to free allocated memory for NAS PDUs
void free_nas_pdu_batch(nas_pdu_t** pdus, int num_pdus) {
    for (int i = 0; i < num_pdus; i++) {
        free(pdus[i]);
    }
    free(pdus);
}
