    void addDataPacket(DataPacket packet) {
        unique_lock<mutex> lock(mutex_);
        dataPackets_->push_back(packet);
        lock.unlock();
    }

    void removeDataPacket(size_t index) {
        lock_guard<mutex> lock(mutex_);
        if (index < dataPackets_->size()) {
            dataPackets_->erase(dataPackets_->begin() + index);
