public:
    int attemptCount = 0;
    double backoffTime = 1.0;

    void retryOperation(std::function<void()> operation, const char* message) {
        try {
            operation();
        } catch (const std::exception& e) {
            if (attemptCount < 3) {
                // Implement exponential backoff
                std::this_thread::sleep_for(std::chrono::seconds(static_cast<unsigned int>(backoffTime * pow(2.0, attemptCount))));
