<?php

namespace MyApp\Auth;

use Illuminate\Support\Facades\Cookie;
use Illuminate\Support\Facades\AuthManager;
use Laravel\Passport\TokenRepository;
use League\OAuth2\Client\Token\AccessToken;
use Firebase\JWT\FJwtException;

class AuthLibrary {
    private $authManager;
    private $tokenRepository;
    private $cache;
    private $rateLimiter;

    public function __construct(AuthManager $authManager, TokenRepository $tokenRepository) {
        $this->authManager = $authManager;
        $this->tokenRepository = $tokenRepository;
        $this->cache = new \League\Redis\Client();
        $this->rateLimiter = new \Laravel\RateLimiting\RateLimiter();
    }

    public function authenticate(AccessToken $accessToken) {
        try {
            // Validate and parse the access token
            $decodedToken = (new \Firebase\JWT\JWT())->decode($accessToken);
            $user = $this->authManager->authenticate($decodedToken);

            // Create a new session for the user
            $session = new \MyApp\Session();
            $session->start();

            // Set the session cookie
            Cookie::set('session_id', $session->getId());

            return $user;
        } catch (FJwtException $e) {
            // Handle JWT exceptions
            return null;
        }
    }

    public function getAuthenticatedUser() {
        // Get the authenticated user from the session
        $user = \MyApp\Session::get('user');

        if (!$user) {
            // User not found, log out and redirect to login page
            return redirect()->route('login');
        }

        return $user;
    }

    public function logout() {
        // End the user's session
        $session = new \MyApp\Session();
        $session->destroy();

        // Remove the session cookie
        Cookie::forget('session_id');

        // Log out and redirect to login page
        return redirect()->route('login');
    }

    public function getRateLimited($limit) {
        // Get the rate limiter for the current tenant
        $limiter = $this->rateLimiter->forTenant(\MyApp\Tenant::getCurrent());

        if (!$limiter->isAllowed($limit)) {
            // Rate limit exceeded, log and return error
            return response()->json(['error' => 'Rate limit exceeded'], 429);
        }

        return null;
    }
}
