    public class DataProcessor
    {
        // Flexible data generation
        private Random _random;
        private Dictionary<string, Random> _distributions = new Dictionary<string, Random>();

        public void Initialize(string[] environmentVariables)
        {
            foreach (var variable in environmentVariables)
            {
                var parts = variable.Split('=');
                if (parts.Length == 2 && _distributions.ContainsKey(parts[0]))
                {
                    _random = _distributions[parts[0]];
                    _random.Seed(int.Parse(parts[1]));
                }
            }
        }

        public double GenerateRandomNumber(string distribution, int seed)
        {
            // Implementation of different distributions (uniform, normal, exponential, etc.)
            switch (distribution.ToLower())
            {
                case "uniform":
                    return _random.NextDouble();
                case "normal":
                    return _random.NextGaussian();
                case "exponential":
                    return -Math.Log(_random.NextDouble());
                default:
                    throw new ArgumentException("Invalid distribution");
            }
        }

        // Secure hashing
        public string ComputeMD5Hash(string input)
        {
            using (var md5 = System.Security.Cryptography.MD5.Create())
            {
                var hashBytes = md5.ComputeHash(System.Text.Encoding.UTF8.GetBytes(input));
                return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
