namespace DynamicRandomValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly RandomNumberGenerator _rng;

        public RandomValueGenerator()
        {
            _rng = RandomNumberGenerator.Create();
        }

        public async Task<float> GenerateFloatAsync()
        {
            byte[] randomBytes = new byte[4];
            _rng.GetBytes(randomBytes);
            return BitConverter.ToSingle(BitConverter.GetBytes(randomBytes[0]), 0);
        }

        public async Task<int> GenerateIntAsync(int min, int max)
        {
            var randomBytes = new byte[4];
            _rng.GetBytes(randomBytes);
            int value = (int)(BitConverter.ToInt32(randomBytes, 0) % (max - min + 1)) + min;
            return value;
        }

        public async Task<(float x, float y, float z)> Generate3DVectorAsync()
        {
            var randomBytesX = new byte[4];
            _rng.GetBytes(randomBytesX);
            var randomBytesY = new byte[4];
            _rng.GetBytes(randomBytesY);
            var randomBytesZ = new byte[4];
            _rng.GetBytes(randomBytesZ);

            return (
