from flask import Flask, request, jsonify
import sqlite3
import logging
import os
import time
from flask_cors import CORS, cross_origin

app = Flask(__name__)
CORS(app)

# Connect to database
conn = sqlite3.connect('cms.db')
c = conn.cursor()

# Create table if not exists
c.execute('''CREATE TABLE IF NOT EXISTS articles 
             (title text, content text)''')

# Start the application
if __name__ == '__main__':
    app.run(debug=True)

@app.route('/api/articles', methods=['GET'])
@cross_origin()
def get_articles():
    try:
        c.execute('SELECT * FROM articles')
        rows = c.fetchall()
        return jsonify([dict(title=row[0], content=row[1]) for row in rows])
    except sqlite3.Error as e:
        logging.error(f"Error: {e}")
        return 'Error', 500, {'Content-Type': 'text/plain'}

@app.route('/api/articles', methods=['POST'])
@cross_origin()
def create_article():
    try:
        data = request.get_json()
        c.execute("INSERT INTO articles VALUES (?, ?)", 
                  (data['title'], data['content']))
        conn.commit()
        return 'Article created successfully', 201, {'Content-Type': 'text/plain'}
    except sqlite3.Error as e:
        logging.error(f"Error: {e}")
        return 'Error', 500, {'Content-Type': 'text/plain'}

@app.route('/api/articles/<id>', methods=['GET'])
@cross_origin()
def get_article(id):
    try:
        c.execute('SELECT * FROM articles WHERE title=?', (id,))
        row = c.fetchone()
        if row is not None:
            return jsonify(dict(title=row[0], content=row[1]))
        else:
            return 'Article not found', 404, {'Content-Type': 'text/plain'}
    except sqlite3.Error as e:
        logging.error(f"Error: {e}")
        return 'Error', 500, {'Content-Type': 'text/plain'}

@app.route('/api/articles/<id>', methods=['PUT'])
@cross_origin()
def update_article(id):
    try:
        data = request.get_json()
        c.execute("UPDATE articles SET content=? WHERE title=?", 
                  (data['content'], id))
        conn.commit()
        return 'Article updated successfully', 200, {'Content-Type': 'text/plain'}
    except sqlite3.Error as e:
        logging.error(f"Error: {e}")
        return 'Error', 500, {'Content-Type': 'text/plain'}

@app.route('/api/articles/<id>', methods=['DELETE'])
@cross_origin()
def delete_article(id):
    try:
        c.execute("DELETE FROM articles WHERE title=?", (id,))
        conn.commit()
        return 'Article deleted successfully', 200, {'Content-Type': 'text/plain'}
    except sqlite3.Error as e:
        logging.error(f"Error: {e}")
        return 'Error', 500, {'Content-Type': 'text/plain'}

if __name__ == '__main__':
    app.run(debug=True)
