class Configuration {
public:
    std::string key;
    std::string value;
};

class ConfigurationManager {
private:
    std::map<std::string, Configuration> configurations;
    std::mutex lock;

public:
    void addConfiguration(const std::string& key, const std::string& value) {
        lock.lock();
        configurations[key] = {key, value};
        lock.unlock();
    }

    std::vector<Configuration> getconfigurations() {
        std::vector<Configuration> result;
        lock.lock();
        for (const auto& pair : configurations) {
            result.push_back(pair.second);
        }
        lock.unlock();
        return result;
    }

    void updateConfiguration(const std::string& key, const std::string& value) {
        lock.lock();
        if (configurations.find(key) != configurations.end()) {
            configurations[key].value = value;
        }
        lock.unlock();
    }

    bool exists(const std::string& key) {
        lock.lock();
        return configurations.find(key) != configurations.end();
        lock.unlock();
    }
};

int main() {
    ConfigurationManager configManager;

    // Add configurations
    configManager.addConfiguration("key1", "value1");
    configManager.addConfiguration("key2", "value2");

    // Get all configurations
    std::vector<Configuration> configs = configManager.getconfigurations();

    for (const auto& config : configs) {
        std::cout << "Key: " << config.key << ", Value: " << config.value << std::endl;
    }

    // Update configuration
    configManager.updateConfiguration("key1", "newValue");

    return 0;
}
