    std::string name;
    double price;
    int quantity;
    std::string category;
};

class Cache {
public:
    using Callback = std::function<void(const Product&)>;
    void set(const Product& product, const Callback& callback) {
        // implement cache eviction policy
        if (cache_.size() >= capacity_) {
            auto it = cache_.begin();
            ++it; // skip the first element
            for (; it != cache_.end(); ++it) {
                cache_.erase(it);
            }
        }
        cache_.emplace(product.id, product);
        callback(product);
    }

    Product get(const std::string& id, const Callback& callback) {
        auto it = cache_.find(id);
        if (it == cache_.end()) {
            return {};
        }
        return it->second;
    }

private:
    int capacity_ = 1000; // adjust the capacity according to your needs
    std::unordered_map<std::string, Product> cache_;
};

