["Here is the Node.js code for the dynamic content delivery network (CDN) that efficiently distributes both static and dynamic content across a geographically dispersed infrastructure:

```javascript
// Import required modules
const express = require('express');
const app = express();
const http = require('http').createServer(app);
const io = require('socket.io')(http);
const redis = require('redis');
const { MachineLearningModel } = require('./ml-model');
const { CloudLoadBalancer } = require('./cloud-load-balancer');
const { SecurityModule } = require('./security-module');
const { MonitoringSystem } = require('./monitoring-system');

// Initialize cache, load balancer, security module, and monitoring system
const redisClient = redis.createClient({ host: 'localhost', port: 6379 });
const mlModel = new MachineLearningModel();
const cloudLoadBalancer = new CloudLoadBalancer();
const securityModule = new SecurityModule();
const monitoringSystem = new MonitoringSystem();

// Define adaptive caching strategy based on cache hit rates and freshness
app.use((req, res, next) => {
    const cacheKey = req.url;
    redisClient.get(cacheKey, (err, cachedResponse) => {
        if (!err && cachedResponse !== null) {
            // Cache hit! Return cached response.
            res.send(cachedResponse);
        } else {
            // No cache hit. Store response in Redis and return original response.
            const response = res.send();
            redisClient.setex(cacheKey, 3600, response);
        }
    });
});

// Implement auto-scaling based on traffic patterns
cloudLoadBalancer.scale((req) => {
    // Use machine learning model to predict demand and optimize cache configurations
    mlModel.predict(req.ip, (demandPrediction) => {
        if (demandPrediction > 1000) {
            cloudLoadBalancer.scaleUp();
        } else if (demandPrediction < 500) {
            cloudLoadBalancer.scaleDown();
        }
    });
});

// Secure content with HTTPS, DDoS protection, and rate limiting
app.use((req, res, next) => {
    securityModule.secure(req, res, next);
});

// Set up comprehensive monitoring and logging
monitoringSystem.start();

// Listen for incoming requests
http.listen(3000, () => {
    console.log('CDN is listening on port 3000');
});
```

