// Define structure to hold PDU data
typedef struct {
    int srn; // Signaling Radio Bearer identifier
    char* data; // Actual PDU data
} lte_pdcps_t;

// Define structure to manage PDCP PDUs for a given SRB
typedef struct {
    int srn;
    size_t count;
    lte_pdcps_t** pdus;
} pdcps_manager_t;

// Initialize the manager
pdcps_manager_t* pdcps_manager_init(int srn) {
    pdcps_manager_t* manager = (pdcps_manager_t*)malloc(sizeof(pdcps_manager_t));
    manager->srn = srn;
    manager->count = 0;
    manager->pdus = NULL;
    return manager;
}

// Add a PDU to the manager
int pdcps_manager_add_pdu(pdcps_manager_t* manager, char* data) {
    // Allocate new memory for the PDU structure
    lte_pdcps_t* pdu = (lte_pdcps_t*)malloc(sizeof(lte_pdcps_t));
    pdu->srn = manager->srn;
    pdu->data = strdup(data);

    // Add the PDU to the array and increment count
    size_t i = manager->count++;
    if (!manager->pdus) {
        manager->pdus = (lte_pdcps_t**)malloc(sizeof(lte_pdcps_t*) * 2);
        manager->pdus[0] = pdu;
    } else {
        lte_pdcps_t** pdus = (lte_pdcps_t**)realloc(manager->pdus, sizeof(lte_pdcps_t*) * (manager->count + 1));
        pdus[i] = pdu;
    }
    return 0;
}

// Remove a PDU from the manager
int pdcps_manager_remove_pdu(pdcps_manager_t* manager, int index) {
    if (index >= manager->count || !manager->pdus[index]) {
        // Return error code for invalid index
        return -1;
    }

    // Free the PDU data and remove from array
    free(manager->pdus[index]->data);
    free(manager->pdus[index]);
    memmove(&manager->pdus[index], &manager->pdus[index + 1], (manager->count - index - 1) * sizeof(lte_pdcps_t*));
    manager->count--;

    return 0;
}

// Retrieve a PDU from the manager
int pdcps_manager_get_pdu(pdcps_manager_t* manager, int index, char** data) {
    if (index >= manager->count || !manager->pdus[index]) {
        // Return error code for invalid index
        return -1;
    }

    *data = manager->pdus[index]->data;

    return 0;
}

// Clean up the manager
void pdcps_manager_free(pdcps_manager_t* manager) {
    if (!manager)
        return;

    size_t i;
    for (i = 0; i < manager->count; i++) {
        free(manager->pdus[i]->data);
        free(manager->pdus[i]);
    }
    free(manager->pdus);
    free(manager);
}

int main() {
    // Initialize the PDCP PDUs for SRB 1
    pdcps_manager_t* manager = pdcps_manager_init(1);

    // Add some PDUs to the manager
    pdcps_manager_add_pdu(manager, "Hello");
    pdcps_manager_add_pdu(manager, "World");

    // Retrieve a PDU from the manager
    char* data;
    int index = 0;
    pdcps_manager_get_pdu(manager, index, &data);
    printf("PDU: %s\n", data);

    // Remove a PDU from the manager
    pdcps_manager_remove_pdu(manager, 1);

    // Clean up the manager
    pdcps_manager_free(manager);

    return 0;
}
