// Define a structure for LTE PDCP PDU objects
typedef struct {
    int srbi; // SRB identifier
    char *data; // PDU data
} lte_pdcppdu;

// Define a structure to manage a dynamic collection of PDUs
typedef struct {
    int size;
    lte_pdcppdu **pdus;
} lte_pdcp_collection;

// Function to add a new PDU to the collection for a given SRB identifier
int lte_pdcp_add_pdu(lte_pdcp_collection *collection, int srbi, char *data) {
    // Allocate memory for the new PDU
    lte_pdcppdu *new_pdu = (lte_pdcppdu *)malloc(sizeof(lte_pdcppdu));
    new_pdu->srbi = srbi;
    new_pdu->data = (char *)malloc(strlen(data) + 1);
    strcpy(new_pdu->data, data);

    // Add the new PDU to the collection
    if (collection->size == 0) {
        collection->pdus = (lte_pdcppdu **)malloc(sizeof(lte_pdcppdu *));
        collection->pdus[0] = new_pdu;
        collection->size = 1;
    } else {
        lte_pdcppdu **new_pdus = (lte_pdcppdu **)realloc(collection->pdus, (collection->size + 1) * sizeof(lte_pdcppdu *));
        collection->pdus = new_pdus;
        collection->pdus[collection->size] = new_pdu;
        collection->size++;
    }

    return 0;
}

// Function to remove a PDU from the collection for a given SRB identifier
int lte_pdcp_remove_pdu(lte_pdcp_collection *collection, int srbi) {
    // Find the index of the PDU with the matching SRB identifier
    int i;
    for (i = 0; i < collection->size; i++) {
        if (collection->pdus[i]->srbi == srbi) {
            break;
        }
    }

    // Remove the PDU from the collection
    if (i < collection->size) {
        free(collection->pdus[i]->data);
        free(collection->pdus[i]);
        for (int j = i; j < collection->size - 1; j++) {
            collection->pdus[j] = collection->pdus[j + 1];
        }
        collection->size--;
    }

    return 0;
}

