#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Define a struct for the LTE PDCP PDU objects
typedef struct {
    int srbid; // SRB identifier
    void* data; // PDU data pointer
} PdcPdu;

// Define a struct for the dynamic collection of PDCP PDUs
typedef struct {
    int size; // Number of PDU objects in the collection
    PdcPdu* pdus; // Array of PDU objects
} PdcPduCollection;

// Function to create a new PDCP PDU object
PdcPdu* pdcPduCreate(int srbid) {
    PdcPdu* pdu = (PdcPdu*)malloc(sizeof(PdcPdu));
    pdu->srbid = srbid;
    pdu->data = NULL;
    return pdu;
}

// Function to add a new PDCP PDU object to the collection
void pdcPduCollectionAdd(PdcPduCollection* collection, PdcPdu* pdu) {
    // Reallocate memory if necessary
    if (collection->size >= collection->pdus->size) {
        collection->pdus = realloc(collection->pdus, sizeof(PdcPdu*) * (collection->size + 1));
        collection->size++;
    }
    // Add the new PDU object to the collection
    collection->pdus[collection->size++] = pdu;
}

// Function to remove a PDCP PDU object from the collection by SRB identifier
void pdcPduCollectionRemoveBySrbid(PdcPduCollection* collection, int srbid) {
    // Find the index of the PDU object with the specified SRB identifier
    for (int i = 0; i < collection->size; i++) {
        if (collection->pdus[i]->srbid == srbid) {
            // Remove the PDU object from the collection and free its memory
            free(collection->pdus[i]->data);
            free(collection->pdus[i]);
            for (int j = i; j < collection->size - 1; j++) {
                collection->pdus[j] = collection->pdus[j + 1];
            }
            collection->size--;
            return;
        }
    }
}

// Function to retrieve a PDCP PDU object from the collection by SRB identifier
PdcPdu* pdcPduCollectionGetBySrbid(PdcPduCollection* collection, int srbid) {
    // Find the index of the PDU object with the specified SRB identifier
    for (int i = 0; i < collection->size; i++) {
        if (collection->pdus[i]->srbid == srbid) {
            return collection->pdus[i];
        }
    }
    return NULL;
}

// Function to free the memory allocated by the PDCP PDU object management library
void pdcPduCollectionFree(PdcPduCollection* collection) {
    for (int i = 0; i < collection->size; i++) {
        free(collection->pdus[i]->data);
        free(collection->pdus[i]);
    }
    free(collection->pdus);
}
