['```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class Cache {
public:
    using Key = std::string;
    using Value = std::any;

    struct Entry {
        Key key;
        Value value;
    };

    explicit Cache(size_t capacity) : _capacity(capacity), _map(), _mutex(), _cond() {}

    template<typename T>
    void put(const Key& key, const T& value) {
        auto lock = std::unique_lock(_mutex);
        while (_map.size() >= _capacity) {
            _cond.wait_for(lock, std::chrono::milliseconds(10));
        }
        _map[key] = value;
    }

    template<typename T>
    Value get(const Key& key) {
        Value result;
        auto lock = std::unique_lock(_mutex);
        if (_map.find(key) != _map.end()) {
            result = _map[key];
        }
        return result;
    }

private:
    size_t _capacity;
    std::unordered_map<Key, Value> _map;
    mutable std::mutex _mutex;
