```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <memory>

class Cache {
public:
    using Callback = std::function<void()>;

    explicit Cache(size_t capacity) : capacity_(capacity), size_(0) {}

    template<typename T>
    void put(const std::string& key, const T& value, Callback callback = nullptr) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (size_ >= capacity_) {
            // Evict an item based on your policy
            evict();
        }
        cache_[key] = value;
        size_++;
        if (callback) callback();
    }

    template<typename T>
    bool get(const std::string& key, T& result) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = cache_.find(key);
        if (it == cache_.end()) return false;
        result = it->second;
        return true;
    }

    size_t getSize() const {
        return size_;
    }

    void evict() {
        // Your eviction policy implementation
    }

private:
    std::unordered_map<std::string, T> cache_;
    size_t capacity_, size_;
    std::mutex mutex_;
};

int main() {
    Cache cache(100);  // Initialize a cache with a capacity of 100

    // Usage example
    auto value = std::make_shared<int>(42);
    cache.put("my_key", *value, [value]() { std::cout << "Value updated: " << *value << std::endl; });
    if (cache.get("my_key", *value)) {
        std::cout << "Retrieved value: " << *value << std::endl;
    }

    return 0;
}

```']

