import java.util.concurrent.ConcurrentHashMap;

public class DynamicArrayProcessor {

    private Map<String, ConcurrentMap<Integer, Integer>> disjointPairCounts = new ConcurrentHashMap<>();
    private Map<String, Boolean> rateLimitStatus = new HashMap<>();

    public void processArray(String tenantId, int[] array) {
        // Process the array and update the disjoint pair counts
        for (int num : array) {
            if (!rateLimitStatus.computeIfAbsent(tenantId, k -> true)) {
                System.out.println("Rate limit exceeded for tenant " + tenantId);
                return;
            }
            // Update the disjoint pair counts
            ConcurrentMap<Integer, Integer> map = disjointPairCounts.getOrDefault(tenantId, new ConcurrentHashMap<>());
            map.put(num, map.computeIfAbsent(num, k -> 0) + 1);
        }
    }

    public int getDisjointPairCount(String tenantId, int num) {
        return disjointPairCounts.getOrDefault(tenantId, new ConcurrentHashMap<>()).getOrDefault(num, 0);
    }

