// Define a struct to represent market data
struct MarketData {
    std::string symbol;
    double price;
    int volume;
};

class MarketDataCache {
public:
    void put(const MarketData& data) {
        // Cache implementation
        std::lock_guard<std::mutex> lock(mutex_);
        cache_.push_back(data);
    }

    bool get(const std::string& symbol, MarketData& result) {
        // Cache implementation
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& data : cache_) {
            if (data.symbol == symbol) {
                result = data;
                return true;
            }
        }
        return false;
    }

private:
    std::vector<MarketData> cache_;
    std::mutex mutex_;
};

class MarketDataProcessor {
public:
    void process(MarketData& data) {
        // Processing implementation
        if (data.price > 100.0) {
            // Handle special case
            std::cout << "Special case: " << data.symbol << " - Price: " << data.price << std::endl;
        } else {
            // Regular processing
            std::cout << data.symbol << " - Price: " << data.price << std::endl;
        }
    }
};

class MarketDataFetcher {
public:
    void fetch(MarketData& data) {
        // API implementation (e.g., Bloomberg, Reuters)
        if (data.symbol == "AAPL") {
            data.price = 150.0;
            data.volume = 100000;
        } else {
            data.price = 200.0;
            data.volume = 50000;
        }
    }
};

MarketDataCache cache;
MarketDataProcessor processor;

void fetchAndProcessMarketData(const std::string& symbol) {
    MarketData data;
    if (!cache.get(symbol, data)) {
        // Fetch and process market data
        MarketDataFetcher fetcher;
        fetcher.fetch(data);
        cache.put(data);

        // Process market data asynchronously
        auto processThread = std::thread([symbol, &processor]() {
            processor.process(data);
        });
        processThread.detach();
    }
}

int main() {
    fetchAndProcessMarketData("AAPL");
    return 0;
}
