// Structure definition
typedef struct {
    uint16_t rnti;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate unique RNTI identifiers
NFAPI_CRC_INDICATION_PDU_T* generateRNTIs(int numRNTIs, int maxRNTIs) {
    // Initialize the list of RNTIs and a counter for available RNTIs
    NFAPI_CRC_INDICATION_PDU_T* rntiList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numRNTIs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int availableRNTIs = maxRNTIs;

    // Initialize a random number generator
    srand(time(NULL));

    for (int i = 0; i < numRNTIs; i++) {
        while (1) {
            // Generate a random RNTI within the pool of valid values
            int rnti = rand() % maxRNTIs;
            // Check if the generated RNTI is unique and available
            if (availableRNTIs & (1 << rnti)) {
                rntiList[i].rnti = (uint16_t)rnti;
                availableRNTIs ^= 1 << rnti;
                break;
            }
        }
    }

    return rntiList;
}

int main() {
    // Example usage
    int numRNTIs = 10; // Number of unique RNTI identifiers to generate
    int maxRNTIs = 1000; // Maximum pool of valid RNTI values

    NFAPI_CRC_INDICATION_PDU_T* rntiList = generateRNTIs(numRNTIs, maxRNTIs);

    for (int i = 0; i < numRNTIs; i++) {
        printf("RNTI %d: %d\n", i, rntiList[i].rnti);
    }

    // Release resources
    free(rntiList);

    return 0;
}
