nfapi_crc_indication_pdu_collection_t* nfaпи_crc_indication_pdu_collection_create(int initial_capacity) {
    // Initialize the dynamic collection
    nfapi_crc_indication_pdu_collection_t* collection = (nfapi_crc_indication_pdu_collection_t*)malloc(sizeof(nfapi_crc_indication_pdu_collection_t));
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->data = (NFAPI_CRC_INDICATION_PDU_T**)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void nfapi_crc_indication_pdu_collection_destroy(nfapi_crc_indication_pdu_collection_t** collection) {
    // Release the dynamic collection
    if (*collection != NULL) {
        free((*collection)->data);
        free(*collection);
        *collection = NULL;
    }
}

int nfapi_crc_indication_pdu_collection_add(nfapi_crc_indication_pdu_collection_t* collection, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Add the PDU to the dynamic collection
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        // Resize the collection when it reaches capacity
        int new_capacity = 2 * collection->capacity;
        NFAPI_CRC_INDICATION_PDU_T** new_data = (NFAPI_CRC_INDICATION_PDU_T**)realloc(collection->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (new_data != NULL) {
            collection->data = new_data;
            collection->capacity = new_capacity;
        }
    }

    if (collection->size < collection->capacity) {
        // Add the PDU to the dynamic collection
        collection->data[collection->size] = pdu;
        collection->size++;

        pthread_mutex_unlock(&collection->lock);
        return 0;
    } else {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Collection full, add failed
    }
}

