        // Get packet from hashmap based on source or destination
        if (packetMap.find(p.source) != packetMap.end()) {
            for (auto& q : packetMap[p.source]) {
                if (q.destination == p.destination)
                    return q;
            }
        } else if (packetMap.find(p.destination) != packetMap.end()) {
