class CustomObject {
public:
    int id;
    std::string name;

    CustomObject(int id, const std::string& name) : id(id), name(name) {}
};

class DynamicObjectManager {
private:
    struct ObjectNode {
        CustomObject* obj;
        ObjectNode* prev;
        ObjectNode* next;
    };

    class ObjectList {
    public:
        ObjectNode* head;
        ObjectNode* tail;

        void add(ObjectNode* node) {
            if (head == nullptr) {
                head = node;
                tail = node;
            } else {
                node->next = head;
                head->prev = node;
                head = node;
            }
        }

        bool remove(ObjectNode* node) {
            if (node->prev != nullptr) {
                node->prev->next = node->next;
                if (node == tail) {
                    tail = node->prev;
                }
            } else {
                head = node->next;
            }
            return true;
        }

        void print() const {
            ObjectNode* temp = head;
            while (temp != nullptr) {
                std::cout << "ID: " << temp->obj->id << ", Name: " << temp->obj->name << std::endl;
                temp = temp->next;
            }
        }
    };

public:
    DynamicObjectManager() : objects(), lock(mutex), cond(lock, true) {}

    void addObject(CustomObject* obj) {
        std::unique_lock<std::mutex> lk(mutex);
        while (true) {
            if (!objects.head || !contains(objects, obj)) {
                objects.add(new ObjectNode());
                break;
            }
            lk.unlock();
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
            lk.lock();
        }
        lk.unlock();
    }

    void updateObject(int id, const std::string& name) {
        std::unique_lock<std::mutex> lk(mutex);
        ObjectNode* temp = objects.head;
        while (temp != nullptr) {
            if (temp->obj->id == id) {
                temp->obj->name = name;
                break;
            }
            temp = temp->next;
        }
    }

    CustomObject* getObject(int id) {
        std::unique_lock<std::mutex> lk(mutex);
        ObjectNode* temp = objects.head;
        while (temp != nullptr) {
            if (temp->obj->id == id) {
                return temp->obj;
            }
            temp = temp->next;
        }
        return nullptr;
    }

    void retrieveObjectsByName(const std::string& name) {
        ObjectNode* temp = objects.head;
        while (temp != nullptr) {
            if (temp->obj->name.find(name) != std::string::npos) {
                // handle retrieved object
            }
            temp = temp->next;
