        while (temp != nullptr) {
            if (temp->obj->id == id) {
                // handle retrieved object
            }
            temp = temp->next;
        }
    }

private:
    std::map<int, CustomObject*> objects;

    class Lock {
    public:
        void lock() {
            cv.wait(lock);
        }

        void unlock() {
            cv.notify_all();
        }
    };

