        std::uint16_t crcflag;
    };

    struct RNTI {
        std::uint32_t value;
    };

    struct CRC_INDICATION_REL8_TAG {
        bool is_valid;
    };

    struct NFAPI_CRC_INDICATION_PDU_T {
        RX_UE_INFORMATION_TAG rx_ue_info;
        RNTI rnti;
        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    };
}

namespace DynamicRandomValueProvider {

    class RandomNumberGenerator {
    public:
        explicit RandomNumberGenerator(size_t seed = 0) : rng_(seed) {}

        template<typename T>
        T generateRandom(T min, T max) {
            std::uniform_int_distribution<T> dist(min, max);
            return dist(rng_);
        }

        double generateGaussian(double mean, double standardDeviation) {
            std::normal_distribution<double> dist(mean, standardDeviation);
            return dist(rng_);
        }

    private:
        std::mt19937 rng_;
    };

    class DynamicRandomValueProvider {
    public:
        explicit DynamicRandomValueProvider(size_t seed = 0) : rng_(seed), random_number_generator_(seed) {}

        void setSeed(size_t newSeed) {
            rng_ = std::random_device{}(); // Re-seed the random device
            random_number_generator_.setSeed(newSeed);
        }

        NFAPI_CRC_INDICATION_PDU_T generateRandomNFAPI_CRC_INDICATION_PDU_T() {
            NFAPI_CRC_INDICATION_PDU_T result;
            result.rx_ue_info.crcflag = static_cast<std::uint16_t>(random_number_generator_.generateRandom(0, 65535));
            result.rnti.value = static_cast<std::uint32_t>(random_number_generator_.generateRandom(0, 4294967295));
            result.crc_indication_rel8_tag.is_valid = random_number_generator_.generateRandom(0, 1) == 1;
            return result;
        }

    private:
        std::random_device rng_;
        RandomNumberGenerator random_number_generator_;
    };

}
