    public class ConfigService : IConfigService
    {
        private readonly HttpClient _httpClient;
        private readonly IOAuth2Client _oauth2Client;
        private readonly ICachingService _cachingService;
        private readonly ILogger _logger;

        public ConfigService(HttpClient httpClient, IOAuth2Client oauth2Client, ICachingService cachingService, ILogger logger)
        {
            _httpClient = httpClient;
            _oauth2Client = oauth2Client;
            _cachingService = cachingService;
            _logger = logger;
        }

        public async Task<ConfigResponse> GetConfigAsync(string gameId)
        {
            var authResult = await _oauth2Client.AuthenticateAsync();
            if (!authResult.IsSuccess)
            {
                throw new Exception("Authentication failed");
            }

            var request = new HttpRequestMessage(HttpMethod.Get, $"https://api.example.com/config/{gameId}");
            request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", authResult.AccessToken);

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var configResponse = await response.Content.ReadAsJsonAsync<ConfigResponse>();
            return configResponse;
        }
    }

    public class ConfigResponse
    {
        public string GameId { get; set; }
        public string GameName { get; set; }
        public int GameVersion { get; set; }
    }

    public interface IConfigService
    {
        Task<ConfigResponse> GetConfigAsync(string gameId);
    }
}
