                // Simulate temperature sensor data
                return static_cast<double>(rand()) / RAND_MAX * (stdDev + 2 * mean);
            }
    };

    class HumiditySensorData : public SensorData {
        public:
            double generateData(double mean, double stdDev, double frequency) override {
                // Simulate humidity sensor data
                return static_cast<double>(rand()) / RAND_MAX * (stdDev + 2 * mean);
            }
    };

    class PressureSensorData : public SensorData {
        public:
            double generateData(double mean, double stdDev, double frequency) override {
                // Simulate pressure sensor data
                return static_cast<double>(rand()) / RAND_MAX * (stdDev + 2 * mean);
            }
    };

    class MotionSensorData : public SensorData {
        public:
            double generateData(double mean, double stdDev, double frequency) override {
                // Simulate motion sensor data
                return static_cast<double>(rand()) / RAND_MAX * (stdDev + 2 * mean);
            }
    };

    class AirQualitySensorData : public SensorData {
        public:
            double generateData(double mean, double stdDev, double frequency) override {
                // Simulate air quality sensor data
                return static_cast<double>(rand()) / RAND_MAX * (stdDev + 2 * mean);
            }
    };

    class NoiseLevelsSensorData : public SensorData {
        public:
            double generateData(double mean, double stdDev, double frequency) override {
                // Simulate noise levels sensor data
                return static_cast<double>(rand()) / RAND_MAX * (stdDev + 2 * mean);
            }
    };

    class Simulator {
        private:
            std::vector<SensorType*> sensors;
            std::mutex mtx;
            std::condition_variable cv;

            void generateData(double mean, double stdDev, double frequency) {
                for (auto& sensor : sensors) {
                    SensorData* data = dynamic_cast<SensorData*>(sensor);
                    if (data != nullptr) {
                        double value = data->generateData(mean, stdDev, frequency);
                        // Send data to external services or cloud
                    }
                }
            }

        public:
            Simulator() {}

            void addSensor(SensorType* sensor) {
                sensors.push_back(sensor);
            }

            void startSimulation(double mean, double stdDev, double frequency) {
                while (true) {
                    generateData(mean, stdDev, frequency);

                    // Wait for some time before generating next data point
                    std::this_thread::sleep_for(std::chrono::milliseconds(1000));
                }
            }
    };

    class AdaptiveSensorDataSimulator {
        public:
            Simulator* getSimulator() { return &simulator; }

