package com.example.inventory;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class InventoryService {
    private ExecutorService executor = Executors.newFixedThreadPool(5);

    public void updateInventory(String productId, int quantity) {
        // Send event to the inventory update service
        executor.submit(() -> {
            try {
                Thread.sleep(100);
                System.out.println("Updated product " + productId + " quantity: " + quantity);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });
    }

    public void subscribeToInventoryEvents(InventorEventListener listener) {
        // Register the event listener
        executor.submit(() -> {
            try {
                Thread.sleep(100);
                System.out.println("Notified " + listener.getClass().getSimpleName() + " about inventory changes");
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
        });
    }

    public interface InventorEventListener {
        void onInventoryUpdate(String productId, int quantity);
    }
}
