public:
    void send(Notification& notification) override {
        // Send push notification using push notification service
        std::cout << "Sent push notification: " << notification.content << std::endl;
    }
};

class InAppMessageChannel : public Channel {
public:
    void send(Notification& notification) override {
        // Send in-app message using in-app messaging framework
        std::cout << "Sent in-app message: " << notification.content << std::endl;
    }
};

