// Function to securely transmit data using OpenSSL
void sendSecureData(const std::string& data) {
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    SSL* ssl = SSL_new(ctx);

    // Establish a connection with the server
    int sockfd;
    struct hostent* he;
    struct sockaddr_in sa;

    he = gethostbyname("example.com");
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    sa.sin_family = AF_INET;
    sa.sin_port = htons(443);
    inet_pton(AF_INET, he->h_addr, &sa.sin_addr);

    connect(sockfd, (struct sockaddr *)&sa, sizeof(sa));

    // Send data securely
    SSL_set_fd(ssl, sockfd);
    int bytesSent = SSL_write(ssl, data.c_str(), data.length());
    if (bytesSent < 0) {
        std::cerr << "Error sending data: " << SSL_error_string() << std::endl;
    }

    // Close the connection
    SSL_shutdown(ssl);

    // Clean up
    SSL_free(ssl);
    SSL_CTX_free(ctx);
}

