from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
from uvicorn.main importUVicorn

class OrderEvent(BaseModel):
    id: str
    order_id: str
    status: str

class LogisticsProvider:
    def __init__(self, api_key: str):
        self.api_key = api_key
        self.session = aiohttp.ClientSession()

    async def get_order_status(self, order_id: str) -> Dict:
        url = f"https://logistics-api.com/{order_id}"
        headers = {"Authorization": f"Bearer {self.api_key}"}
        try:
            async with self.session.get(url, headers=headers) as response:
                if response.status == 200:
                    return await response.json()
                raise HTTPException(status_code=404)
        except Exception as e:
            logging.error(f"Error fetching order status: {e}")
            return {}

class PaymentGateway:
    def __init__(self):
        self.session = aiohttp.ClientSession()

    async def process_payment(self, order_id: str) -> Dict:
        url = f"https://payment-gateway.com/{order_id}"
        try:
            async with self.session.get(url) as response:
                if response.status == 200:
                    return await response.json()
                raise HTTPException(status_code=500)
        except Exception as e:
            logging.error(f"Error processing payment: {e}")
            return {}

class OrderProcessor:
    def __init__(self, logistics_provider: LogisticsProvider, payment_gateway: PaymentGateway):
        self.logistics_provider = logistics_provider
        self.payment_gateway = payment_gateway

    async def process_order(self, order_event: OrderEvent) -> None:
        if order_event.status == "new":
            try:
                order_status = await self.logistics_provider.get_order_status(order_event.order_id)
                if order_status["status"] == "delivered":
                    await self.payment_gateway.process_payment(order_event.order_id)
                else:
                    logging.info(f"Order {order_event.order_id} not delivered")
            except HTTPException as e:
                logging.error(f"Error processing order: {e}")

app = FastAPI()

@app.post("/orders/")
async def create_order(order_event: OrderEvent) -> None:
    await asyncio.create_task(OrderProcessor(logistics_provider, payment_gateway).process_order(order_event))

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8000)
