#include <stdio.h>
#include <stdlib.h>

int load_resource_bundle(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // Error: File not found or unable to open
    }

    fseek(file, 0, SEEK_END);
    size_t bundle_size = ftell(file);
    rewind(file);

    void* bundle = malloc(bundle_size);
    if (!bundle) {
        fclose(file); // Free resources in case of allocation failure
        return -2; // Error: Memory allocation failed
    }

    fread(bundle, 1, bundle_size, file);
    fclose(file);

    int item_count;
    if (fread(&item_count, sizeof(int), 1, file)) {
        printf("Bundle contains %d items.\n", item_count);
    } else {
        free(bundle); // Release resources in case of read failure
        return -3; // Error: Unable to read bundle count
    }

    return item_count;
}
