// Define a struct CellMeasurementReport
typedef struct {
    int id;
    float temperature;
    float humidity;
} CellMeasurementReport;

// Structure to hold CellMeasurementReports
typedef struct {
    size_t capacity;
    size_t size;
    CellMeasurementReport* reports;
} MeasurementCollection;

// Function to initialize MeasurementCollection
void measurement_collection_init(MeasurementCollection* collection, size_t initial_capacity) {
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->reports = (CellMeasurementReport*)malloc(initial_capacity * sizeof(CellMeasurementReport));
}

// Function to add a CellMeasurementReport to the collection
void measurement_collection_add(MeasurementCollection* collection, CellMeasurementReport report) {
    if (collection->size >= collection->capacity) {
        // Reallocate memory for increased capacity
        size_t new_capacity = collection->capacity * 2;
        CellMeasurementReport* new_reports = (CellMeasurementReport*)realloc(collection->reports, new_capacity * sizeof(CellMeasurementReport));
        if (!new_reports) {
            printf("Memory allocation failed.\n");
            exit(-1);
        }
        collection->reports = new_reports;
        collection->capacity = new_capacity;
    }
    memcpy(&collection->reports[collection->size], &report, sizeof(CellMeasurementReport));
    collection->size++;
}

// Function to retrieve a CellMeasurementReport from the collection
CellMeasurementReport* measurement_collection_get(MeasurementCollection* collection, int id) {
    for (int i = 0; i < collection->size; i++) {
        if (collection->reports[i].id == id) {
            return &collection->reports[i];
        }
    }
    return NULL;
}

// Function to remove a CellMeasurementReport from the collection
void measurement_collection_remove(MeasurementCollection* collection, int id) {
    for (int i = 0; i < collection->size; i++) {
        if (collection->reports[i].id == id) {
            // Shift all reports after the one being removed forward to fill the gap
            memmove(&collection->reports[i], &collection->reports[i + 1], (collection->size - i - 1) * sizeof(CellMeasurementReport));
            collection->size--;
        }
    }
}

// Function to release resources used by MeasurementCollection
void measurement_collection_free(MeasurementCollection* collection) {
    free(collection->reports);
    collection->reports = NULL;
}

int main() {
    // Initialize a MeasurementCollection with an initial capacity of 10
    MeasurementCollection measurement_collection;
    measurement_collection_init(&measurement_collection, 10);

    // Add some CellMeasurementReports to the collection
    CellMeasurementReport report1 = {1, 25.0f, 60.0f};
    CellMeasurementReport report2 = {2, 30.0f, 70.0f};
    measurement_collection_add(&measurement_collection, report1);
    measurement_collection_add(&measurement_collection, report2);

    // Retrieve and display a specific report
    CellMeasurementReport* retrieved_report = measurement_collection_get(&measurement_collection, 2);
    if (retrieved_report) {
        printf("Retrieved Report: ID %d, Temperature %.2f, Humidity %.2f\n", retrieved_report->id, retrieved_report->temperature, retrieved_report->humidity);
    } else {
