MeasurementReportManager *measurement_report_manager_init(size_t initial_capacity) {
    MeasurementReportManager *manager = (MeasurementReportManager *)malloc(sizeof(MeasurementReportManager));
    manager->lock = pthread_mutex_init(NULL, NULL);
    manager->reports = (CellMeasurementReport **)calloc(initial_capacity, sizeof(CellMeasurementReport *));
