// Function to add a cell measurement report to the manager
void measurement_report_manager_add(MeasurementReportManager *manager, CellMeasurementReport *report) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= sizeof(manager->reports) / sizeof(manager->reports[0])) {
        // Resize the array when it reaches capacity
        size_t new_capacity = manager->count + 16;
        void *new_reports = realloc(manager->reports, new_capacity * sizeof(CellMeasurementReport *));
        manager->reports = (CellMeasurementReport **)new_reports;
    }
    manager->reports[manager->count] = report;
    manager->count++;
    pthread_mutex_unlock(&manager->lock);
}

