    bool RX_UE_INFORMATION_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the cache data structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} CacheT;

// Initialize a new cache with given capacity
CacheT* cache_init(size_t capacity) {
    CacheT* cache = (CacheT*)malloc(sizeof(CacheT));
    cache->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    cache->capacity = capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

// Add an element to the cache
void cache_add(CacheT* cache, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&cache->lock);
    if (cache->count < cache->capacity) {
        cache->elements[cache->count] = *element;
        cache->count++;
    }
    pthread_mutex_unlock(&cache->lock);
}

// Get an element from the cache
NFAPI_CRC_INDICATION_PDU_T* cache_get(CacheT* cache, uint32_t RNTI) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->elements[i].RNTI == RNTI) {
            NFAPI_CRC_INDICATION_PDU_T* element = &cache->elements[i];
            pthread_mutex_unlock(&cache->lock);
            return element;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

// Update an element in the cache
void cache_update(CacheT* cache, uint32_t RNTI, NFAPI_CRC_INDICATION_PDU_T* new_element) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->elements[i].RNTI == RNTI) {
            cache->elements[i] = *new_element;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Delete an element from the cache
void cache_delete(CacheT* cache, uint32_t RNTI) {
    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->elements[i].RNTI == RNTI) {
            memmove(&cache->elements[i], &cache->elements[i + 1], (cache->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            cache->count--;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

// Free the cache and its elements
void cache_free(CacheT* cache) {
    free(cache->elements);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}
