CREATE PROCEDURE GetSupervisorEmployees @supervisorId INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @employees TABLE (EmployeeID INT, Name VARCHAR(50), Department VARCHAR(100));

    BEGIN TRY
        INSERT INTO @employees
        SELECT e.EmployeeID, e.Name, ed.DepartmentName
        FROM Employees e
        JOIN EmployeeDepartments ed ON e.EmployeeID = ed.EmployeeID
        WHERE e.SupervisorID = @supervisorId;

        IF @@ROWCOUNT > 0
            SELECT * FROM @employees;
        ELSE
            RAISERROR('Supervisor has no direct reports', 16, 1);

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000), @ErrorSeverity INT;
        SET @ErrorMessage = ERROR_MESSAGE();
        SET @ErrorSeverity = ERROR_SEVERITY();

        RAISERROR(@ErrorMessage, @ErrorSeverity, 1);
    END CATCH;

END

