import logging
from typing import List, Dict

class State:
    def __init__(self, id: int):
        self.id = id
        self.next: 'State' = None


def create_state_list(states: List[int], fsa: Dict[int, 'State'], last_state_id: int) -> 'State':
    state_list = None
    current_state = None

    for state_id in states:
        if not state_list:
            state_list = State(state_id)
            current_state = state_list
        else:
            next_state = fsa.get(state_id, None)
            if not next_state:
                return None  # FSA does not contain the given state
            current_state.next = next_state
            current_state = next_state

    if last_state_id != current_state.id:
        return None  # Last state ID mismatch

    current_state.next = None  # Set the 'next' pointer of the last state to None
    return state_list


def main():
    states = [1, 2, 3]
    fsa = {1: State(2), 2: State(3), 3: State(-1)}  # -1 indicates end of the list
    last_state_id = 3

    result = create_state_list(states, fsa, last_state_id)
    if not result:
        logging.error("Failed to create state list")
    else:
        logging.info(f"State list created successfully: {result.id}")


if __name__ == "__main__":
    main()
