const axios = require('axios');
const { setTimeout } = require('timers/promises');
const { performance } = require('perf_hooks');

class AsyncReducer {
  constructor(config) {
    this.config = config;
    this.metrics = [];
    this.state = config.initialState;
    this.callbacks = [];
    this.concurrentLimit = +process.env.CONCURRENCY_LIMIT || 100;
    this.requestInterval = +process.env.REQUEST_INTERVAL || 500;
    this.aggregationInterval = +process.env.AGGREGATION_INTERVAL || 1000;
  }

  async reduce(metrics, callback) {
    this.metrics = metrics;
    this.callbacks.push(callback);
    await this.fetchAndReduce();
  }

  async fetchAndReduce() {
    const concurrency = Math.min(this.concurrentLimit, this.metrics.length);
    for (let i = 0; i < concurrency; i++) {
      const metricId = this.metrics.shift();
      if (!metricId) break;
      try {
        const metadata = await this.fetchMetricMetadata(metricId);
        this.state = this.applyReducer(metadata, this.state);
      } catch (error) {
        console.error(`Error fetching or reducing metric ${metricId}:`, error);
        await this.handleError(error);
      }
    }
    if (this.metrics.length > 0) {
      setTimeout(() => this.fetchAndReduce(), this.requestInterval);
    } else {
      this.callbacks.forEach((callback) => callback(this.state));
    }
  }

  async fetchMetricMetadata(metricId) {
    try {
      const response = await axios.get(`https://api.monitoring.cloud/${metricId}`);
      return response.data;
    } catch (error) {
      if (error.code === 'ECONNREFUSED') {
        await this.backoff();
        return await this.fetchMetricMetadata(metricId);
      }
      throw error;
    }
  }

  async backoff() {
    const maxAttempts = +process.env.MAX_ATTEMPTS || 5;
    for (let attempts = 0; attempts < maxAttempts; attempts++) {
      if (attempts > 0) {
        await setTimeout(Math.pow(2, attempts), 'backoff');
      }
      try {
        return await this.fetchMetricMetadata();
      } catch (error) {
        if (attempts >= maxAttempts - 1) {
          throw error;
        }
      }
    }
  }

  async handleError(error) {
    console.error('Error handling reduction:', error);
    performance.getEntriesByName('handleError').forEach((entry) => entry.delete());
  }

  applyReducer(metadata, state) {
    // implement your reducer logic here
  }
}

module.exports = AsyncReducer;
