```go
package main

import (
	"context"
	"fmt"
	"log"
	"sync"

	"github.com/olivere/elastic/v7"
)

type LogEntry struct {
	Timestamp int64  `json:"timestamp"`
	Sender    string `json:"sender"`
	Message   string `json:"message"`
}

func processLogEntries(ctx context.Context, logChan chan<- LogEntry) {
	elasticClient := elastic.NewClient()
	esIndex := "logs"

	for logEntry := range logChan {
		fmt.Println("Processing log entry:", logEntry)

		if err := sendToElastic(logEntry, elasticClient, esIndex); err != nil {
			log.Println(err)
		}
	}

	log.Println("Exiting the processLogEntries function")
}

func sendToElastic(logEntry LogEntry, client *elastic.Client, index string) error {
	ctx := context.Background()
	p, err := client.Index().
		Index(index).
		Type("_doc").
		BodyJson(logEntry).
		Do(ctx)
	if err != nil {
		return err
	}
	fmt.Println("Logged successfully:", p.Id())
	return nil
}

func main() {
	logChan := make(chan LogEntry)

	go processLogEntries(context.Background(), logChan)

	// Simulate receiving log entries and send them to the channel
	for i := 0; i < 10; i++ {
		logEntry := LogEntry{
			Timestamp: int64(i),
			Sender:    "sender-" + fmt.Sprintf("%d", i),
			Message:   fmt.Sprintf("Log message - %d", i),
		}
		logChan <- logEntry
		time.Sleep(time.Second)
	}

	close(logChan)
}
```

This function takes a channel of `LogEntry` type, processes each entry, and sends it to Elasticsearch using the Elastic library.']

