import asyncio
from typing import Dict, List

class EventMessage:
    def __init__(self, data: Dict):
        self.data = data
        self.priority = data.get("priority", 0)

class MessagingSystem:
    def __init__(self):
        self.ingestion_queue = asyncio.Queue()
        self.filter_queue = asyncio.Queue()
        self.storage_queue = asyncio.Queue()

    async def ingest(self, event: EventMessage):
        await self.ingestion_queue.put(event)

    async def filter(self, event: EventMessage):
        # implement rule engine here
        if event.priority > 5:
            await self.filter_queue.put(event)
        else:
            await self.storage_queue.put(event)

    async def store(self, event: EventMessage):
        # integrate with storage system here
        print(f"Stored {event.data}")

    def run(self):
        while True:
            event = await self.ingestion_queue.get()
            await self.filter(event)
            if not self.filter_queue.empty():
                for f_event in asyncio.as_completed([self.filter_queue.get() for _ in range(100)]):
                    await self.store(f_event)
