use tokio::runtime::Builder;

async fn compile_with_metrics(code: &str) -> Result<(), Box<dyn std::error::Error>> {
    let start = Instant::now();
    // Initialize thread pool
    let rt = Builder::new_multi_thread().enable_all().build()?;

    // Compile code using Rust compiler
    let mut cmd = Command::new("rustc")
        .arg("--crate-type=bin")
        .arg("--out-dir=.") 
        .arg(code);
    let output = rt.block_on(cmd.output())?;

    // Extract metrics from compilation process
    let compile_time = start.elapsed().as_millis();
    let memory_usage = get_memory_usage()?;
    let error_rate = calculate_error_rate(&output.stdout, &output.stderr)?;

    // Log and monitor performance metrics
    log_compile_metrics(compile_time, memory_usage, error_rate);

    // Adjust resource allocation based on historical data
    adjust_resources();

    // Serialize and send metrics to message broker
    serialize_and_send_metrics(message_broker_url(), compile_time, memory_usage, error_rate).await?;

    Ok(())
}

fn get_memory_usage() -> Result<(), Box<dyn std::error::Error>> {
    // Get system memory usage using sysfs or /proc/meminfo
    let mut file = File::open("/sys/fs/cgroup/memory/memory.usage")?;
    let mut buffer = String::new();
    file.read_to_string(&mut buffer)?;
    // Parse and return memory usage as a percentage
    Ok(())
}

fn calculate_error_rate(stdout: &[u8], stderr: &[u8]) -> Result<(), Box<dyn std::error::Error>> {
    // Calculate error rate based on stdout and stderr contents
    let error_count = count_errors(stdout, stderr)?;
    let total_operations = count_total_operations(stdout, stderr)?;
    // Return error rate as a percentage
    Ok(())
}

fn log_compile_metrics(compile_time: u128, memory_usage: f64, error_rate: f64) {
