// Structure to represent a CellMeasurementReport
typedef struct {
    int cell_id;
    double rsrp;
    double rsrq;
} CellMeasurementReport;

// Cache structure with in-memory and disk-based storage
typedef struct {
    // In-memory cache
    pthread_mutex_t lock;
    CellMeasurementReport* reports[100]; // Assuming max 100 reports per cell
    int report_count;

    // Disk-based cache (for persistence)
    FILE* file;
} Cache;

// Initialize the cache with in-memory and disk-based storage
void init_cache(Cache* cache) {
    pthread_mutex_init(&cache->lock, NULL);
    cache->report_count = 0;
    cache->file = fopen("report_cache.bin", "wb+");
}

// Add a report to the cache
void add_report(Cache* cache, CellMeasurementReport* report) {
    pthread_mutex_lock(&cache->lock);

    // Check if cell ID already exists
    int i;
    for (i = 0; i < cache->report_count; i++) {
        if (cache->reports[i]->cell_id == report->cell_id) {
            break;
        }
    }

    if (i >= cache->report_count) {
        // Add new cell ID
        cache->reports[cache->report_count] = report;
        cache->report_count++;
    } else {
        // Update existing report
        memcpy(cache->reports[i], report, sizeof(CellMeasurementReport));
    }

    pthread_mutex_unlock(&cache->lock);
}

// Get the average signal quality for a cell ID
double get_average_signal_quality(Cache* cache, int cell_id) {
    pthread_mutex_lock(&cache->lock);

    // Find reports for given cell ID
    CellMeasurementReport* report = NULL;
    int i;
    for (i = 0; i < cache->report_count; i++) {
        if (cache->reports[i]->cell_id == cell_id) {
            report = cache->reports[i];
            break;
        }
    }

    double rsrp_sum = 0.0;
    double rsrq_sum = 0.0;

    // Calculate average signal quality
    if (report) {
        int count = 1;
        while (i < cache->report_count && cache->reports[i]->cell_id == cell_id) {
            rsrp_sum += report->rsrp;
            rsrq_sum += report->rsrq;
            i++;
            count++;
        }
        rsrp_sum /= count;
        rsrq_sum /= count;
    }

    pthread_mutex_unlock(&cache->lock);

    return (rsrp_sum + rsrq_sum) / 2.0; // Average signal quality
}

// Remove a report from the cache
void remove_report(Cache* cache, int cell_id) {
    pthread_mutex_lock(&cache->lock);

    // Find reports for given cell ID
    CellMeasurementReport* report = NULL;
    int i;
    for (i = 0; i < cache->report_count; i++) {
        if (cache->reports[i]->cell_id == cell_id) {
            report = cache->reports[i];
            break;
        }
    }

    // Remove reports
    if (report) {
        int j;
        for (j = i; j < cache->report_count - 1; j++) {
            cache->reports[j] = cache->reports[j + 1];
        }
        cache->report_count--;
    }

    pthread_mutex_unlock(&cache->lock);
}

// Cache operations with concurrency control
void* cache_operations(void* arg) {
    // Thread-safe cache operations
    Cache* cache = (Cache*)arg;
    int operation_type; // 0: add, 1: get, 2: remove

    while (1) {
        pthread_mutex_lock(&cache->lock);
        // Perform cache operation based on operation_type
        if (operation_type == 0) {
            // Add report
            add_report(cache, (CellMeasurementReport*)arg);
        } else if (operation_type == 1) {
            // Get average signal quality
            double result = get_average_signal_quality(cache, *(int*)arg);
            pthread_mutex_unlock(&cache->lock);
            return &result;
        } else if (operation_type == 2) {
            // Remove report
            remove_report(cache, *(int*)arg);
        }
        pthread_mutex_unlock(&cache->lock);
    }
}

int main() {
    Cache cache;
    init_cache(&cache);

    // Create threads for concurrent cache operations
    pthread_t threads[3];
    int i;
    for (i = 0; i < 3; i++) {
        pthread_create(&threads[i], NULL, cache_operations, &cache);
    }

    return 0;
}
```

This code provides a basic framework for the task. It includes functions to add, update, and remove reports from the cache, as well as calculate the average signal quality for specific cells. The cache is designed with in-memory and disk-based storage, and it uses read-write locks for concurrency control.']

