use std::thread;
use std::sync::{Arc, Mutex};
use std::collections::{HashMap, VecDeque};
use reqwest;

struct Command {
    id: u64,
    endpoint: String,
    data: HashMap<String, String>,
    priority: i32,
}

impl Command {
    fn new(id: u64, endpoint: &str, data: &HashMap<String, String>, priority: i32) -> Self {
        Command { id, endpoint: endpoint.to_string(), data: data.clone(), priority }
    }
}

struct Executor {
    commands: VecDeque<Command>,
    api_endpoints: HashMap<String, reqwest::Client>,
    load_balancer: Arc<Mutex<LoadBalancer>>,
    metrics: Arc<Mutex<Metrics>>,
}

impl Executor {
    fn new() -> Self {
        Executor {
            commands: VecDeque::new(),
            api_endpoints: HashMap::new(),
            load_balancer: Arc::new(Mutex::new(LoadBalancer::new())),
            metrics: Arc::new(Mutex::new(Metrics::new())),
        }
    }

    fn add_command(&mut self, command: Command) {
        self.commands.push_back(command);
    }

    fn execute_commands(&self) {
        let mut commands = self.commands.drain().collect::<Vec<Command>>();
        let load_balancer = Arc::clone(&self.load_balancer);
        let metrics = Arc::clone(&self.metrics);

        for command in commands {
            if let Some(api_endpoint) = &mut *load_balancer.lock().unwrap().get_api_endpoint(command.endpoint.clone()) {
                if let Err(err) = api_endpoint.post(&command.data).await {
                    println!("Error executing command {}: {}", command.id, err);
                }
            } else {
                println!("No API endpoint found for command {}: {}", command.id, command.endpoint);
            }
        }

        *metrics.lock().unwrap() = Metrics::new();
    }
}

struct LoadBalancer {
    api_endpoints: HashMap<String, reqwest::Client>,
}

impl LoadBalancer {
    fn new() -> Self {
        LoadBalancer { api_endpoints: HashMap::new() }
    }

    fn get_api_endpoint(&self, endpoint: String) -> &mut Option<reqwest::Client> {
        self.api_endpoints.entry(endpoint).or_insert(Some(reqwest::Client::new()))
    }
}

struct Metrics {
    cpu_usage: f64,
    memory_usage: f64,
    network_latency: f64,
}

impl Metrics {
    fn new() -> Self {
        Metrics { cpu_usage: 0.0, memory_usage: 0.0, network_latency: 0.0 }
    }
}

fn main() {
    let mut executor = Executor::new();

    // Start a separate thread for command execution
