public class SecureDataPipeline
{
    public async Task ProcessAsync(string data)
    {
        // Determine encryption algorithm based on header information and metadata
        EncryptionAlgorithm algorithm = GetEncryptionAlgorithm(data);

        // Decrypt the data using the selected algorithm
        byte[] decryptedData = Decrypt(data, algorithm);

        // Process the decrypted data
        await ProcessDecryptedData(decryptedData);
    }

    private EncryptionAlgorithm GetEncryptionAlgorithm(string data)
    {
        // Extract header information and metadata from the cloud-based storage service
        string algoHeader = ExtractAlgoHeader(data);
        return GetAlgorithmFromMetadata(algoHeader);
    }

    private byte[] Decrypt(byte[] data, EncryptionAlgorithm algorithm)
    {
        // Use the selected algorithm to decrypt the data
        using (Aes aes = Aes.Create())
        {
            aes.Key = Guid.NewGuid().ToByteArray();
            aes.IV = Guid.NewGuid().ToByteArray();

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
            return Transform(data, decryptor);
        }
    }

    private byte[] Transform(byte[] data, ICryptoTransform transform)
    {
        using (MemoryStream ms = new MemoryStream())
        {
            CryptoStream cs = new CryptoStream(ms, transform, CryptoStreamMode.Write);
            cs.Write(data, 0, data.Length);
            cs.FlushFinalBlock();
            return ms.ToArray();
        }
