    public class ImageUploadProcessor
    {
        private readonly ICloudStorageProvider _cloudStorageProvider;
        private readonly ICDNProvider _cdnProvider;
        private readonly IImageTransformer _imageTransformer;

        public ImageUploadProcessor(
            ICloudStorageProvider cloudStorageProvider,
            ICDNProvider cdnProvider,
            IImageTransformer imageTransformer)
        {
            _cloudStorageProvider = cloudStorageProvider;
            _cdnProvider = cdnProvider;
            _imageTransformer = imageTransformer;
        }

        public async Task UploadAndTransformAsync(
            byte[] imageBuffer,
            string originalFileName,
            string transformedFileName)
        {
            // Upload the image to cloud storage
            await _cloudStorageProvider.UploadAsync(imageBuffer, originalFileName);

            // Transform the image using the transformer
            var transformedImage = await _imageTransformer.TransformAsync(imageBuffer);

            // Store the transformed image in cloud storage
            await _cloudStorageProvider.StoreTransformedAsync(transformedImage, transformedFileName);

            // Deliver the transformed image through the CDN
            await _cdnProvider.DistributeAsync(transformedImage);
        }
    }

    public interface ICloudStorageProvider
    {
        Task UploadAsync(byte[] buffer, string fileName);
        Task StoreTransformedAsync(byte[] buffer, string fileName);
    }

    public interface ICDNProvider
    {
        Task DistributeAsync(byte[] buffer);
    }

    public interface IImageTransformer
    {
        Task<byte[]> TransformAsync(byte[] buffer);
    }
}
