#include <mutex>

// Define CellMeasurementReport structure
struct CellMeasurementReport {
    std::string cellId;
    int rsrp;
    int rsrq;
};

class MeasurementLibrary {
public:
    // Constructor to initialize the library
    MeasurementLibrary() : cache_(std::make_shared<std::map<std::string, CellMeasurementReport>>()) {}

    // Add a new report to the collection
    void addReport(const std::string& cellId, int rsrp, int rsrq) {
        auto report = CellMeasurementReport{cellId, rsrp, rsrq};
        cache_->insert({cellId, report});
    }

    // Update an existing report in the collection
    void updateReport(const std::string& cellId, int rsrp, int rsrq) {
        if (cache_->find(cellId) != cache_->end()) {
            auto &report = cache_->at(cellId);
            report.rsrp = rsrp;
            report.rsrq = rsrq;
        }
    }

    // Remove a report from the collection
    void removeReport(const std::string& cellId) {
        if (cache_->find(cellId) != cache_->end()) {
            cache_->erase(cellId);
        }
    }

    // Calculate average signal quality for specific cells
    double calculateAverageSignalQuality(const std::vector<std::string>& cellIds) {
        double sumRsrp = 0;
        double sumRsrq = 0;
        int count = 0;

        for (const auto& cellId : cellIds) {
            if (cache_->find(cellId) != cache_->end()) {
                const auto &report = cache_->at(cellId);
                sumRsrp += report.rsrp;
                sumRsrq += report.rsrq;
                count++;
            }
        }

        return (count > 0) ? (sumRsrp / count + sumRsrq / count) : 0.0;
    }

private:
    std::shared_ptr<std::map<std::string, CellMeasurementReport>> cache_;
};

// Function to create a new directory with a given name and set an environment variable
void createDirectory(const std::string& directoryName) {
    auto envVar = "DIRECTORY_PATH";
    if (std::getenv(envVar.c_str())) {
        // Environment variable is already set, use the existing value
        return;
    }

    try {
        // Create a new directory with the given name
        std::ofstream file(directoryName);
        file.close();

        // Set the environment variable to the path of the directory
        auto directoryPath = directoryName;
        setenv(envVar.c_str(), directoryPath.c_str(), 1);
    } catch (const std::exception& e) {
        // Handle potential errors gracefully, ensuring the system remains robust under various conditions
        std::cerr << "Error creating directory: " << e.what() << std::endl;
    }
}

int main() {
    MeasurementLibrary library;

    // Add reports to the collection
    library.addReport("cell1", 10, 20);
    library.addReport("cell2", 15, 30);

    // Update a report in the collection
    library.updateReport("cell1", 12, 25);

    // Remove a report from the collection
    library.removeReport("cell2");

    // Calculate average signal quality for specific cells
    std::vector<std::string> cellIds = {"cell1"};
    double averageSignalQuality = library.calculateAverageSignalQuality(cellIds);
    std::cout << "Average signal quality: " << averageSignalQuality << std::endl;

    return 0;
}

