#include <arpa/inet.h>
#include <pthread.h>

#define REPORT_MAX_SIZE 1024

// Forward declarations
void* report_thread(void* arg);
int send_request(int sockfd, char* request);

// Cell measurement report structure
typedef struct {
    int cell_id;
    double rsrp;
    double rsrq;
} CellMeasurementReport;

// Report manager
typedef struct {
    pthread_mutex_t lock;
    CellMeasurementReport** reports;
    int report_count;
} ReportManager;

// Initialize the report manager
void init_report_manager(ReportManager* rm) {
    pthread_mutex_init(&rm->lock, NULL);
    rm->reports = (CellMeasurementReport**)malloc(REPORT_MAX_SIZE * sizeof(CellMeasurementReport*));
    rm->report_count = 0;
}

// Add a cell measurement report to the report manager
void add_report(ReportManager* rm, CellMeasurementReport* report) {
    pthread_mutex_lock(&rm->lock);
    rm->reports[rm->report_count++] = report;
    pthread_mutex_unlock(&rm->lock);
}

// Calculate average signal quality metrics for all reports
double calculate_average_signal_quality(ReportManager* rm) {
    double rsrp_sum = 0, rsrq_sum = 0;
    int count = 0;

    pthread_mutex_lock(&rm->lock);
    for (int i = 0; i < rm->report_count; i++) {
        CellMeasurementReport* report = rm->reports[i];
        rsrp_sum += report->rsrp;
        rsrq_sum += report->rsrq;
        count++;
    }
    pthread_mutex_unlock(&rm->lock);

    if (count == 0) return -1;

    return (rsrp_sum / count + rsrq_sum / count) / 2.0;
}

// Main function
int main() {
    ReportManager rm;
    init_report_manager(&rm);

    // Add some sample reports
    CellMeasurementReport* report1 = (CellMeasurementReport*)malloc(sizeof(CellMeasurementReport));
    report1->cell_id = 1; report1->rsrp = 10.5; report1->rsrq = -5.2;
    add_report(&rm, report1);

    CellMeasurementReport* report2 = (CellMeasurementReport*)malloc(sizeof(CellMeasurementReport));
    report2->cell_id = 2; report2->rsrp = 12.3; report2->rsrq = -6.7;
    add_report(&rm, report2);

    // Calculate average signal quality metrics
    double avg_signal_quality = calculate_average_signal_quality(&rm);
    printf("Average signal quality: %f\n", avg_signal_quality);

    return 0;
}

void* report_thread(void* arg) {
    int sockfd = *(int*)arg;

    // Send requests to the RESTful API
    char request[] = "GET /api/measurement-reports HTTP/1.1";
    send_request(sockfd, request);

    free((int*)arg);
    return NULL;
}

int send_request(int sockfd, char* request) {
    int bytes_sent = send(sockfd, request, strlen(request), 0);
    if (bytes_sent == -1) {
        perror("Error sending request");
        return -1;
    }
    return bytes_sent;
}
