// Function to dynamically initialize and manage array of structures
void* handleNFAApiIndications(int num_nodes) {
    // Initialize lock
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize retry limit and backoff time
    int max_retries = 5;
    int retry_backoff_time = 1000; // in milliseconds

    // Initialize CRC validation function pointer
    void (*validate_crc)(void*) = NULL;

    // Initialize logging function pointer
    void (*log_message)(char*, ...) = NULL;

    // Dynamically allocate array of structures
    NFAPI_CRC_INDICATION_PDU_T** nfa_api_indications = 
        (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_nodes * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!nfa_api_indications) {
        // Handle allocation failure
        log_message("Allocation failure for NFAPI CRC indications\n");
        return NULL;
    }

    // Initialize and validate each structure in the array
    for (int i = 0; i < num_nodes; i++) {
        nfa_api_indications[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!nfa_api_indications[i]) {
            // Handle allocation failure
            log_message("Allocation failure for NFAPI CRC indication %d\n", i);
            continue;
        }

        // Initialize structure and validate its CRC
        nfa_api_indications[i]->crc = 0;
        validate_crc(nfa_api_indications[i]);
    }

    return nfa_api_indications;
}

