    for (size_t i = 0; i < offsetSize; ++i) {
        offsets[i] = i;
    }
    for (size_t i = 0; i < keySize; ++i) {
        keys[i] = (char)(rand() % 256);
    }

    // Return a pointer to the initialized database structure
    return reinterpret_cast<void*>(records.get());
}

