#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define the semaphore structure
typedef struct {
    sem_t lock;
    int value; // Initial value of the semaphore
    pthread_mutex_t mutex; // Mutex for synchronization
} Semaphore;

// Function to create a new semaphore with initial value
Semaphore* semaphore_create(int value) {
    Semaphore *sem = (Semaphore*)malloc(sizeof(Semaphore));
    sem->value = value;
    if (sem_init(&sem->lock, 0, value) == -1) {
        // Handle error
    }
    pthread_mutex_init(&sem->mutex, NULL);
    return sem;
}

// Function to acquire the semaphore
void semaphore_acquire(Semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem_getvalue(&sem->lock, &sem->value) == -1) {
        // Handle error
    }
    if (sem_wait(&sem->lock) == -1) {
        // Handle error
    }
    pthread_mutex_unlock(&sem->mutex);
}

// Function to release the semaphore
void semaphore_release(Semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    sem_post(&sem->lock);
    pthread_mutex_unlock(&sem->mutex);
}

// Function to destroy the semaphore
void semaphore_destroy(Semaphore *sem) {
    sem_destroy(&sem->lock);
    pthread_mutex_destroy(&sem->mutex);
    free(sem);
}

int main() {
    // Create a new semaphore with initial value 5
    Semaphore* sem = semaphore_create(5);

    // Acquire the semaphore
    semaphore_acquire(sem);

    // Release the semaphore
    semaphore_release(sem);

    // Destroy the semaphore
    semaphore_destroy(sem);

    return 0;
}
