// TIFF metadata structure
typedef struct {
    uint16_t byteOrder;
    uint16_t Reserved1;
    uint32_t offsetToFirstIFD;
} TIFFHeader;

// IFD (Image File Directory) metadata structure
typedef struct {
    uint32_t tag;
    uint16_t type;
    union {
        uint32_t val;
        char *str;
    } data;
    uint16_t count;
    uint16_t Reserved1;
    uint16_t Reserved2;
} IFDMetadata;

// Module API: initialize TIFF parser
void tiff_parser_init();

// Module API: parse a single TIFF file
int tiff_parse_file(const char* filename, char** metadata);

// Module API: extract specific metadata from parsed image
char* tiff_get_metadata(const char* metadata, uint16_t tag);

// Module API: free allocated memory and close the parser
void tiff_parser_free();

// Concurrent processing routine
void* tiff_parse_files(void* arg);

// Main function to parse multiple TIFF files concurrently
int main() {
    // Initialize parser
    tiff_parser_init();

    // Parse multiple TIFF files concurrently
    pthread_t threads[2];
    for (int i = 0; i < 2; i++) {
        if (pthread_create(&threads[i], NULL, tiff_parse_files, "file1.tif") != 0) {
            return -1;
        }
        if (pthread_create(&threads[i + 1], NULL, tiff_parse_files, "file2.tif") != 0) {
            return -1;
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory and close the parser
    tiff_parser_free();

    return 0;
}

// Memory-mapped I/O function
void* mmap_file(const char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        return NULL;
    }

    void* map = mmap(NULL, getpagesize(), PROT_READ, MAP_SHARED, fd, 0);
    close(fd);
    return map;
}

