    time_t expirationTime;

    CacheEntry(std::string val, time_t expirTime)
        : value(val), expirationTime(expirTime) {}
};

class DNSCache {
private:
    std::mutex mutex;
    std::map<std::string, CacheEntry> cache;
    int maxEntries = 1000; // configurable
    time_t cacheExpiration = 300; // configurable in seconds

public:
    void addProvider(DNSProvider* provider) {
        // implement provider management logic
    }

    void query(const std::string& domain, DNSProvider* provider) {
        // handle concurrent access using mutex
        std::lock_guard<std::mutex> lock(mutex);

        auto it = cache.find(domain);
        if (it != cache.end() && time(nullptr) <= it->second.expirationTime) {
            // cache hit
            return;
        }

        // query provider and update cache
        auto result = provider->query(domain);
        CacheEntry entry(result.first, time(nullptr) + cacheExpiration);
        cache[domain] = entry;

        if (cache.size() > maxEntries) {
            // implement LRU eviction policy or caching strategy
        }
    }

    void logStats() {
