    FSAStateMachine(std::function<void(const State&)> on_state_change) : on_state_change_(on_state_change), current_state_(State::START) {}

    void set_state(State new_state) {
        if (new_state != current_state_) {
            on_state_change_(current_state_);
            current_state_ = new_state;
            on_state_change_(new_state);
        }
    }

private:
    std::function<void(const State&)> on_state_change_;
    State current_state_;
};

