void initializeDatabase(size_t numRecords) {
    srand(time(0)); // Seed random number generator
    std::vector<offset> offsets;
    std::vector<key> keys;

    for (size_t i = 0; i < numRecords; i++) {
        offset tempOffset;
        key tempKey;

        // Generate unique values for offset and key
        tempOffset = generateRandomOffset();
        tempKey = generateRandomKey();

        offsets.push_back(tempOffset);
        keys.push_back(tempKey);
    }

    // Initialize records array with random values
    std::vector<CellMeasurementReport> records(numRecords);

    for (size_t i = 0; i < numRecords; i++) {
        CellMeasurementReport report;
        report.offset = offsets[i];
        report.key = keys[i];
        report.value = generateRandomValue();

        records[i] = report;
    }
}

offset generateRandomOffset() {
    // Generate random offset value
    return (offset){rand(), rand()};
}

key generateRandomKey() {
    // Generate random key value
    return (key){rand(), rand()};
}

float generateRandomValue() {
    // Generate random float value
    return (float)rand() / RAND_MAX;
}
