// Custom semaphore structure
typedef struct {
    pthread_mutex_t lock;
    int value;
} my_semaphore;

// Initialize a custom semaphore with an initial value
my_semaphore* init_semaphore(int value) {
    my_semaphore* sem = (my_semaphore*) malloc(sizeof(my_semaphore));
    sem->value = value;
    pthread_mutex_init(&sem->lock, NULL);
    return sem;
}

// P operation on the custom semaphore: decrement and wait if necessary
void down(my_semaphore* sem) {
    pthread_mutex_lock(&sem->lock);
    if (--sem->value <= 0) {
        // Wait until the semaphore is released
        while (sem->value == 0) {
            sleep(1); // Simulate a delay for demonstration purposes
        }
    }
    pthread_mutex_unlock(&sem->lock);
}

// V operation on the custom semaphore: increment and notify if necessary
void up(my_semaphore* sem) {
    pthread_mutex_lock(&sem->lock);
    ++sem->value;
    pthread_mutex_unlock(&sem->lock);
}

