// Video Streaming Platform
package com.videoStreaming;

import java.util.*;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.web.reactive.function.server.*;

@SpringBootApplication
public class VideoStreamingPlatform {
    public static void main(String[] args) {
        SpringApplication.run(VideoStreamingPlatform.class, args);
    }

    @Bean
    public RouterFunction<ServerResponse> router() {
        return RouterFunctions.route(
            GET("/videos/{id}").and(accept(MediaType.APPLICATION_STREAM)),
            (request, response) -> Stream.of(videos.stream())
                .filter(video -> video.getId().equals(request.pathVariable("id")))
                .findFirst()
                .map(video -> response.body(video))
                .orElse(response.status(HttpStatus.NOT_FOUND).build())
        );
    }

    @Bean
    public ServerApiExchangeFunction videoStream() {
        return exchange -> Stream.of(videos.stream())
            .filter(video -> video.isLive())
            .findFirst()
            .map(video -> new ResponseEntity<>(video, HttpStatus.OK))
            .orElse(new ResponseEntity<>(HttpStatus.NOT_FOUND));
    }

    @Bean
    public ServerApiExchangeFunction onDemandVideo() {
        return exchange -> Stream.of(videos.stream())
            .filter(video -> !video.isLive())
            .findFirst()
            .map(video -> new ResponseEntity<>(video, HttpStatus.OK))
            .orElse(new ResponseEntity<>(HttpStatus.NOT_FOUND));
    }

    private List<Video> videos = Arrays.asList(
        // sample video data
        new Video("1", "Video 1", true),
        new Video("2", "Video 2", false)
    );

    public class Video {
        String id;
        String title;
        boolean isLive;

        public Video(String id, String title, boolean isLive) {
            this.id = id;
            this.title = title;
            this.isLive = isLive;
        }
    }
}
