    // Check if the report count is less than capacity
    if (reports->reportCount < reports->reports->capacity) {
        CellMeasurementReport* newReport = &reports->reports[reports->reportCount];
        newReport->cellId = cellId;
        newReport->rsrp = rsrp;
        newReport->rsrq = rsrq;
        reports->reportCount++;
    } else {
        // Handle report overflow
        printf("Reports array is full. Cannot add more reports.\n");
    }
    pthread_mutex_unlock(&reports->lock);
}

// Calculate average signal quality metrics (RSRP and RSRQ) for specific cells
double calculate_average_signal_quality(CellMeasurementReports* reports, int cellId) {
    // Find the report count for the specified cell ID
    size_t index = 0;
    while (index < reports->reportCount && reports->reports[index].cellId != cellId) {
        index++;
    }

    if (index >= reports->reportCount) return -1.0; // Cell not found

    double sumRsrp = 0.0, sumRsrq = 0.0;
    size_t count = 0;
    for (; index < reports->reportCount && reports->reports[index].cellId == cellId; index++) {
        sumRsrp += reports->reports[index].rsrp;
        sumRsrq += reports->reports[index].rsrq;
        count++;
    }

    if (count > 0) {
        return (sumRsrp / count, sumRsrq / count);
    } else {
        return -1.0; // No reports found for the cell
    }
}

// Remove a cell measurement report from the collection
void remove_report(CellMeasurementReports* reports, int cellId) {
    pthread_mutex_lock(&reports->lock);

    // Find the report index for the specified cell ID
    size_t index = 0;
    while (index < reports->reportCount && reports->reports[index].cellId != cellId) {
        index++;
    }

    if (index >= reports->reportCount) {
        printf("Cell not found in reports.\n");
        pthread_mutex_unlock(&reports->lock);
        return;
    }

    // Remove the report and shift remaining reports
    for (; index < reports->reportCount - 1; index++) {
        reports->reports[index] = reports->reports[index + 1];
    }
    reports->reportCount--;

    pthread_mutex_unlock(&reports->lock);
}

// Function to integrate with an external logging system to capture and report errors or warnings
void log_report(CellMeasurementReports* reports, int cellId) {
    // Implement logging functionality
}

// Main function for initializing the library and managing reports
int main() {
    CellMeasurementReports* reports = init_reports(1000000); // Initialize with capacity 10 million

    while (1) {
        // Handle incoming reports from external sources
        add_report(reports, /* cellId */, /* rsrp */, /* rsrq */);

        // Calculate average signal quality metrics for specific cells
        double average_signal_quality = calculate_average_signal_quality(reports, /* cellId */);

        // Remove expired or outdated reports
        remove_report(reports, /* cellId */);
    }

    return 0;
}
